ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, display_name = EXCLUDED.display_name, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, total_stories = EXCLUDED.total_stories, total_words = EXCLUDED.total_words;

INSERT INTO public.sample_stories (id, source_key, author_id, title, content, starter_sentence, word_count, time_mode, mode, is_hardcore, created_at)
SELECT id, source_key, author_id, title, content, starter_sentence, word_count, time_mode, mode, is_hardcore, created_at FROM jsonb_to_recordset($collection$[{"id":"90fd8e18-a355-5fe3-bf38-a104eb0a2915","source_key":"sample-story-90fd8e18-a355-5fe3-bf38-a104eb0a2915","author_id":"eadfc958-d5fc-541b-8a17-0b53c62c7cac","title":"Last kick","content":"We kept playing because Leon said the next goal wins and then he scored but it was offside, except you can't really be offside with four people and a dog. So then Josh scored. I mean Leon again. I was in goal and the light had gone so I heard it hit the metal fence but didn't see where. We'd moved the jumpers already becuase the council guy was mowing the other bit and now nobody agreed how wide the goal was. My phone was buzzing inside my shoe. Mum probably. Leon hit it so hard the ball got through the broken fence into the private tennis bit. He said we could climb. I said he could climb. The lights in the tennis place came on and there was a man already holding our ball.","starter_sentence":"A match continues after everyone should go home.","word_count":135,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-07-24T14:03:20Z"},{"id":"934c1eb7-5900-531b-8abb-c3ff20f81bd7","source_key":"sample-story-934c1eb7-5900-531b-8abb-c3ff20f81bd7","author_id":"eadfc958-d5fc-541b-8a17-0b53c62c7cac","title":"the bridge","content":"The bridge was only two planks and both of them moved when I put my foot down. Connor said don't look down which made me look down. It wasn't even that far. Just a ditch with nasty water and a trolley in it. He jumped and and landed on the other side and then came back because he'd forgot his bag. Now I had to go first AGAIN. I took a run up but stopped so late my foot went through the mud and I lost the trainer. Left one. It just stayed there like it was someone's foot.","starter_sentence":"A shortcut turns out longer.","word_count":99,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-07-24T15:06:15Z"},{"id":"d3ab66b8-de78-5b15-ae93-f020eb648625","source_key":"sample-story-d3ab66b8-de78-5b15-ae93-f020eb648625","author_id":"3716d580-ebcf-5e43-9be4-0e8273a7b844","title":"oranges","content":"At the end they tip the oranges out and that sound is so nice, all the little thuds together. I can't desribe it properly. Soft but heavy. The man catches two under his arm, drops one again, swears in a language I know just enough of to recognise that. His daughter is drawing on the back of a cardboard sign with a thick green pen. Everything she draws smells of the pen: a horse, a sun with massive teeth, what might be another horse. I want an orange but he says take the whole bag, take it. My bag already has shoes in it. She begins drawing on the orange while he's looking for change and I say no don't stop, I want that one, the one with","starter_sentence":"Describe a market just before closing.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-07-27T05:47:48Z"},{"id":"1a46edc3-f392-5126-add1-5cee72be5a59","source_key":"sample-story-1a46edc3-f392-5126-add1-5cee72be5a59","author_id":"3716d580-ebcf-5e43-9be4-0e8273a7b844","title":"Curtain","content":"Someone hung the curtain while I slept. That is how I want to start this but it sounds like a horror thing and I mean a nice thing. My brother got the pole up at last. The morning is yellow because the cloth is yellow, even my knees look yellow. I used to hate this colour, all those school toilets painted like old teeth, but here it's sort of warm. There's one bit not hemmed and a thread moving in the air from the heater. I should ring him before he goes to work.","starter_sentence":"A room looks different in the morning.","word_count":94,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-07-28T06:07:51Z"},{"id":"f073f78a-97f9-53f7-858e-c58cd943389f","source_key":"sample-story-f073f78a-97f9-53f7-858e-c58cd943389f","author_id":"6bd32309-597a-5e7f-b957-e1402b53ca2f","title":"shelf","content":"I have put the shelf up upside down. Not upside down exactly the brackets are right but the nice side is facing the wall. You wouldn't think a plank has a nice side until you've spent forty quid on one. Anyway I'm not taking it down because I don't have the plaster left for another attempt. Wife says just put books on it. Yes that's what shelves are FOR, Alan, sorry that's me doing her voice. I've got sawdust in my tea now as well.","starter_sentence":"Explain a small failure.","word_count":85,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-07-28T11:48:21Z"},{"id":"6304b6f9-45ca-55ae-8a44-601d9ae4e59d","source_key":"sample-story-6304b6f9-45ca-55ae-8a44-601d9ae4e59d","author_id":"499dd69e-3f4b-5ba5-b5e5-b656d486793c","title":"Phone call","content":"The phone said Dad but Dad was in the garage and I could see him through the window. So I answered and a man said is your father there. I said yes. Then I thought this might be the thing where they copy voices, except it wasn't his voice. I went outside holding the phone out and Dad said don't bring that near the petrol. This is where there should be some clue about who is calling but I haven't worked it out. Could be his old phone. Could be the garage has a basement.","starter_sentence":"A call comes from a familiar number.","word_count":95,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-07-30T16:44:49Z"},{"id":"e2a406a2-1b3f-5a06-af1f-3edc7b96840a","source_key":"sample-story-e2a406a2-1b3f-5a06-af1f-3edc7b96840a","author_id":"7b3241d7-5e0a-54ff-874b-5c14c843752d","title":"custody","content":"'He's not your cat.' 'He's IN my room.' 'I'm in your room, am I your cat?'\n\nI don't know why I said that because she'd already got the collar out. The real cat was licking mayonnaise off the handle of my bag. We'd both been feeding him. Two dinners. He hadn't told either of us. Now we'd booked two vet appointments and apparently the place charges if you cancel late. 'Fine, YOU take the teeth and I'll do the balls.' Which sounded reasonable until we rang to explain.","starter_sentence":"Two flatmates disagree about a pet.","word_count":88,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-02T19:48:37Z"},{"id":"128ff569-b874-57e1-ad77-1ebc1ff65761","source_key":"sample-story-128ff569-b874-57e1-ad77-1ebc1ff65761","author_id":"7b3241d7-5e0a-54ff-874b-5c14c843752d","title":"Untitled Sprint","content":"Everyone had to bring an example of conflict resolution to the house meeting. I brought the broken air fryer. Ben brought crisps, which was clearly an attempt to influence the panel. The panel was me and the landlord's daughter on a video call. You couldn't hear her because of a blender. 'I'm not paying for it,' Ben said BEFORE anyone even mentioned paying for it. Suspicious. Very lawyer behaviour. Then the front door opened and our fourth housemate came in with an air fryer he'd borrowed from work. Same model. NEW. We all looked at it. Ben put his hand over the crisps. I was trying to remember whether you could say something was evidence if it was still cooking chips.","starter_sentence":"A meeting nobody wants to attend.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-02T22:26:49Z"},{"id":"faf6c6ff-ca2f-59be-b3fd-56976a2b4fe7","source_key":"sample-story-faf6c6ff-ca2f-59be-b3fd-56976a2b4fe7","author_id":"ff5ca053-a03b-51fa-a1f3-a5b20bc75d40","title":"the green room","content":"The men had taken the bed apart before asking what to do with the woman in it. She was not dead, which made the situation rather awkward. She sat up between the dismantled posts and asked for tea. Outside, her son was negotiating the price of the garden statues. He had been negotiating things since nine o'clock and hadn't come upstairs once. Mrs Vale put on her stockings slowly. One of the men handed her the other shoe. He was young and visibly frightened of her, although she had said nothing unkind. The mattress was already on the floor. It was the first time in sixty years that she could get out of bed without her feet hanging above the carpet.","starter_sentence":"A house is being emptied.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-05T11:02:22Z"},{"id":"e33731b8-d05e-50d1-b9c4-20661fd8ece3","source_key":"sample-story-e33731b8-d05e-50d1-b9c4-20661fd8ece3","author_id":"ff5ca053-a03b-51fa-a1f3-a5b20bc75d40","title":"Hem","content":"The dress was too narrow across the back. If she breathed normally the seam would go, so she stood in the bathroom taking tiny breaths while the wedding started without her. She had borrowed it from a woman she disliked. That seemed significant at the time. There was a pair of nail scissors beside the basin and she considered opening the seam herself, just a little, in a place that wouldn't show.\n\nSomeone tried the door. Her sister. Then their mother. The organ began again, louder. She put one blade under the stitches. It was surprisingly hard to cut somebody else's dress. She kept thinking of the woman smoothing it over the hanger, saying it's vintage, you know, and the way she'd looked at her waist.","starter_sentence":"Something borrowed does not fit.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-05T12:24:41Z"},{"id":"54613cb3-5c9f-5fe4-91c4-af2388059b6b","source_key":"sample-story-54613cb3-5c9f-5fe4-91c4-af2388059b6b","author_id":"b0607af9-396b-5aa6-9c27-9ee44270d0e9","title":"the shutter","content":"By ten the shop was full of people who had never bought anything there. They took photos of the sign and said it was a shame. Mr Lau sold three batteries and a packet of mints. I was helping him put price stickers on the shelves because the shelves were for sale too. A woman asked whether she could have the old till as a decorative object. It was still plugged in. He said come back at five. She said she couldn't. He said then no. After she left we moved the till behind the counter where nobody would see it. His daughter arrived with sandwiches and began arguing with him in the back. He wanted to open tomorrow as well. I kept sticking labels on things, trying not to hear.","starter_sentence":"A shop opens for the last time.","word_count":131,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-05T18:42:33Z"},{"id":"1453e1b1-5860-51c3-8d68-65b415259a89","source_key":"sample-story-1453e1b1-5860-51c3-8d68-65b415259a89","author_id":"b0607af9-396b-5aa6-9c27-9ee44270d0e9","title":"two seats","content":"The woman spread her coat across the seat and said somebody was coming. Nobody came. We went six stops. I was standing beside her with a box that was getting heavier by the minute, so I asked whether the person had missed the bus. She shook her head. Then she lifted the coat a little and showed me the bag underneath. It was moving. A cat, I thought, but it was a small chicken. She looked frightened. You're not meant to bring animals, she said. I told her the bus didn't have a chicken rule as far as I knew. She shifted the bag onto her knees and I sat down. Its head came out once near the hospital. Nobody said anything.","starter_sentence":"Someone saves a seat for a stranger.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-05T19:52:38Z"},{"id":"b1076203-d50f-52e7-a0f1-72f0a5c80ad2","source_key":"sample-story-b1076203-d50f-52e7-a0f1-72f0a5c80ad2","author_id":"ff5ca053-a03b-51fa-a1f3-a5b20bc75d40","title":"ribbon","content":"Inside the plaster was a ribbon, folded and folded until it was thicker than a matchbox. I pulled it free and it kept coming. Red, then brown with dust, then red again. My husband told me to stop because it might be tied to something important. What important part of a house is held up by ribbon? I said. But it had gone tight. Far above us, in the ceiling, a small weight dragged across the boards.","starter_sentence":"You find an object inside a wall.","word_count":77,"time_mode":2,"mode":"custom","is_hardcore":true,"created_at":"2026-08-06T13:23:32Z"},{"id":"31afa399-ec66-549d-9e15-498f9ff2c14b","source_key":"sample-story-31afa399-ec66-549d-9e15-498f9ff2c14b","author_id":"b0607af9-396b-5aa6-9c27-9ee44270d0e9","title":"Change","content":"The man in the corner shop asked if I wanted a bag. He's asked me for fifteen years, although I always have one. Today I said yes. He reached under the counter and then looked up, properly looked. You moved away? he asked. I said no. He said your sister used to come. I don't have a sister. We both waited for the other to sort it out. The queue behind me grew. I paid for the milk and took the bag even though I didn't need it.","starter_sentence":"A familiar person does not recognise you.","word_count":88,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-06T16:13:59Z"},{"id":"2d45a9a4-8ecf-5f7e-b3e4-b7f2e21256b3","source_key":"sample-story-2d45a9a4-8ecf-5f7e-b3e4-b7f2e21256b3","author_id":"c40b5e8b-ae09-57ea-9f70-2b01a7041932","title":"which station","content":"'Central.' 'Yes, central.' 'The station.' 'I KNOW.'\n\nWe had been saying this for eight minutes. Behind her I could hear a man selling hot corn. Behind me you could hear my suitcase falling over every time I turned round. 'Tell me something you can see.' 'A clock.' 'Anything else.' 'Another clock.' I wanted to throw my phone. We'd planned this for months and now both of us were standing beside clocks apparently. She said the name of the coffee shop. Finally. I looked it up. She was in the other central staion. Why do cities do this.","starter_sentence":"Two people agree without understanding each other.","word_count":97,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-07T00:17:38Z"},{"id":"62f2ef59-e704-5e7f-b008-024a1db10c78","source_key":"sample-story-62f2ef59-e704-5e7f-b008-024a1db10c78","author_id":"ff5ca053-a03b-51fa-a1f3-a5b20bc75d40","title":"Afternoon","content":"She was early because she didn't want him to have time to hide anything. This sounded less mad before she arrived. Now she was on his doorstep at quarter past two holding an absurd bunch of lilies, watching him eat something straight from a pan. He wasn't dressed. Nobody was hiding in the curtains. There were no unfamiliar shoes. She said she'd written the time down wrong and he let her in, still chewing. The room smelled of frying onions. It was exactly the same room and she had used up all her anger preparing for a different one. She put the flowers in the sink. He asked what was wrong with her face, and then, more gently, whether she wanted some lunch.","starter_sentence":"A guest arrives early.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-08T11:08:49Z"},{"id":"c818c8b0-5bfb-5332-a723-9902b78df41e","source_key":"sample-story-c818c8b0-5bfb-5332-a723-9902b78df41e","author_id":"b0607af9-396b-5aa6-9c27-9ee44270d0e9","title":"outside number eight","content":"There were seventeen parcels for number eight and nobody at number eight. I checked the address twice. The driver was new and sweating through his shirt. Could I take them, he asked. I had come out to put the bins away, so now apparently I was in charge of the street. We carried boxes into my hall until I couldn't open my kitchen door. At lunchtime a woman knocked and said those were hers. She lived at eighteen. I'd already signed. The driver was in another town. We started carrying them down the road one at a time. By the third trip we were laughing. By the seventh she told me they were all exercise equipment and we stopped laughing.","starter_sentence":"A delivery cannot be completed.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-08T20:04:30Z"},{"id":"34a55fc6-2c75-5ed6-a6d7-703c9e10af58","source_key":"sample-story-34a55fc6-2c75-5ed6-a6d7-703c9e10af58","author_id":"372bf907-ffb2-5e65-9653-dd3a7cfb1e05","title":"toast","content":"The ghost wanted the toast left pale. I said you should have told me before I put it on because this toaster has one setting and it is structural fire. He hovered by the fridge while I scraped it. I'd always assumed I'd be frightened of a ghost but he looked like the bloke who used to fix the lift, only see-through from the belt down. He couldn't tell me much about being dead. Apparently there was a lot of waiting and his glasses hadn't come with him. I asked why my kitchen. He pointed to the cupboard where the old boiler was. There used to be a door there, he said. I had to get to work. I left him with the plate and told him to stay out of the eggs.","starter_sentence":"A ghost has an ordinary request.","word_count":133,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-09T04:45:14Z"},{"id":"3b14d374-8ce7-5c1a-83c7-acc35779d9d0","source_key":"sample-story-3b14d374-8ce7-5c1a-83c7-acc35779d9d0","author_id":"bedbcf5d-ff2a-551b-b189-9167eae5be5d","title":"the pump","content":"The pump was fine. I blamed the pump for about half an hour before realising the the valve had come loose. Took the wheel off and lost one of the nuts in the gravel. Then found a different nut which looked close enough but wasn't. I used to do this stuff without thinking. Now I have to watch a video to remember which way the tyre goes. My son kept asking if we were still going out. I said yes too many times. By the time I got it fixed he'd taken his bike down the road with his mates. I went round the block on my own. Brakes rubbed all the way. Need to sort those next.","starter_sentence":"Someone tries to repair an old bicycle.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-09T06:10:07Z"},{"id":"81a60695-45e8-5990-b263-53048483609e","source_key":"sample-story-81a60695-45e8-5990-b263-53048483609e","author_id":"372bf907-ffb2-5e65-9653-dd3a7cfb1e05","title":"a start","content":"A pigeon got into the kitchen. No, a goose. Needs to be a bigger bird or there isn't much of a story. A goose got in and won't leave and the man has an interview in twenty minutes. He tries throwing bread outside but the goose eats the loaf he's left on the counter. This is just a goose being a goose now. Maybe the interviewer is the goose. I don't think I can do anything with that either.","starter_sentence":"A quiet morning is interrupted.","word_count":79,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-09T14:37:37Z"},{"id":"1f28f318-da85-57aa-a746-555640d4beec","source_key":"sample-story-1f28f318-da85-57aa-a746-555640d4beec","author_id":"bedbcf5d-ff2a-551b-b189-9167eae5be5d","title":"Saturday","content":"Seven of us turned up. You need eleven, obviously, but the other lot only had nine so we agreed on a smaller pitch. Then Dave brought his brother. Then their keeper's cousin arrived. We spent longer counting people than playing. I went in goal because my knee was bad and immediately had to dive on it. Nobody scored for twenty minutes. It wasn't good defending, just terrible shooting.\n\nAt half time we stood round someone's boot drinking orange squash from cups left over from a birthday party. Mine had a unicorn on it. Dave asked if I fancied the league again next year. I said probably. Knee says no but I always say probably.","starter_sentence":"A team has too few players.","word_count":114,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-10T07:01:34Z"},{"id":"2a6ffdea-9a71-596d-9dcb-560aa1c52805","source_key":"sample-story-2a6ffdea-9a71-596d-9dcb-560aa1c52805","author_id":"ff5ca053-a03b-51fa-a1f3-a5b20bc75d40","title":"the stairs","content":"The staircase had been carpeted over while they were away. Their suitcases stood in the hall like witnesses. Neither of them had asked for a carpet. It was a dense floral thing, red roses on black, and it covered the first flight but stopped at the turning. Above that the steps were bare. She crouched to touch the edge. Fresh glue. Her husband was already on the phone to the letting agent saying unacceptable in his loud work voice. She wished he would be quiet. There were footprints in the pile, coming down. Whoever had put the carpet there was still somewhere above them. She tried to say his name without making a sound.","starter_sentence":"Someone has changed your house while you were away.","word_count":114,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-10T10:43:14Z"},{"id":"4e5a5f77-95af-5608-9dd3-fd484a601273","source_key":"sample-story-4e5a5f77-95af-5608-9dd3-fd484a601273","author_id":"866db53a-8aca-5f5e-8aab-6b719a7a3396","title":"the pot","content":"There is soil on Asha's side of the hall and soil on my side so nobody can claim this was all me. She'd borrowed the enormous rubber plant for her flat viewing. Apparently people offer more money when they think a plant can survive in a place. Now she's brought it back in a washing-up bowl because the pot cracked in the lift, and I am trying to separate the roots from a sponge. I keep saying that's fine. It isn't fine! I liked the pot more than the plant. She keeps giving me instructions about drainage even though I'm the one who's kept it alive for eight years. Actually six. It was before the divorce, anyway. There is a tap root through one of the sponge holes and I don't know whether cutting it will kill the whole thing.","starter_sentence":"A neighbour returns something borrowed.","word_count":140,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-10T16:43:21Z"},{"id":"e824c6f7-f3b7-5474-affa-42c393196eb6","source_key":"sample-story-e824c6f7-f3b7-5474-affa-42c393196eb6","author_id":"866db53a-8aca-5f5e-8aab-6b719a7a3396","title":"Landing","content":"I was the last one on the landing so I did switch it off. I remember because my nail got caught in the switch and split. At two in the morning my neighbour starts banging. She's in her dressing gown carrying a small cage under a towel. She says the light has been going on and off and her bird thinks it's morning. Well I didn't even know she had a bird. We're all standing there now, me, her, the man from downstairs who has brought a stepladder without being asked. The bird is doing an extremely good impression of someone's text alert. Nobody knows which fuse is for the hall. I suggest putting the cage in the bathroom and she looks at me as if I suggested flushing it.","starter_sentence":"Someone keeps leaving the light on.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-10T17:51:08Z"},{"id":"17520fc9-b9d4-55b0-8fb4-12b67fe130c0","source_key":"sample-story-17520fc9-b9d4-55b0-8fb4-12b67fe130c0","author_id":"bedbcf5d-ff2a-551b-b189-9167eae5be5d","title":"Bench","content":"Sanded half the bench then it rained. Brought it inside. Too wide for the door. Left it on its side under a bin bag. This was meant to be the easy job this weekend.","starter_sentence":"An unfinished repair.","word_count":34,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-11T05:03:29Z"},{"id":"77a4dd26-c4e1-514e-9c15-638280700e99","source_key":"sample-story-77a4dd26-c4e1-514e-9c15-638280700e99","author_id":"56e3ab93-f00d-5013-8efa-7e9793982187","title":"lead","content":"Dog turned left so I turned left. Usually we go right. He dragged me past the park, past the bakery, straight into a car wash. No idea why. A man came out holding a hose and the dog went absolutely mad with happiness. Turns out the man used to own him. Not own him, foster him before us. I stood there feeling weirdly jealous while my dog tried to climb inside somebody else's coat. Then he came back and leaned on my leg, still watching the man.","starter_sentence":"A dog chooses the route.","word_count":87,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-11T11:26:08Z"},{"id":"ea10e31b-d92a-518b-a5c0-589f2fbbc80f","source_key":"sample-story-ea10e31b-d92a-518b-a5c0-589f2fbbc80f","author_id":"56e3ab93-f00d-5013-8efa-7e9793982187","title":"hill","content":"Halfway up I thought I'd be sick so I slowed down but Jess was behind me and I didn't want her to think I'd stopped. Stupid. She'd already seen me fall over a bin earlier. The hill kept bending and every bend looked like the top until you got there. My shirt was stuck to my back. I could hear my breath louder than the music. At the actual top there was no view, just a fence and somebody's shed. Jess arrived walking. Said she'd walked most of it. I sat on the gravel. She had brought sweets. We ate them without saying anything, then had to decide how to get down because my legs had started shaking.","starter_sentence":"Keep moving even when you regret starting.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-12T17:35:01Z"},{"id":"c8459a90-05eb-5212-9be7-b8e4bfe77f34","source_key":"sample-story-c8459a90-05eb-5212-9be7-b8e4bfe77f34","author_id":"bedbcf5d-ff2a-551b-b189-9167eae5be5d","title":"last lap","content":"I thought there was another lap. That's it, that's the story. Everyone stopped and I kept going because I'd lost count around lap four when my shoelace came undone. A woman shouted something but I thought she was encouraging me. So I ran a whole extra lap and came back to find them packing the clock away. My wife had my medal in her bag. She'd collected it because she thought I'd gone to the toilet. I was angry for about ten minutes, then tired, then hungry. We went for chips. I still put the distance in my running app because I had run it, regardless of whether anybody was counting.","starter_sentence":"Someone keeps going after the race ends.","word_count":111,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-13T07:24:06Z"},{"id":"606cee2e-971b-5143-ae77-d0d96f02d2a8","source_key":"sample-story-606cee2e-971b-5143-ae77-d0d96f02d2a8","author_id":"56e3ab93-f00d-5013-8efa-7e9793982187","title":"over","content":"Jumped the puddle. Cleared the water. Landed in mud on the other side and slid straight back into it. Dog watched. Didn't even try to help. Whole left shoe full of water now.","starter_sentence":"A small jump goes wrong.","word_count":33,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-13T19:06:14Z"},{"id":"8344dacb-2f99-51e1-996e-f425dda7f393","source_key":"sample-story-8344dacb-2f99-51e1-996e-f425dda7f393","author_id":"876da364-0641-5578-b7d4-fd9b2456202e","title":"the queue","content":"They put me in the queue to find out which queue I needed. I asked if I could just stand between both queues and the woman said that wasn't fair to people who'd chosen. Chosen WHAT. A man behind me had brought a folding stool and I felt this meant he knew something I didn't. I asked how long he'd been there. He said since Tuesday. It was Tuesday. He wouldn't clarify. I'm still standing here and he is eating an egg from a napkin.","starter_sentence":"An unnecessary rule.","word_count":85,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-15T00:55:03Z"},{"id":"4e508eee-9e01-54a9-b3b3-cdd85e1dec11","source_key":"sample-story-4e508eee-9e01-54a9-b3b3-cdd85e1dec11","author_id":"56e3ab93-f00d-5013-8efa-7e9793982187","title":"race","content":"The woman kept shouting go Danny and I kept running faster even though I'm not Danny. I was tired enough that encouragment was encouragement. She ran along the barrier beside me for a bit and then stopped. I looked over. Her face had changed. Actual Danny was behind me, limping, and I'd been soaking up his mother's support for the last hundred metres. I slowed down without meaning to. He caught me at the corner. We ran together for a bit. He said you can go ahead. I said I couldn't actually, I'd used everything trying to impress his mum. He laughed so hard he had to stop and now I felt responsible for that too.","starter_sentence":"Someone cheers for the wrong person.","word_count":116,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-15T07:59:12Z"},{"id":"c18b4688-5de5-5dfd-879c-e19d9ff5db46","source_key":"sample-story-c18b4688-5de5-5dfd-879c-e19d9ff5db46","author_id":"75af2211-3775-551c-8cc4-62c5f5ad26aa","title":"rope","content":"Dad was late and the tide was taking the boat away from the ladder. I had one foot on the jetty and one on the side of the boat, which was a ridiculous position to be in but I couldn't seem to stop. If I let go the rope would go underneath. He'd tied it wrong again. I shouted for the boy fishing further along to come and hold it. He couldn't hear, or didn't want to leave his rod. In the end I sat down hard on the wet planks and pulled the boat in with both hands. Dad came back with two bags of groceries. He said I thought you were staying aboard. I wanted to shout at him but he had bought the biscuits I like and was holding them out, not understanding what he'd done.","starter_sentence":"Someone is waiting on a jetty.","word_count":139,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-16T12:34:55Z"},{"id":"a9ad96fa-e4ba-5416-bf71-65db0eb88787","source_key":"sample-story-a9ad96fa-e4ba-5416-bf71-65db0eb88787","author_id":"75af2211-3775-551c-8cc4-62c5f5ad26aa","title":"the spare coat","content":"I gave the coat to the woman collecting for the shelter and then drove after her van. It was a stupid thing to do. She pulled over thinking something had fallen out. I couldn't explain it properly, just kept saying the blue one, the big blue one. There were several blue ones. We stood in a layby going through bags of other people's clothes until I found his. It didn't even smell of him any more. She was kind about it which made me cry worse.\n\nI said I'd wash it and bring it to the depot. She said I didn't have to. But I do want someone to have it. I don't want it in the hall every day. I just wasn't ready for it to already be on somebody else.","starter_sentence":"A useful thing is difficult to give away.","word_count":132,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-16T13:12:47Z"},{"id":"5446a336-6bdb-5ea7-905d-26c2a781d21f","source_key":"sample-story-5446a336-6bdb-5ea7-905d-26c2a781d21f","author_id":"8665f806-0371-5a69-bcc1-b0f509b01190","title":"no actually","content":"i was going to say actually it hurt my feelings but that sounds like something from a worksheet. so i said dont be weird and she said what and i said nothing. NO that wasn't how it went she said what first. whatever. i had this whole speech on the walk there and then she was wearing the jumper i gave her and i couldn't work out if that meant something. probably it meant she was cold. i hate that i can think of seventen things to say to a wall and then a person turns up and i say nothing","starter_sentence":"Say the thing you rehearsed.","word_count":101,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-17T08:37:10Z"},{"id":"35ee8990-829b-5f9f-b5a3-d6fc8b490c4a","source_key":"sample-story-35ee8990-829b-5f9f-b5a3-d6fc8b490c4a","author_id":"56e3ab93-f00d-5013-8efa-7e9793982187","title":"the gap","content":"He got through a gap I couldn't even fit my hand into. One secod dog, next second tail, then nothing. I called and heard him crashing about behind the fence. We were beside the railway so so I went cold all over. Tried climbing, slipped, ripped my sleeve. A man in a van stopped and asked what I was doing. I said dog, just dog, couldn't make a sentence. He had bolt cutters. Why he had bolt cutters I didn't ask. We got a panel open and there was my idiot sitting beside a sandwich wrapper, eating bread. I grabbed his collar so hard he yelped. Then I sat down in the dirt holding him and couldn't get up for a minute.","starter_sentence":"An animal escapes through a small opening.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-17T09:39:45Z"},{"id":"a7944ced-48f5-53b1-b7b3-7585273779f6","source_key":"sample-story-a7944ced-48f5-53b1-b7b3-7585273779f6","author_id":"75af2211-3775-551c-8cc4-62c5f5ad26aa","title":"low tide","content":"We used to walk the low-tide path to avoid paying for the ferry. They fenced it off this year. My aunt said fences were suggestions and lifted the bottom wire while I passed her bag underneath. Then she got stuck. Not properly stuck, her earring caught, but she began laughing and every time she laughed it pulled harder. The ferry man was watching from his hut. I could see his orange jacket. He'd watched us do this for thirty years and now he came out carrying wire cutters.","starter_sentence":"A familiar route is blocked.","word_count":88,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-17T10:45:54Z"},{"id":"024ed9e3-5ea1-556c-a13d-13bb8171983d","source_key":"sample-story-024ed9e3-5ea1-556c-a13d-13bb8171983d","author_id":"ccc9a13c-cd6e-5bc4-8c40-3106ddb82b76","title":"the blue bag","content":"For the whole train journey I had been sitting on the bag so nobody would nick it. That is relevant because when we opened it later the rolls were flat. Not our rolls. Somebody else's beautiful little homemade rolls, with seeds on, and a towel and two pairs of absolutely enormous pants. My actual bag was probably halfway to Brighton by then. Mum wouldn't stop laughing long enough to ring the number on the label. I felt awful. I was meant to be showing I could organise one single thing. The owner answered and he was furious, completely fair, except he kept referring to his underpants as garments. I had to hand the phone over. Then Mum started saying garments as well and I knew we'd never get through it.","starter_sentence":"You bring the wrong thing on a trip.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-17T15:37:57Z"},{"id":"e6d204e9-0a9d-58e5-9063-ac37b0eece46","source_key":"sample-story-e6d204e9-0a9d-58e5-9063-ac37b0eece46","author_id":"04903eff-fc1c-5234-af10-2baa64cd1776","title":"wrong key","content":"The key turned but the door didn't open. I leaned on it. Something heavy was behind it, not a chain because there wasn't any give. I could get a finger round the edge at the top. Light on inside. I called through the letterbox and heard someone moving away. Then my phone rang. It was the landlord asking why I was at the old address. He'd changed the viewing. The person inside started pushing the door back and my key snapped in the lock.","starter_sentence":"A key will not open the door you expected.","word_count":84,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-17T17:49:06Z"},{"id":"1388ef6d-7801-5f36-9fb0-24032fd90398","source_key":"sample-story-1388ef6d-7801-5f36-9fb0-24032fd90398","author_id":"04903eff-fc1c-5234-af10-2baa64cd1776","title":"Measurements","content":"From the kitchen wall to the back fence was nine metres. The cellar should have been four metres wide. It was eleven. I checked with the laser measure, then with the tape because the laser can bounce off glass and there was a shiny patch on the far wall. Eleven either way. That meant we were under next door's garden. Possibly under next door. I'd only gone down to look at the damp. Now I was sketching floor plans on the back of an invoice while the estate agnet stood at the top of the stairs saying old houses are full of surprises. There was a small door behind a shelving unit. I moved the shelves. She stopped talking. I asked if she had the key and she said the surveyor hadn't mentioned a door.","starter_sentence":"A room is bigger than the building should allow.","word_count":135,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-18T18:08:02Z"},{"id":"f6831975-e0c5-5bdf-88d6-02cf4c5122a6","source_key":"sample-story-f6831975-e0c5-5bdf-88d6-02cf4c5122a6","author_id":"04903eff-fc1c-5234-af10-2baa64cd1776","title":"Latch","content":"I locked the workshop then pulled the handle to check. Came off in my hand. The door stayed shut. I stood there holding it, thinking I should have stopped after the first part.","starter_sentence":"Someone forgets to lock up.","word_count":33,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-19T17:04:36Z"},{"id":"2f612f36-e001-5f3f-953d-92415b74ae11","source_key":"sample-story-2f612f36-e001-5f3f-953d-92415b74ae11","author_id":"aabd5fd6-402c-546a-b1ce-9ebb44a17114","title":"room 12","content":"Room twelve was already occupied. Not by a person, by a suitcase. Open on the bed, half unpacked. Recpetion said there was no booking for it and I must have the wrong room. I held up the key. They gave me another room. At two in the morning someone tried my door. Same reception boy, carrying the suitcase. He said it was mine. I said it wasn't. He looked so tired I almost accepted it. In the morning it was outside my door with a note saying sorry for the inconvenience. I left it there. On the train I kept wondering whether I should have opened it, then remembered I had already seen inside. Shirts. A hairbrush. An orange peeled halfway.","starter_sentence":"A hotel room contains someone else's belongings.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-19T18:00:27Z"},{"id":"05e34feb-ed3f-5511-bdef-425410ae4979","source_key":"sample-story-05e34feb-ed3f-5511-bdef-425410ae4979","author_id":"e35ec7d7-1f8d-5028-b7d0-810249b008c8","title":"rules","content":"'You can't move backwards.' 'You JUST moved backwards.' 'I'm a wizard.' 'You were a plumber ten minutes ago.' 'I multiclassed.'\n\nWe were supposed to be playing a board game I'd bought in a charity shop and none of us had noticed the instuctions were for a different game. So basically Tom had been making up rules for an hour and somehow still losing. I wanted my money back from Tom specifically. He said you can't demand a refund during a battle. I tipped the box over to find the real instructions and about thirty more pieces came out. Tiny sheep. We hadn't used a single sheep. Everyone went quiet because now we had to decide whether to start again or pretend sheep didn't exist.","starter_sentence":"Friends disagree about a game.","word_count":124,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-19T21:15:37Z"},{"id":"772116e1-7e74-579e-9f45-3833820068d8","source_key":"sample-story-772116e1-7e74-579e-9f45-3833820068d8","author_id":"aabd5fd6-402c-546a-b1ce-9ebb44a17114","title":"junction","content":"There were two trains and either would get me there. One went through the city where he lived. I'd checked this three times, although it wasn't relevant because I wasn't getting off. The other was faster and cost less. I bought the slower ticket. Then stood at the junction watching the faster train arrive first. I could still change it. The woman beside me was eating an apple very loudly and I started using her bites as a countdown, which makes no sense but I was tired. Three more bites and I'd move. She put the apple in her bag. My train came. I got on and took a seat facing backwards, so at least I wouldn't see the city coming.","starter_sentence":"You have time to change your mind.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-20T15:58:49Z"},{"id":"8433acae-ed17-5a17-8563-7ced967c8115","source_key":"sample-story-8433acae-ed17-5a17-8563-7ced967c8115","author_id":"35db90b0-3430-5c6f-827a-31e11613b5b4","title":"backup","content":"My backup self was six weeks out of date. That meant he still liked my ex and hadn't learned the new parking rules. I tried to catch him up over breakfast but he kept asking why he'd been activated. Fair question, difficult answer. I wasn't dying or anything. I just had two job interviews at the same time. Technically this is prohibited by the licence agreement, which he knew because he was the version of me who still read licence agreements. We argued for forty minutes and missed both interviews. Then he asked if he could have my old laptop. I said OUR old laptop, since I was trying to establish a cooperative framewrok, but that made it sound like we were married. Neither of us wanted to wash up.","starter_sentence":"A backup version of you is out of date.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-20T17:10:59Z"},{"id":"7ac06b12-983d-56cc-b8f8-8ac5a8060aa7","source_key":"sample-story-7ac06b12-983d-56cc-b8f8-8ac5a8060aa7","author_id":"fac9356b-8dab-5a27-a784-f98812e1b574","title":"the drawer","content":"The drawer opened every time the extractor fan came on. At first I thought vibration. Then I put a heavy book in front of it and the drawer pushed the book off the counter. I had people coming for dinner and wasn't going to cancel because of a drawer. I taped it shut. Halfway through frying the onions the tape stretched, slowly, until there was a thin gap. Someone inside said could you keep it down. I said I'm cooking. They said yes, they could tell. I turned the fan off and opened the window instead. By dessert I'd almost forgotten. Then my friend went to find a spoon and I shouted at her so loudly she dropped the bowl.","starter_sentence":"A house makes a new sound.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-20T21:02:09Z"},{"id":"0de479ab-9a52-5817-9760-0cf0a03a05e4","source_key":"sample-story-0de479ab-9a52-5817-9760-0cf0a03a05e4","author_id":"e35ec7d7-1f8d-5028-b7d0-810249b008c8","title":"the key","content":"'You've got it.' 'No you've got it.' 'I gave it to you.' 'When.' 'When I gave it to you.' Excellent evidence from counsel there. We checked every pocket. I checked pockets in a coat I wasn't wearing. Then Luke said maybe it was still in the door. It was. On the other side. You could see the little shadow of it through the keyhole. 'Can we push it out?' I said. 'With what?' He held up my bank card. 'That is not going to fit.' 'We can fold it.'","starter_sentence":"Two friends wait outside a locked door.","word_count":89,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-20T22:22:23Z"},{"id":"3b095b85-fafb-5240-9f20-04b821c971ac","source_key":"sample-story-3b095b85-fafb-5240-9f20-04b821c971ac","author_id":"fac9356b-8dab-5a27-a784-f98812e1b574","title":"boiling","content":"The kettle boiled without being plugged in. Useful, I thought. I know that's not the right response but electricity is expensive. After a week it started making two cups. I drank one and left the other.\n\nBy Friday there was toast. Buttered badly, right to the edges on one slice and none in the middle of the other. That's when I got upset. My father made toast like that. I sat down and said if it's you, I need you to do something else. Something definite. The kitchen went quiet. Then the radio came on to a station he hated, very loud, and I laughed and cried at the same time because that was also something he'd do by accident.","starter_sentence":"A ghost joins an ordinary routine.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-21T02:20:59Z"},{"id":"8e5a4ad7-677a-568d-8b04-8f466480ebc7","source_key":"sample-story-8e5a4ad7-677a-568d-8b04-8f466480ebc7","author_id":"aabd5fd6-402c-546a-b1ce-9ebb44a17114","title":"Window","content":"the window rattles when we go fast and stops when we slow down. fields then houses then fields again. somebody behind me is opening a packet very carefully and making it take longer. i have no signal. the reflection of my face floats over a horse.","starter_sentence":"Describe a journey without the destination.","word_count":46,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-21T15:57:50Z"},{"id":"3cd577ce-7605-50b4-8298-fe6d19318f5d","source_key":"sample-story-3cd577ce-7605-50b4-8298-fe6d19318f5d","author_id":"35db90b0-3430-5c6f-827a-31e11613b5b4","title":"meeting room","content":"The teleportation system worked perfectly except it wouldn't move anything that was touching anything else. This was a safety measure to avoid taking bits of wall with you. So the test subject had to jump. But then his clothes were touching him. We put him in a loose gown, which didn't solve anything if you think about it for two seconds, which apparently none of us had. Meanwhile the client was asking why our rival could teleport whole shipping containers. I said they had different ethical standards. They probably had different progammers. Then the test subject asked whether air counted and the lead engineer left the room. That wasn't encouraging. I wrote 'air?' on the whiteboard so we could come back to it.","starter_sentence":"A future invention meets an ordinary problem.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-21T17:37:47Z"},{"id":"59905c27-c8d5-5ca0-8a1d-75b4e69c892b","source_key":"sample-story-59905c27-c8d5-5ca0-8a1d-75b4e69c892b","author_id":"e35ec7d7-1f8d-5028-b7d0-810249b008c8","title":"Reset","content":"The character stopped obeying me halfway across the bridge. I pushed left and he sat down. Pressed jump, he took his shoes off. 'Controller's broken,' said Mat. We swapped. Same thing. On screen the little guy was wringing water out of his socks. There wasn't even water in this level. Mat tried shooting him with player two and missed because player two was lying down now. They were both exhausted. I said maybe we should give them a minute and Mat laughed, but he put the controller down. The game music kept going. The little guy looked directly at us. Then he started talking, no text box, just moving his mouth and pointing behind him at","starter_sentence":"A game changes while you are playing.","word_count":116,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-21T22:40:54Z"},{"id":"f8f45ccd-dbbd-5b5a-8f11-1b3ac2930dbf","source_key":"sample-story-f8f45ccd-dbbd-5b5a-8f11-1b3ac2930dbf","author_id":"fac9356b-8dab-5a27-a784-f98812e1b574","title":"photo","content":"In the photograph my aunt is standing behind the chair. Yesterday she was sitting in it. I asked Mum and she said there were two photographs from that day. There aren't. I took the frame apart. One photo, cardboard, glass. When I put it back she was sitting again. I don't want to sound dramatic but I've put it face down. Mum turned it over while dusting. Now the chair is empty and my aunt is standing much nearer the camera.","starter_sentence":"An old photograph changes.","word_count":81,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-22T03:26:45Z"},{"id":"949143cb-7b22-57bc-9ef4-3fbcd0cde421","source_key":"sample-story-949143cb-7b22-57bc-9ef4-3fbcd0cde421","author_id":"ea6da2fe-b561-5aca-b34c-3a691d21a947","title":"cups","content":"My sister unpacked the kitchen according to a system she understood. Plates above the sink, glasses by the oven, mugs somewhere I couldn't find. Every time I asked where something was she said it was obvious. I had moved to be closer to her. That was the thing neither of us wanted to say while we argued about cupboards. After she left I moved everything back to where I'd first put it. Then I couldn't find it either. I rang her to ask about the mugs and she answered immediately, before the first ring had finished. She'd been waiting in her car downstairs, worried she'd been too much. I told her to come back up. We ate takeaway out of the cartons because all the plates still had newspaper stuck to them.","starter_sentence":"Someone helps you move.","word_count":132,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-22T15:56:00Z"},{"id":"45aa97a3-bded-5f15-95a1-cc95904b7b6f","source_key":"sample-story-45aa97a3-bded-5f15-95a1-cc95904b7b6f","author_id":"6d6fdef6-dd71-58ba-a2d3-5191446b814d","title":"Third drawer","content":"The third drawer is locked. He opens it and there's another drawer inside. Smaller obviously. Then another one. I thought this was going somewhere but it's just drawers. Maybe the last one has a tooth in it. Why a tooth though.","starter_sentence":"Something is happening inside a locked drawer.","word_count":41,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-22T16:24:30Z"},{"id":"d1a726d5-f738-5cdc-bd78-ea6c970e930b","source_key":"sample-story-d1a726d5-f738-5cdc-bd78-ea6c970e930b","author_id":"ea6da2fe-b561-5aca-b34c-3a691d21a947","title":"spare bed","content":"He said two nights, so I made the bed with the good sheets. By the ninth night I wanted those sheets back. They were mine and I had no spare set, only the thin ones that twist around your legs. It sounds petty written down. He had lost his job and probably his flat, although he wouldn't say the second part. Every evening he offered to cook. Every evening I said don't worry about it and then got angry that I was cooking again.\n\nTonight I said yes. He looked surprised. I sat in the kitchen while he chopped onions with my blunt knife. He didn't ask where anything was. He'd learned the cupboards. I wasn't sure whether that made me feel better or worse.","starter_sentence":"A guest stays longer than expected.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-22T16:47:40Z"},{"id":"84003637-b50b-5706-a2b0-4af4755bb1c5","source_key":"sample-story-84003637-b50b-5706-a2b0-4af4755bb1c5","author_id":"35db90b0-3430-5c6f-827a-31e11613b5b4","title":"sleep credit","content":"If you sell eight hours of sleep, who wakes up tired? This is the part nobody explains in the adverts. I sold mine on a Friday and felt fine Saturday. Sunday also fine. Thought I'd found a loophole. Monday morning my wife said I'd been standing in the kitchen asleep for half an hour making the same cup of tea. The bank had collected the sleep late. There was a processing delay. I called customer services and they asked me to stay awake while they checked the account which felt quite rude considering. Then they offered me a sleep loan to cover the shortfall. At this point I realised it was just a bank. All the futuristic stuff was decoration. I still took the loan because I had to drive.","starter_sentence":"He sold his sleep to a tech company. He didn't read the terms of service.","word_count":130,"time_mode":3,"mode":"regular","is_hardcore":false,"created_at":"2026-08-22T17:53:25Z"},{"id":"8e2d44fe-713e-5e19-97f9-2e348611e3aa","source_key":"sample-story-8e2d44fe-713e-5e19-97f9-2e348611e3aa","author_id":"87026c76-9bb9-5539-80f7-1590581ecda2","title":"Biscuit policy","content":"Someone put a spreadhseet beside the biscuit tin. A SPREADSHEET. Names, dates, number consumed. I ate a biscuit while reading it and immediately felt like a criminal. Was I supposed to log the broken half? Were crumbs taxable? I wrote 'Lee, today, several' and went back to my desk. At eleven Carol came round with the sheet asking who had written several. My name was next to it Carol. We have reached the point where literacy is optional but biscuit accountability is mandatory. Anyway she says it's for stock control and I said then why is there a column called habitual. She said that was unfortunate wording. I have been labelled a habitual biscuit user and HR won't answer my email.","starter_sentence":"A small office dispute grows.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-23T07:32:13Z"},{"id":"66b0738d-e212-5eb7-a98f-859de9d6740f","source_key":"sample-story-66b0738d-e212-5eb7-a98f-859de9d6740f","author_id":"ea6da2fe-b561-5aca-b34c-3a691d21a947","title":"two teaspoons","content":"There are two teaspoons in my handbag and I don't remember putting them there. I found them at the dentist when I was looking for my card. The receptionist waited while I moved them out of the way. One is my mother's. I know because the handle has a dent from the disposal. The other might be from work. I have become a person who carries stolen cutlery without noticing. Mum would have found this funny. I wanted to tell her, which still happens at completely ordinary times. I put them back in the bag. The dentist called my name and asked how I'd been. I said fine, automatically, then said actually no and started crying with a paper bib on.","starter_sentence":"An object you do not need.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-23T14:20:06Z"},{"id":"56d3204c-4c9d-548a-82f8-03c7025c4cf4","source_key":"sample-story-56d3204c-4c9d-548a-82f8-03c7025c4cf4","author_id":"6d6fdef6-dd71-58ba-a2d3-5191446b814d","title":"machine","content":"The machine folded a piece of paper in half. That was all it did. It was three metres high and had to be bolted to the floor because the motor shook the whole room. My uncle said it was a prototype. I folded the paper again myself and he said that wasn't the point. He'd been building it since Christmas. There were wires across the spare bed where I was supposed to sleep. I asked if it could do a plane and he got the screwdriver out.","starter_sentence":"A machine does one useless thing perfectly.","word_count":87,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-23T15:21:14Z"},{"id":"9f744a03-b843-5ae8-9ce0-bf25462687fd","source_key":"sample-story-9f744a03-b843-5ae8-9ce0-bf25462687fd","author_id":"e35ec7d7-1f8d-5028-b7d0-810249b008c8","title":"cinema","content":"I had bought three tickets because I thought she was bringing her sister. She wasn't. Now she thought the third ticket was for my girlfriend. I don't have a girlfriend. I said that too fast. Made it worse. 'We could find someone,' I said, as if I were proposing to collect a stranger from the pavement. She started laughing. Finally. Then she actually did it. Asked a bloke by the machines if he wanted to see a film. He was waiting for his wife. His wife wanted to come too. Suddenly I was at the desk trying to get FIVE seats together for a screening that started four minutes ago and the man was telling me it was unallocated seating and I could just go in.","starter_sentence":"Someone arrives with an extra ticket.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-23T20:41:31Z"},{"id":"45c23005-5953-574d-9058-6c433bef7acd","source_key":"sample-story-45c23005-5953-574d-9058-6c433bef7acd","author_id":"fac9356b-8dab-5a27-a784-f98812e1b574","title":"the tap","content":"'Can you turn the tap off?' I called from the hall. 'In a minute,' someone called back. I was alone. I knew I was alone because I'd spent all morning enjoying it. I stood with my coat half on, listening to the water run. It sounded like the upstairs basin. I said who is that, and the voice said in a minute again, impatient this time. I went outside and rang my sister. She told me not to go back in. Good advice, except my dog was still inside. Through the letterbox I could see him sitting at the bottom of the stairs, tail going. He never does that for strangers. I called his name and he looked at me like I was interrupting.","starter_sentence":"Someone answers from an empty room.","word_count":124,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T01:39:45Z"},{"id":"7cb08c86-7514-52a9-a20b-bc761a3edcbc","source_key":"sample-story-7cb08c86-7514-52a9-a20b-bc761a3edcbc","author_id":"87026c76-9bb9-5539-80f7-1590581ecda2","title":"mug","content":"My mug is gone and everyone is being NORMAL about it. That's the worst bit. They've all still got drinks. Nobody has paused operations. Mine is the blue one with no handle, which I know sounds like a bowl but it is a mug with history. I found it in the meeting room holding pens. Asked whose idea that was. Nobody knew. Took the pens out, washed it, made tea, sat down. It leaked. Someone had put pens in it BECAUSE it leaked. I had forgotten that. Now there's tea in my keyboard and I have to go round explaining why I accused everybody of theft. Might just go home.","starter_sentence":"Something small goes missing.","word_count":110,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T09:34:20Z"},{"id":"b2b0eb24-7573-57fd-bc5e-0acd57715e7f","source_key":"sample-story-b2b0eb24-7573-57fd-bc5e-0acd57715e7f","author_id":"35db90b0-3430-5c6f-827a-31e11613b5b4","title":"attempt 4","content":"A machine to make time. Not save it, actually make another minute. It takes two minutes to run. That's the problem. You can paralellise them I suppose, but then you've invented a really noisy way to stand in a warehouse. Maybe the extra minute arrives yesterday so you could stop yourself buying the machine. Then who built it. I'm going in circles. The man switches it off and goes to lunch. His sandwich has vanished. That's something at least.","starter_sentence":"A time-saving device takes too long.","word_count":79,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T17:33:00Z"},{"id":"ad66e8d3-aca0-535a-af57-60537d1c592a","source_key":"sample-story-ad66e8d3-aca0-535a-af57-60537d1c592a","author_id":"65dce665-cd08-5b8e-b711-05282ce21da9","title":"roof","content":"The bird dropped a tooth onto the roof and flew back down. A huge tooth. Too big for its beak, actually, I need to think about that. It dragged it by a string? There was something tied to it. The girl picked it up with the edge of her shirt because it was wet. Below the gutter another bird was climbing instead of flying. Then another. All of them had teeth. Across the city the windows were opening as people heard the scraping. She ran along the ridge towards the bell tower. Her brother was still asleep up there and if this was happening to everyone's teeth then she needed to wake him before the birds found the big crack in the","starter_sentence":"A bird brings something unexpected.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T19:52:23Z"},{"id":"0aeda070-a5f1-5a58-9e3b-270f5f9b8e89","source_key":"sample-story-0aeda070-a5f1-5a58-9e3b-270f5f9b8e89","author_id":"b4640650-cb5e-5f6f-aa84-0822fda364bf","title":"wall","content":"Maybe the house is growing a room. There's a lump beside the kitchen, that's the easiest way to put it. Like a bubble in wallpaper only the actual wall is bulging. I asked Dad if the house was pregnant and he said don't be silly and then went outside to look from the other side. The other side looks normal. I think that bothered him because he didn't make the joke he normally makes about this being a load bearing mess. We put a bit of pencil on it to measure. By dinner the pencil mark was above the shelf. Mum said ring someone. Dad said who. A builder obviously, but I was thinking we should ring the people who deliver babies because","starter_sentence":"A house begins to change shape.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T20:43:46Z"},{"id":"54a36b57-248b-5400-96ce-c16bd67cab2c","source_key":"sample-story-54a36b57-248b-5400-96ce-c16bd67cab2c","author_id":"65dce665-cd08-5b8e-b711-05282ce21da9","title":"Flight lesson","content":"Every morning the roofs were a different distance apart. Yesterday she'd cleared the butcher's in one jump and today it was too far. The street below looked stretched, people tiny at the bottom, all their shopping bags swinging. She didn't mind being high. It was the distance changing that made her sick. Her instructor said close your eyes and feel the roof with your feet. That sounded stupid. She needed her eyes to avoid dying. She closed one, just to be polite, and immediately felt the tiles move under her. Not the whole roof. One tile was crawling across another tile like it had legs. She looked back to show him but he'd already jumped.","starter_sentence":"Someone is afraid of a familiar place.","word_count":115,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T22:49:42Z"},{"id":"a6027207-b7b4-56f3-8450-728ca5792be2","source_key":"sample-story-a6027207-b7b4-56f3-8450-728ca5792be2","author_id":"b4640650-cb5e-5f6f-aa84-0822fda364bf","title":"moth","content":"the moth kept landing on the envelope. It was one of the big furry ones that looks soft till you get really close and the legs are horrible. I moved it with a glass, put the glass outside, came back, same moth. Or a different one but it had the same torn bit in its wing. There was no stamp on the letter so possibly it had come by moth? I quite like that. A whole postal service that only works if you leave your lights on. But then who sends a letter with no address. I've spent too much time thinking about the moth and not what the letter says. I'm opening it now and there's just a drawing of my","starter_sentence":"Something keeps returning to the same place.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-24T22:59:22Z"},{"id":"cabb54ef-52ac-5160-a542-5f63e9f7f3d0","source_key":"sample-story-cabb54ef-52ac-5160-a542-5f63e9f7f3d0","author_id":"87026c76-9bb9-5539-80f7-1590581ecda2","title":"Untitled Sprint","content":"Saved the crispy bit of lasagne till last and then sneezed on it. Proper sneeze, no time to turn away. It's my own sneeze so technically what's the problem. I eat things that have been in my own mouth all the time. That's chewing. But now I've thought about chewing too much and can't eat anything. The lasagne is geting cold. I was looking forward to that bit all afternoon. This is a bad story. It's also my lunch.","starter_sentence":"Someone saves the best bit for later.","word_count":79,"time_mode":2,"mode":"custom","is_hardcore":true,"created_at":"2026-08-25T07:05:58Z"},{"id":"9ff808df-b217-5b3f-8961-7ecbe2d57bf5","source_key":"sample-story-9ff808df-b217-5b3f-8961-7ecbe2d57bf5","author_id":"34567fb1-7198-5a58-98e6-e977f17d8752","title":"Rehearsal","content":"CAPTAIN: We leave at dawn.\nPILOT: It's space.\nCAPTAIN: Metaphorical dawn.\nPILOT: We leaving at six then?\n\nI put the script down because nobody was taking this seriously. My spaceship was three chairs and a drying rack but I'd spent ALL lunch making the control panel. Josh had written BOOB ENGINE on it. We had eight minutes before assembly and the queen of Mars was in the toilet refusing to come out without her actual crown.","starter_sentence":"Someone forgets their line.","word_count":76,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-25T14:40:59Z"},{"id":"b9f35b63-3d04-5caf-a44d-0b13599533d2","source_key":"sample-story-b9f35b63-3d04-5caf-a44d-0b13599533d2","author_id":"ea6da2fe-b561-5aca-b34c-3a691d21a947","title":"first evening","content":"The first night I slept on the floor because the bed bolts were in the other van. Every time I rolled over the plastic under the mattress crackled. Upstairs someone walked from one end of the flat to the other, stopped, walked back. I tried to work out their rooms from the footsteps. Kitchen at the front, bedroom at the back, maybe a child who wouldn't settle. At three I went out onto the landing in my socks. The upstairs door was open and a man was carrying a sleeping baby around a pile of unpacked boxes. He looked as startled as I felt. We'd both moved in that day. Neither of us knew which bin was ours. We whispered about that for a while.","starter_sentence":"A new home has unfamiliar sounds.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-25T15:21:28Z"},{"id":"f017c9ac-7fa7-52c5-b82a-c51a541448e3","source_key":"sample-story-f017c9ac-7fa7-52c5-b82a-c51a541448e3","author_id":"e35ec7d7-1f8d-5028-b7d0-810249b008c8","title":"Wrong door","content":"'Before you say anything, I'm sorry.' The woman blinked at me. 'For what?' 'The thing with the bike.' 'What bike?' Wrong flat. I could have left then. I could have just said sorry again and moved on, but she was smiling and I started explaining the entire story. Including how I'd bent the wheel and tried to straighten it with a frying pan. She stopped smiling. Her husband came to the door. 'That was YOU?' Apparently the flats shared a bike cupboard. I had apologised to the wrong person in exactly the right place. The actual owner appeared behind me carrying the frying pan. I'd left it there. Didn't have a plan for this part.","starter_sentence":"An apology is interrupted.","word_count":115,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-25T22:17:14Z"},{"id":"ed91ba8d-2532-5c71-9a62-b4b5c5edeaa0","source_key":"sample-story-ed91ba8d-2532-5c71-9a62-b4b5c5edeaa0","author_id":"256be037-5e86-50ba-b5da-17a37ad173ae","title":"next stop","content":"bus is going the wrong way. well no the bus is going its way im on the wrong one. cant ask him again i already asked if this was the 6 and he said obviously. its a 9. why did he say obviously","starter_sentence":"Someone misses their stop.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-26T01:44:47Z"},{"id":"e698bb75-a5be-5dc9-ac28-70d12b8e7360","source_key":"sample-story-e698bb75-a5be-5dc9-ac28-70d12b8e7360","author_id":"d108af74-3071-56bf-9309-54dfc0c496ac","title":"borrowed magic","content":"The spell made everyone speak kindly for one day. Grandmother said that was a lovely idea right before it took effect, which should have warned us. By lunch she was telling the postman he had a beautiful large head. Mum complimented the neighbour's remarkably persistent dog. Nobody could ask anyone to stop doing anything. I tried telling my brother to stop eating the spell ingredients and called him a resourceful little treasure. He ate the whole jar. Now we don't know how to undo it.","starter_sentence":"A spell has a small side effect.","word_count":85,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-26T23:55:35Z"},{"id":"8abece9a-e48c-5147-90ec-d3d2ff49c0e0","source_key":"sample-story-8abece9a-e48c-5147-90ec-d3d2ff49c0e0","author_id":"d108af74-3071-56bf-9309-54dfc0c496ac","title":"winter apples","content":"The apple tree gave gloves that winter. Mostly left ones. We hung them in pairs where we could and gave the odd ones to people who'd lost a hand, but there were only two such people in the village and they didn't need forty gloves each. Father wanted to chop the tree down. Mother said wait till spring.\n\nIn March it grew sleeves. In April a whole coat. By June there was a man hanging upside down from the highest branch, asleep, with his shoes tied together. He wasn't a prince. We checked. He was a tailor from the next valley and he was very cross about the way we had pruned his fingers.","starter_sentence":"A tree gives something other than fruit.","word_count":114,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-27T02:29:42Z"},{"id":"d81d5378-0c69-569d-8c32-a980910d874d","source_key":"sample-story-d81d5378-0c69-569d-8c32-a980910d874d","author_id":"87026c76-9bb9-5539-80f7-1590581ecda2","title":"lunch","content":"Phone rang while I was eating. I answered with a mouth full of rice and said 'hello speaking' which isn't anything. They asked for someone called Martin. I said yes. Why did I say yes. Now I'm Martin and they've got a quote for my roof.","starter_sentence":"An interruption at lunchtime.","word_count":46,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-08-27T09:55:11Z"},{"id":"b68e8565-0cbd-5271-9cb4-23b713b84ec4","source_key":"sample-story-b68e8565-0cbd-5271-9cb4-23b713b84ec4","author_id":"ea6da2fe-b561-5aca-b34c-3a691d21a947","title":"Letterbox","content":"The letter was for the woman who used to live here. I'd returned the others but this one had a photograph sticking out, so I looked. A boy on a bicycle. On the back someone had written that he'd finally learned. I put it on the hall table and forgot it until the woman knocked on Saturday to ask about post. I gave her the bills first. I don't know why. When I handed her the photograph she held it by the edges and sat on the bottom stair without asking. I went to make tea. I wanted to give her privacy but it was my flat and the kettle was in the same room. She kept saying look at him, as if I knew who he was.","starter_sentence":"You receive a letter for someone else.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-27T14:58:19Z"},{"id":"68f1d44c-977f-5f93-9bf9-e56e3aa326de","source_key":"sample-story-68f1d44c-977f-5f93-9bf9-e56e3aa326de","author_id":"f98753ba-d6ed-5c8e-a28c-82603ffe6cf5","title":"signal check","content":"RX 04:18 / strength 0.7 / origin uncertain. That's the entry I made before I knew what I was hearing. We get all sorts through the receiver, old telemetry, other ships testing, someone once played a whole cooking programme into the emergency band. This was a person counting. Up to seventeen and back to one. Same breathing every time, which made me think recording. I put it through the noise filter and got a second voice, much quieter, saying ready or not. That shouldn't have upset me. Kids played that game everywhere. But the first voice counted fifteen twice. I used to do that. My brother always accused me of cheating. The ship computer wanted me to categorise the signal before it would store it and there wasn't a box for what I","starter_sentence":"A signal from space contains a familiar sound.","word_count":133,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-27T23:02:19Z"},{"id":"32239ee3-765d-552e-a86f-3ff14bb6c548","source_key":"sample-story-32239ee3-765d-552e-a86f-3ff14bb6c548","author_id":"d108af74-3071-56bf-9309-54dfc0c496ac","title":"the wish","content":"I wished that my brother would come back. The woman at the well asked which brother, and I said I only had one. She asked if I was certain. I was annoyed because this was supposed to be the sad part and she was making it complicated. Yes, I said. Then there were footsteps behind me. My brother was there, but small, the size he'd been before he went away. He had mud on his knees and wanted to know where his wooden horse was. I didn't know how to explain that I'd burned it after the letter came. The woman at the well had gone. He took my hand and asked why I was old. I started walking him home.","starter_sentence":"A wish brings someone back differently.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-27T23:16:15Z"},{"id":"e455465f-5946-556c-8660-30dc45697eb6","source_key":"sample-story-e455465f-5946-556c-8660-30dc45697eb6","author_id":"f98753ba-d6ed-5c8e-a28c-82603ffe6cf5","title":"Delay","content":"The delay is eleven minutes. I tell her I am safe and eleven minutes later she asks if I got hurt. So I say no and in the meantime she is telling me about the ambulance because she thinks I haven't heard. You can't interrupt. You can only make the message longer and worse. I keep watching the little upload bar. There are things I should have said before launch, ordinary things, mostly where the insurance papers are. I record those now. It sounds like I'm dying so I delete it and start with the weather.","starter_sentence":"A message arrives too late.","word_count":96,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-28T21:08:10Z"},{"id":"a91fc26d-d4ec-5f1a-8209-ebff64e136ee","source_key":"sample-story-a91fc26d-d4ec-5f1a-8209-ebff64e136ee","author_id":"a8550ec4-065a-5341-b089-3fb177637ffa","title":"worms","content":"worms all over the path. i tried putting them back on the soil but they kept coming out. maybe they know something i don't. the rain had stopped and the path was drying in little islands around them. one was so long i thought it was two stuck together. picked it up with a leaf and it contracted so hard i dropped it. sorry worm. my hands smelled of wet pennies after. there isn't really a story here i just spent twenty minutes doing this","starter_sentence":"A garden after rain.","word_count":85,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-29T02:11:37Z"},{"id":"1e5bd187-7706-5445-b3ef-509b0957e712","source_key":"sample-story-1e5bd187-7706-5445-b3ef-509b0957e712","author_id":"a8550ec4-065a-5341-b089-3fb177637ffa","title":"nest","content":"the nest was in the wheelbarrow. under the folded sack, not in the hedge where i thought birds were meant to build. three pale eggs, warm looking although i didn't touch them. i needed the wheelbarrow for the gravel. stood there being annoyed with a bird, then with myself for being annoyed. borrowed next door's. now i go round the long way to the shed becuase the mother sits on the fence and makes this noise like i'm the worst thing that's ever happened. i put a bit of string across the handles so nobody else uses it. dad thought it was a spider web and put his hand through. spent the afternoon waiting to see if she'd come back","starter_sentence":"You find something unfinished.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-29T02:56:37Z"},{"id":"f6b59953-3cb4-5ca4-b929-32161821c923","source_key":"sample-story-f6b59953-3cb4-5ca4-b929-32161821c923","author_id":"87026c76-9bb9-5539-80f7-1590581ecda2","title":"leaving card","content":"What do you write in a leaving card for a man whose name you learned from the leaving card. 'All the best' is taken four times. 'Good luck' three. Someone wrote 'onwards and upwards' which makes it sound like he's died climbing stairs. I started 'It's been a pleasure' and then realised I couldn't finish that honestly. It's been a pleasure sharing a printer with you Nigel. Except he always left the tray empty. Now I'm holding up the whole card chain and Carol is hovering. Wrote 'Enjoy the next chapter!' I don't know if he's got another job. Could be retiring. Could be going to prison. Chapters covers most things.","starter_sentence":"You cannot think what to write.","word_count":111,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-29T08:06:42Z"},{"id":"4dc2dfcf-3132-571b-bc8d-ab19311ac137","source_key":"sample-story-4dc2dfcf-3132-571b-bc8d-ab19311ac137","author_id":"35a4db28-6377-5741-90c1-ad9e7385b249","title":"update","content":"my laptop updated during the interview. FULL update not the little restart lie they tell you. i was mid sentence about being reliable and it just went blue. so i joined on my phone except i couldn't remember the password so now i'm on the phone to my own mother asking for the code because i used her email when i first made the account at uni. she keeps asking is this a scam rory. yes mum my whole professional life is a scam apparently. also the only decent shirt i own is still wet at the cuffs so im holding my arms out like a surgeon while she reads each number twice. she wants to know what the job is. i told her yesterday. she asks if theres a pension. MUM THERE WONT BE A JOB. finally get get back in and the interveiwer says these things happen which either means these things happen or it means you are never hearing from us again. then the laptop starts reading the welcome screen OUT LOUD because somehow ive turned on accessibility voice and","starter_sentence":"Technology fails at the worst possible moment.","word_count":183,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-29T20:30:10Z"},{"id":"7ee04034-43b4-596c-8f7d-be366091a2b9","source_key":"sample-story-7ee04034-43b4-596c-8f7d-be366091a2b9","author_id":"a8550ec4-065a-5341-b089-3fb177637ffa","title":"the apple","content":"one apple left right at the top. can't reach it with the ladder and it won't fall when i shake the branch. the leaves are mostly gone now. you can see the crow damage on it from the ground, one dark hole. i keep thinking something should eat it before it freezes. i could leave it alone. probably should. the tree does not need me to manage its last apple. but it's the first thing i check when i open the curtain and today the branch was bare and i felt annoyed that i'd missed whatever happened. checked the grass. nothing there either.","starter_sentence":"Something ordinary stays after everyone leaves.","word_count":103,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-30T00:36:18Z"},{"id":"a3a43ea1-2d91-5674-ac22-ba03c7b81917","source_key":"sample-story-a3a43ea1-2d91-5674-ac22-ba03c7b81917","author_id":"35a4db28-6377-5741-90c1-ad9e7385b249","title":"work chat","content":"it was only a screenshot of the rota. fine technically it was a screenshot of the rota with a message underneath saying he couldnt organise a piss up in an actual functioning pub but the rota was the MAIN content. now he's seen it and put a thumbs up. not angry not anything just that little yellow hand. i can live with being shouted at i cannot live with a thumbs up. i tried deleting it and it deleted from my side only so for everyone else it's still there and for me there's an empty space where my career used to be. alex has sent me 'mate' privatly. just mate. cheers for the emergency response team alex glad you're on it","starter_sentence":"Someone sends a message to the wrong group.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-30T20:48:34Z"},{"id":"b95ccd25-2fd5-57a6-89df-93e042f14b5e","source_key":"sample-story-b95ccd25-2fd5-57a6-89df-93e042f14b5e","author_id":"a189efa2-708b-5189-a654-1a850da08c16","title":"seat","content":"theres a seat next to her but her bag is on it so maybe she doesnt want anyone there. i could ask. i ask people things all day why is this diffrent. because if she says no i'll have to sit somewhere else and she'll know i tried. which is not actually a disaster. okay i'm going to ask. she looked up and moved the bag before i said anything and now i've forgot how to say thanks","starter_sentence":"You want to sit beside someone.","word_count":78,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-31T11:17:15Z"},{"id":"5c6cefe7-647e-5a87-96a4-4c83542bc608","source_key":"sample-story-5c6cefe7-647e-5a87-96a4-4c83542bc608","author_id":"a189efa2-708b-5189-a654-1a850da08c16","title":"the message","content":"i wrote hey about six times. hey sounds too casual but hello sounds like i'm selling something. i want to ask if she's angry with me but if she isn't then she might become angry because i keep asking. last time she said she was tired. people can be tired. i am tired right now from thinking about a text nobody's even received. recieved. i never spell that right. maybe just send a photo of the cat. that is how we used to talk before everything got difficult. the cat is asleep on my shoes. i'll take the photo and see.","starter_sentence":"A difficult message remains unsent.","word_count":101,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-31T12:24:46Z"},{"id":"a816370b-e763-51dd-aa01-92828a8b4eaa","source_key":"sample-story-a816370b-e763-51dd-aa01-92828a8b4eaa","author_id":"26cfcf4b-54e6-58e9-94c6-39fea415494e","title":"toll","content":"We had six gold crowns, a ruby and the royal seal, but the toll was two copper pennies. The dwarf would not change a crown. There was a shop back in the village, he said. We'd come through that village three days ago. Pell offered him the ruby outright. Now he thought we were trying to bribe him, which apparently had a separate fine. I sat on the bag of provisions while they argued. On the far bank the dragon had started burning the watchtower. You could see the smoke. The dwarf looked over his shoulder and said the bridge might be closing early. I asked whether that meant we could cross for free before it shut and he started explaining the difference between a closure and a waiver.","starter_sentence":"A quest requires exact change.","word_count":129,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-08-31T14:21:01Z"},{"id":"06bb4f17-f566-5424-a334-776d612c7eac","source_key":"sample-story-06bb4f17-f566-5424-a334-776d612c7eac","author_id":"35a4db28-6377-5741-90c1-ad9e7385b249","title":"Untitled Sprint","content":"been trying to return these headphones for forty minutes and the form asks what country they were manufactured in. why would I know that i bought headphones not a facotry. looked on the box it says designed in california which is where they want you to imagine them existing i guess. actually made in a warehouse of tiny wizards. put that in the box. now the form wont let me go back and i'm scared pressing submit will somehow make this legally binding","starter_sentence":"A small inconvenience takes over someone's day.","word_count":83,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-08-31T21:05:43Z"},{"id":"6eeb3947-92fc-564b-a3ec-f21e0d6f5bb6","source_key":"sample-story-6eeb3947-92fc-564b-a3ec-f21e0d6f5bb6","author_id":"a189efa2-708b-5189-a654-1a850da08c16","title":"partner work","content":"we had to make a poster about rivers. i drew the river and she did the writing. mine looked like a road so i coloured it blue. still a road really. we didn't talk much. i was trying to think of something to say the whole time and then the lesson ended","starter_sentence":"Two people are asked to work together.","word_count":52,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-01T09:41:57Z"},{"id":"ea3b9354-3356-59e0-8f24-7aac47d3f51a","source_key":"sample-story-ea3b9354-3356-59e0-8f24-7aac47d3f51a","author_id":"26cfcf4b-54e6-58e9-94c6-39fea415494e","title":"provisions","content":"We took eleven swords and no spoon. That sums it up really. I was only responsible for the maps but somehow everyone was angry with me about the spoon. Mira tried eating the stew with the flat of her dagger and cut her lip. We were one day into a journey supposed to last six months. I suggested carving spoons. Nobody had a suitable knife, despite all the swrods. By the time we got the fire going again the stew had become a black disc in the pot and a wolf had taken the bread. It didn't even run. It walked away while we were watching it because we'd all leaned our weapons against a tree on the other side of camp.","starter_sentence":"Someone packs badly for an adventure.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-01T15:51:06Z"},{"id":"b45493df-84be-5c44-bb19-cb14ebabdff4","source_key":"sample-story-b45493df-84be-5c44-bb19-cb14ebabdff4","author_id":"cbf08ff9-efeb-5af8-83f8-6c73633db4b0","title":"circling back","content":"The meeting has a meeting after it now. A debrief. Of THIS meeting, which was a pre-brief for Thursday. I can see Thursday filling up on the shared calendar while we're talking about how important it is to protect everyone's time. Somebody's cursor keeps moving my lunch. Yes, my lunch is on the calendar, becasue otherwise they put a meeting there. Now my lunch is at 4.15. I unmute to object and my mouth makes a noise like a dying printer because I haven't spoken in forty minutes.","starter_sentence":"A meeting runs over.","word_count":88,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-09-02T05:08:21Z"},{"id":"7af54417-b379-5253-9ed8-524aacf11dbf","source_key":"sample-story-7af54417-b379-5253-9ed8-524aacf11dbf","author_id":"cee893b5-d607-51b6-9dc7-a328f705d14c","title":"red boots","content":"She sat down in the puddle. Just sat. We had been arguing about going home for so long that I didn't understand what she was doing until the water came over her waist. She looked surprised too. Her red boots floated up in front of her. I pulled her out by the armpits and she began screaming, not because she was wet but because I'd taken her out. A man with a little white dog watched the whole thing. He said they grow up so fast. I nearly threw a boot at him. On the way home she fell asleep against my neck, wet all through her clothes. I could feel the cold through my coat. Her hand was still holding a leaf she'd refused to drop.","starter_sentence":"A child refuses to go home.","word_count":127,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-02T09:27:56Z"},{"id":"437c5ced-4d82-5594-9339-88da72d08a4a","source_key":"sample-story-437c5ced-4d82-5594-9339-88da72d08a4a","author_id":"cee893b5-d607-51b6-9dc7-a328f705d14c","title":"the bell","content":"The bell sounded wrong because it was the same. Everything else at the school was new: fence, windows, a whole extra building where the sandpit had been. But that awful metallic rattle still made my stomach do the thing. I was there for my niece's concert. Her teacher told us to line up outside the hall and I actually stood straighter. I'm thirty. I pay bills. A woman in a cardigan can still make me feel like I'm about to lose break time. Inside, someone had polished the floor and it smelled exactly like wet pencil shavings. My niece waved so hard her cardboard crown slipped. I waved back with both hands, which embarrassed my sister.","starter_sentence":"An old sound returns.","word_count":116,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-02T10:40:32Z"},{"id":"c4001a34-d4e0-50be-9de7-4b60c192c28c","source_key":"sample-story-c4001a34-d4e0-50be-9de7-4b60c192c28c","author_id":"26cfcf4b-54e6-58e9-94c6-39fea415494e","title":"Wrong cave","content":"There wasn't a dragon in the cave. There were bats, wet boots, and a very angry hermit who wanted to know why we'd kicked his door in. The map said HERE in red. I showed him. He turned the map over. More writing. 'Other cave,' it said. Pell said that hadn't been there before. He says that whenever we get lost. The hermit wanted four silver to repair the door and wouldn't accept a promise from the king. Sensible, to be fair.","starter_sentence":"A hero reaches the wrong destination.","word_count":82,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-09-02T18:02:38Z"},{"id":"2d58271c-503b-5292-bfcc-354af274019e","source_key":"sample-story-2d58271c-503b-5292-bfcc-354af274019e","author_id":"35a4db28-6377-5741-90c1-ad9e7385b249","title":"version two","content":"so version two of me would remeber to charge things. that is literally all i want from a clone. people always go oh but would it have a soul would it be you. don't care can it put the bike lights on charge. this version of me is tired. the clone can do monday to wednesday and i'll do thursday onwards. except then it'll want weekends which is fair but also defeats the point. maybe we alternate. now i'm inventing shared custody of my own life. it'd probably use all my good socks and tell people im the weird one. actually the more i think about this the more i think we need a third version to referee and that sounds expensive","starter_sentence":"Imagine sharing everyday life with a copy of yourself.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-02T20:21:43Z"},{"id":"3ff2f6b7-0d65-5dba-bb23-705c355f7a09","source_key":"sample-story-3ff2f6b7-0d65-5dba-bb23-705c355f7a09","author_id":"a189efa2-708b-5189-a654-1a850da08c16","title":"again","content":"went past the old school. gate was shut. couldn't see my classroom because there's a new building in front of it. thought i'd feel something more than annoyed about the building but i didn't really.","starter_sentence":"Return to a place you used to know.","word_count":35,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-09-03T08:17:02Z"},{"id":"4659c890-ea41-5009-9266-2eaf4fbbb4dc","source_key":"sample-story-4659c890-ea41-5009-9266-2eaf4fbbb4dc","author_id":"cee893b5-d607-51b6-9dc7-a328f705d14c","title":"Rain","content":"waiting for it to stop raining but it keeps starting harder just when it sounds like it might stop. the kitchen window is fogged at the bottom. drew a dog in it. looks like a chair. that's all i've got today.","starter_sentence":"Describe waiting indoors.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-09-03T10:54:13Z"},{"id":"31296b5b-15f8-57ac-9e48-60248e78dc78","source_key":"sample-story-31296b5b-15f8-57ac-9e48-60248e78dc78","author_id":"cee893b5-d607-51b6-9dc7-a328f705d14c","title":"the long way","content":"We couldn't get through the alley because somebody had built a gate. My cousin said it had always been there. It hadn't. We'd ridden scooters through that alley every summer. I showed her the scratch on the wall where I'd lost a handlebar, but the wall had been painted and the scratch was gone. She didn't remember the scooters either. She remembered bikes. I got stupidly upset upset. It wasn't even about the gate by then. We walked round the block in silence and found the corner shop was now a place selling expensive soap. She bought some. I waited outside trying to remember whether my scooter had been red or yellow, which made the whole argument feel worse.","starter_sentence":"A familiar shortcut has changed.","word_count":119,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-05T00:42:12Z"},{"id":"4df8eb4f-e449-56c9-bda5-3e5dc1186a68","source_key":"sample-story-4df8eb4f-e449-56c9-bda5-3e5dc1186a68","author_id":"a189efa2-708b-5189-a654-1a850da08c16","title":"one good thing","content":"the bus driver waited. i was running and i know he saw me ages before i got there because he was looking in the mirror. usually they pretend they cant see you. i said thank you too loudly and sat right at the front because my legs felt weird. then i realised i had the wrong ticket and he just waved me on. i nearly cried which is stupid, it's a bus ticket. had been a horrible day before that. i don't want to write all of it down. i just want to remember that someone waited when he didn't have to.","starter_sentence":"Something small improves a bad day.","word_count":102,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-09-05T11:56:58Z"},{"id":"c0cd9c24-e653-5fa2-8b01-e105bc479dc5","source_key":"sample-story-c0cd9c24-e653-5fa2-8b01-e105bc479dc5","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"03:17","content":"He wanted a bottle of water but wouldn't come through the door. I held it up from behind the counter. This one? He nodded. I took it outside and he counted coins into my hand, very slowly, looking over my shoulder. There was nobody in the shop. I checked anyway. He asked if the lights were always that bright. I said yes. He said I used to work here. The bottle slipped out of his hand and rolled under a parked car before he'd opened it. Neither of us moved to get it. I could see his feet properly now. One shoe was tied and the other had no lace. I asked if he needed me to phone someone. He shook his head so hard I stopped asking.","starter_sentence":"A late-night customer wants something small.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T02:03:38Z"},{"id":"7dfb6936-142f-5062-9150-54e2ad12eb05","source_key":"sample-story-7dfb6936-142f-5062-9150-54e2ad12eb05","author_id":"a63b3511-769e-54e5-9253-ce29cd08d1b7","title":"the other route","content":"I can get to the hospital three different ways and I have begun to think choosing the right one might affect what happens there. I know that isn't sensible. Last Tuesday I went by the canal and the news was good, today there is a barrier across the towpath and I am standing in front of it arguing with nobody. A man in a yellow jacket says the bank has slipped. I ask how long the diversion is. He says ten minutes. I say I don't have ten minutes though I left an hour early specifically so I would have time to sit outside and not go in. He is waiting for me to move. Behind him a duck is standing in the middle of the broken path, and I wish I could explain this without sounding like a person who needs help herself.","starter_sentence":"Walk towards a place you have been avoiding.","word_count":144,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T03:10:36Z"},{"id":"4af3f0e4-4bed-5632-9daf-0dc3b9099702","source_key":"sample-story-4af3f0e4-4bed-5632-9daf-0dc3b9099702","author_id":"049b6e2b-ab51-5bea-93ea-bd5edee32b3d","title":"Platform change","content":"'This isn't our train.'\n'It's got our number.'\n'Look outside.'\n\nNo platform. No tracks either. A field going backwards under us, cows standing with their heads up.\n\n'Get the guard.'\n'You get him.'\n\nThe boy at the other table was filming. His mother slapped the phone down.\n\n'How long?' I asked her.\n\nShe looked at the window.\n\n'Since Derby.'","starter_sentence":"Two travellers realise they were sent to the wrong place.","word_count":59,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T03:48:33Z"},{"id":"10bb4ffa-8daa-5e71-b1c7-6c6962301101","source_key":"sample-story-10bb4ffa-8daa-5e71-b1c7-6c6962301101","author_id":"a4fe032c-ebcc-5b12-99b8-2cdf9a0bdd0f","title":"in my defence","content":"I took my microwave home. Mine. Bought with my money in 2019. Apparently this makes me the villain because twenty-seven people now have cold lunch. Twenty-seven poeple who watched me clean somebody's exploded fish out of it on Friday and said nothing. There is a kitchenette FUND. Use the fund. They say the fund is for essentials and I say excellent, you've just discovered an essential. I'm eating hot soup at home while they discuss me in the group chat. Someone has used the word community. About my microwave.","starter_sentence":"You are the villain. You are also completely right.","word_count":89,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T08:23:05Z"},{"id":"163ca57a-1ed1-55da-8f5b-a2d472b85914","source_key":"sample-story-163ca57a-1ed1-55da-8f5b-a2d472b85914","author_id":"b3202ae3-0a6d-5560-af9b-5751e9f739f0","title":"The water budget","content":"The tank was down eleven litres. I assumed a leak until I found a child's sock in the laundry intake. There were no children on the manifest. I showed it to Hale. She sat down very slowly and asked me to close the hatch. Her son was asleep behind the insulation in her cabin, thin enough to fit where an adult couldn't. She had been sharing her ration with him for nineteen days. We were beyond the return burn. I told her we had to tell the captain. She said yes, then asked for one hour. Not to escape, there was nowhere to go. She wanted to wash him first. I gave her my water card and went to the bridge without her.","starter_sentence":"A space crew discovers a hidden passenger.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T11:30:34Z"},{"id":"4db8450a-70ae-5a6d-9500-8d28bec64df3","source_key":"sample-story-4db8450a-70ae-5a6d-9500-8d28bec64df3","author_id":"dcb01423-22d4-5fdc-8baf-e69da01aac45","title":"away game","content":"They said we brought an older player but Samir is fourteen he is just tall. The other coach wanted his birth certifcate like he would have it in his socks. Then Samir takes his boots off and says hes not playing. I tell him put them back on we need him. He says thats all anyone says.\n\nHe walks right past the bus and out the gates. Coach sent me after him. When I caught him he looked at the captains band first before my face. I took it off. Now I have to say something.","starter_sentence":"Write a scene in which someone is accused of cheating.","word_count":96,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T11:40:13Z"},{"id":"70721ab0-004c-56d9-a1c3-21852f2a6510","source_key":"sample-story-70721ab0-004c-56d9-a1c3-21852f2a6510","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"reserved apparently","content":"someone was in 14A and i had 14A on my tikcet so i did the awkward thing where you stand there holding it at chest height like a tiny warrant. he looked up and said this is 14A. yes i know. that is the issue. he showed his ticket, also 14A. same train same date. i was trying to be normal about it but he'd already taken his shoes off and i resented that more than the actual seat. the guard came and looked at both tickets and said one of you booked backwards. what does that even mean. then the train started moving the wrong way, not backwards along the track, sideways, through the people standing on the platform who didnt seem to notice. the man put his shoes back on very quickly and said let her have it.","starter_sentence":"Someone is sitting in your seat.","word_count":140,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T12:42:36Z"},{"id":"5ec4b3e3-46ed-5038-8752-1de190d6caf4","source_key":"sample-story-5ec4b3e3-46ed-5038-8752-1de190d6caf4","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"Outside ward C","content":"The sparrow was pulling at the yellow foam in a gap above the window. It got a piece loose, dropped it, tried again. I had been watching for perhaps ten minutes before I noticed its foot. Three toes on one side, none on the other. It rested that side on the sill like a little fist. Inside, my uncle was explaining something to a nurse very slowly, in the voice he uses for people he thinks aren't listening. She was listening. He was repeating himself. The bird came back with another bird and they argued over the gap. I wanted to tell my uncle about the foot but he was still talking. Then the nurse asked him a question he didn't answer, and I stopped looking out. His hand was flat on the blanket. There was a brown mark at the base of his thumb I hadn't seen before.","starter_sentence":"Notice something outside a hospital window.","word_count":149,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T13:19:36Z"},{"id":"96947821-c42e-5325-a689-305b12d43a1c","source_key":"sample-story-96947821-c42e-5325-a689-305b12d43a1c","author_id":"7889cb6b-b2b4-599b-b86e-5519eb0a5b9a","title":"inside the hem","content":"Coins in the hem. Cora felt them knocking her knuckles as she lifted the skirt. She cut two stitches. A silver disc fell out, stamped with a face from the news. Not a coin. The girl on the chair stopped swinging her feet. Where had the dress come from? Her mother had said bring it here and wait. A car stopped outside, engine running. Cora put the disc in her mouth before she could think why. It tasted of soap. She told the girl to get under the cutting table.","starter_sentence":"A repair reveals evidence someone needs.","word_count":90,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T14:04:17Z"},{"id":"e6b339d0-c1f3-5b45-9f83-5fc0b4c35e19","source_key":"sample-story-e6b339d0-c1f3-5b45-9f83-5fc0b4c35e19","author_id":"4e915f8d-f5e6-5536-bb28-03e5dde5616d","title":"Room 206","content":"The key turned at 2:11. I was awake because of the pipe over the bed. A man came in carrying his shoes. He saw me, stopped, looked at the door number from the inside as though it might be written there. I said wrong room. He said no. We waited. He put his shoes down very carefully and went into the bathroom. I could hear him opening the cupboard. My phone was on the desk beyond him. I got out on the other side of the bed, kept the mattress between us. When he came out he was holding a woman's bracelet. He said where is she. I said I checked in at nine. He looked at the empty half of the bed and sat on the floor.","starter_sentence":"A hotel guest hears someone enter the wrong room.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T14:08:15Z"},{"id":"9e114611-93a5-59d1-aa91-a418b27d7ab8","source_key":"sample-story-9e114611-93a5-59d1-aa91-a418b27d7ab8","author_id":"ae8577b0-b86b-57de-b55c-da9bb0393055","title":"not a big deal","content":"i wasn't even laughing at her. i was laughing at something on my phone but she'd already decided and then everyone looked at me. i tried showing the phone and it had locked so now i'm doing my passocde wrong while she says forget it. no i dont want to forget it i want you to know i didn't do it. except chasing someone down a corridor saying i wasn't laughing at you looks exactly like something a person who was laughing at you would do","starter_sentence":"You are explaining yourself to someone who has already made up their mind about you.","word_count":86,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T15:15:22Z"},{"id":"772c834a-e411-57bb-8aca-867b3338c566","source_key":"sample-story-772c834a-e411-57bb-8aca-867b3338c566","author_id":"55f79dc6-f9c9-5a93-b44d-1f4ca2d44981","title":"Relay 8","content":"At 04:12 the receiver spat gravel. Real gravel, three pieces, hot enough to blister the desk. There isn't an opening in the casing wide enough for them. I unplugged it and got the same transmission, the voice counting down from eight. Seven. Six. I put the whole unit in the sink. Five. It isn't a bomb, I kept thinking, a bomb wouldn't need you to hear it. Four. The drain started sucking air. I could see daylight through it, a square of orange sky below the U bend. Three. I went to get my camera which was such a stupid thing to do because when I came back the sink was empty and the countdown was coming from my mouth.","starter_sentence":"A signal arrives with a physical side effect.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T16:31:54Z"},{"id":"a0d3ca63-290a-5ab2-9335-0c219a7f2194","source_key":"sample-story-a0d3ca63-290a-5ab2-9335-0c219a7f2194","author_id":"316eed8d-f125-5a1b-8346-6d608fb46e5c","title":"South of the Glass","content":"The egg was getting heavy. It had been small enough to fit in Eda's coat when she stole it, now she had to roll it along the road and it left a groove in the dust. She kept saying sorry to whatever was inside. At the river the ferrryman wouldnt take her. He could hear tapping. Eda could hear it too but she said it was stones in her shoes. That wasn't a good lie, she had no shoes. The egg rolled a little closer to the water by itself. Across the river the trees bent backwards all at once, and the ferryman dropped his rope. She jumped in his boat while he was looking. There was room for her or the egg. She hadn't thought about that.","starter_sentence":"A young traveller must carry something dangerous.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T16:54:20Z"},{"id":"76023d92-4aa4-5e39-a51d-f550ea34ece7","source_key":"sample-story-76023d92-4aa4-5e39-a51d-f550ea34ece7","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"dont send","content":"typed are you coming then haha so it looked less angry. worse. dinner's nearly ready? too domestic. only four dates, one was accidentally at a party. made pasta for six because i didnt trust the packet. now stuck together in the sink. typing dots appeared then went away. put phone in cupboard. took it out becuase what if i couldnt hear. he sent a bent bike wheel. i said oh no are you okay then felt pleased which is horrible. he had a reason. i was reheating pasta already before he'd answered whether he could still get here. should have asked about his leg first.","starter_sentence":"Write a message you keep changing in your head.","word_count":105,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T17:12:27Z"},{"id":"b9ee4385-a4ad-5a77-8bee-f54c9c7389d7","source_key":"sample-story-b9ee4385-a4ad-5a77-8bee-f54c9c7389d7","author_id":"76ddfafa-74ee-5075-8521-1c0f3727a98c","title":"A small discrepancy","content":"Fourteen pounds short. Again. I took four payslips to Ruth. She said payroll was complicated. I said multiplication wasn't. Wished I hadn't because she gives me Saturdays off. She asked me to leave it with her. I wanted the papers back. I had written bus fares on the back to show why fifty six pounds mattered. She turned one over and read them. I felt stupid. Shouldn't have to explain why I want money I've worked for. But I explained and she kept nodding and nothing got agreed.","starter_sentence":"A person notices their workplace owes them money.","word_count":88,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T17:23:10Z"},{"id":"b183130e-2c8a-50a3-bfed-97108647b3d8","source_key":"sample-story-b183130e-2c8a-50a3-bfed-97108647b3d8","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Replacement hero","content":"The chosen one had a dentist appointment so they sent me. This sounds stupid but he'd already cancelled twice and they'd charge him the full amount, which the prophecy budget apparantly didn't cover. I had his cloak and a letter saying I was acting on his behalf. The cave didn't accept letters. It spoke directly into my teeth, ALL WHO ENTER MUST BE NAMED, so I said Gus and it said WRONG. I tried his name. Wrong. Tried his full name including the middle bit he hated. Still wrong. By now the horse had started eating the letter and I was wondering if maybe named meant like given a special name by the gods. I said Sword of Morning. The cave made a noise that could have been a laugh. Behind me the horse said Gerald. The cave opened. I stared at the horse. The horse stared back with a corner of the letter hanging out its mouth. Fine. Gerald goes first then. Except Gerald refused because he'd never agreed to be a hero, he'd agreed to carry luggage, and now we were having a labour dispute outside a talking hole while somewhere in town the actual chosen one was getting a filling.","starter_sentence":"The chosen one cannot make it.","word_count":203,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T18:32:28Z"},{"id":"593e4256-0782-564d-a0f4-2862bfdd7710","source_key":"sample-story-593e4256-0782-564d-a0f4-2862bfdd7710","author_id":"1bd72f15-96d8-5538-ba67-5a265af316fc","title":"allotment seven","content":"Dug up a spoon, two batteries and then a jaw. Bottom bit with teeth. I fetched Mr Bell. He said fox. I said it's got fillings. He took his glasses out. After a bit he brought a bucket. I didn't think we should move it. He said we couldn't leave it for the children. No children there but I understood. Rang the allotment number. A woman asked whether I'd paid my fees. I said yes and tried again about the teeth.","starter_sentence":"A gardener finds something unexpected in the soil.","word_count":81,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T20:40:04Z"},{"id":"e0b47ffe-24ea-590c-a466-61ab1f387bc5","source_key":"sample-story-e0b47ffe-24ea-590c-a466-61ab1f387bc5","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"don't open it yet","content":"There was a brushing sound behind the door. Not a brush exactly. Something softer dragging in little starts across the floor. I put my ear against the paint and then regretted it because whatever it was stopped at once. My hand was still on the handle. I could feel my own pulse in the metal, or thought I could. The room was empty when we moved in. I keep writing empty but it had a bedframe and three bags of clothes, so that isn't empty. We had shut it because of the smell. My sister came up the stairs carrying a glass of water and I signalled her to be quiet. She stepped over the third stair. We have always stepped over that stair, I couldn't remember why. She handed me the glass and it was full of hair. No, I don't like that. It was just water. She wanted me to drink it before she told me something.","starter_sentence":"A sound comes from a locked room.","word_count":159,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T21:22:46Z"},{"id":"a477bd37-7e7d-537c-99c6-0053eb0b3537","source_key":"sample-story-a477bd37-7e7d-537c-99c6-0053eb0b3537","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"wrong gate","content":"The gate was tied with string and there was a sign saying bull in field. Couldn't see a bull. There was a sheep but I do know the difference. I climbed over because the footpath arrow pointed that way and ten minutes later came to the same gate from the other side. That can't be right because I'd only walked downhill. I went back to the top and tried again paying attention this time, past the water trough, left at the dead tree, through the muddy bit and there it was. Same string same sheep. I rang Pete but he was driving and said follow the map. I had followed the map. The sheep came right up and started chewing the strap on my bag while I was talking. I pushed it off and it followed me when I tried the other direction. Then I had the additional problem of somebody else's sheep.","starter_sentence":"A walk begins with a small obstacle.","word_count":153,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-05T23:21:18Z"},{"id":"e1197072-94f7-5f97-b676-39bf29722018","source_key":"sample-story-e1197072-94f7-5f97-b676-39bf29722018","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Five seconds ahead","content":"Five seconds sounds useful until you try crossing a road. I saw myself get hit, stopped, then saw myself standing there not getting hit, so started, then saw the car again. I spent forty minutes at that crossing. Eventually a child took my hand because she thought I was frightened. I was frightened. She pulled me across and for five seconds I saw her grown up, which wasn't how it was supposed to work at all. I let go halfway. Car horn, shouting, her mother grabbing both of us by the coats. I tried to explain about the child but the mother thought I was making excuses. Then I saw her face five seconds ahead and it was mine. I hadn't figured out the rules properly. Maybe that was the problem with having a power nobody had tested.","starter_sentence":"You can see five seconds into the future.","word_count":138,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T00:04:55Z"},{"id":"f2108101-e029-5acc-ab93-0fdf5ad10b54","source_key":"sample-story-f2108101-e029-5acc-ab93-0fdf5ad10b54","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"half past six","content":"The cleaner needed the keys but Colin was still in the office. He said he was waiting for an email. The cleaner said he could get emails at home. Colin said it was confidential. This was not true. He was waiting for the car park to empty because he had hit someone's car and he wanted to see whose it was without standing beside it. From the upstairs window he could only see the roof. It was blue. There were three blue cars and he had forgotten which bay. At six thirty the cleaner came upstairs with a mop and said the manager had called to ask who was still there. Colin said just me. She said I know that, what should I tell him. He did not have a good answer.","starter_sentence":"Someone delays leaving work.","word_count":132,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T00:56:17Z"},{"id":"1d3e6c77-f00a-57f4-ae52-7eca4a5dd177","source_key":"sample-story-1d3e6c77-f00a-57f4-ae52-7eca4a5dd177","author_id":"0b4f9787-dc5c-5e47-ba2a-09ff695b34ac","title":"the group chat","content":"I told everyone except Liv. Not on purpose at first but then it got more awkward every day. The others assumed she knew because of course she would know. She found out in the group chat when somebody asked if I needed boxes. She typed 'boxes?' and I watched the little typing thing appear and disappear under my own name because I kept writing and deleting. In real life I would have laughed and made it smaller somehow. In the chat there was just the word boxes sitting there. I called her. She didn't pick up. I sent sorry then a longer thing then deleted the longer thing. Now it says message deleted which looks worse than anything I could have written.","starter_sentence":"A person realises they have left out an important fact.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T01:57:10Z"},{"id":"19158379-96e8-5e68-8f26-4b0dc52c276b","source_key":"sample-story-19158379-96e8-5e68-8f26-4b0dc52c276b","author_id":"a4cda7f0-ae9c-5f75-8c2b-99f55a17d4cc","title":"Survey 14","content":"We survey the cellar twice. North wall 4.2 metres. South wall 4.2. Distance between them, six. Outside the entire house is only five metres deep. I check the laser against the tape. Same readings. Nina says perhaps the cellar extends under the pavement. It doesn't. I draw the outline on the floor in chalk, using the upstairs measurements, and there's a strip of dark concrete left over. No pipes, no drain. Just the extra metre. Nina puts one foot across the chalk line. Her radio cuts out. She takes it back. The radio works. We agree not to step over again. Then she tells me she has left her tape on the other side and I can see it moving away from us.","starter_sentence":"A map is accurate in a way it should not be.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T03:17:24Z"},{"id":"8ec8db9a-e7d0-5c88-a5ed-ec176aaccfc4","source_key":"sample-story-8ec8db9a-e7d0-5c88-a5ed-ec176aaccfc4","author_id":"ed95f9f4-57c6-5a55-8be0-7d54206b565d","title":"under the shed","content":"Dust in the mouth first. Then the undersides of the boards, each dark ring of a knot looking closer than it should. I had thought there would be room to turn my head. There isn't. The kitten has gone quiet and I can't see beyond the pipe. With one cheek flat against the earth I can hear traffic through the ground, a heavy soft noise, quite different to being above it. I push the saucer ahead of me. It tips. Milk soaks into the soil before I can reach it. Now my elbow is stuck against something sharp and I have to go backwards.","starter_sentence":"Describe a very small place from inside it.","word_count":104,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T07:19:24Z"},{"id":"c6c42387-c4f9-5ee4-819f-260ad353eebc","source_key":"sample-story-c6c42387-c4f9-5ee4-819f-260ad353eebc","author_id":"a4fe032c-ebcc-5b12-99b8-2cdf9a0bdd0f","title":"chair situation","content":"If you sit in a chair long enough do you own it. Asking because Martin has put a cushion on mine and now everybody calls it Martin's chair. I was off for TWO DAYS. I moved the cushion. He moved it back. We're communicating entirely through soft furnishings. Today I put my coat there before nine. At nine fifteen it was folded neatly on the printer. He's being polite which is cheating. I need him to be rude so I can be rude back.","starter_sentence":"Someone claims an object by using it.","word_count":84,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T08:23:08Z"},{"id":"322a3c81-e925-5c6b-a6d6-6747eb17c484","source_key":"sample-story-322a3c81-e925-5c6b-a6d6-6747eb17c484","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"It says FLO","content":"I opened it because it said FLO on the label. It actually said FLOOR 2 but the label was folded so I feel this is a shared mistake. Inside were twelve very expensive looking wigs. Not one wig which you could easily repackage. Twelve, all compressed together like a small sleeping animal. I pulled one out to see what it was and they sort of expanded. By the time I realised I had no chance of getting them back in, someone was at the door. I answered wearing one. I don't know why. Panic isn't always running away sometimes its putting on hair. The woman upstairs looked at me for ages and said have you seen a parcel. I said what sort. What SORT. She pointed at my head. I said I can explain but it was actually a fairly complete explanation already.","starter_sentence":"Open a delivery meant for someone else.","word_count":143,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T08:55:50Z"},{"id":"82c21adc-7711-53ca-8f59-732815fc9899","source_key":"sample-story-82c21adc-7711-53ca-8f59-732815fc9899","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"six months of lentils","content":"The crate was marked medical so of course we left it sealed while we ate the insulation off the biscuit packs. Turns out it contained lentils. Forty kilos of lentils and a little bag of cinnamon someone had tucked into a corner. I wanted to hug the bag. Pavel wanted to know how we were supposed to cook them without using our drinking water. I said soak them in the coolant. He thought I meant it. That's how bad things had got, we were seriously considering the coolant. We put one mugful in the pressure chamber with steam from the laundry vent. They came out hard in the middle and tasting of everyone's socks. We ate them anyway. Then the chamber door wouldn't shut and the pressure light came on and I was trying to scrape a lentil out of the seal with my fingernail when Pavel said","starter_sentence":"A space crew receives the wrong supplies.","word_count":148,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T08:56:58Z"},{"id":"e90d5e77-c761-5cf9-b00a-34955014732b","source_key":"sample-story-e90d5e77-c761-5cf9-b00a-34955014732b","author_id":"c4ddf376-4b92-5716-a61f-6e79b3d388a6","title":"the arrival","content":"She was coming at six. By half five we had argued about towels, the chair and bathing the dog. He said I was making a fuss. Hadn't seen her in eight years, could make a small fuss himself. He moved the car. I moved the chair again. No good place for it. Room still looked like an office with a bed delivered by mistake. I took the calendar down. At six the dog barked and I realised we hadn't talked about what to call each other in front of her.","starter_sentence":"A family prepares for a visitor and argues about the wrong thing.","word_count":90,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T15:05:15Z"},{"id":"72ee6f58-c85a-5c72-b723-836d4e2742e3","source_key":"sample-story-72ee6f58-c85a-5c72-b723-836d4e2742e3","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"First train home","content":"People were getting on with coffees and clean hair. I had fryer smell in my sleeves. A woman sat next to me, then got up again when another seat came free. Fair enough. I closed my eyes and counted stations by the bends. Missed mine anyway. At the next one I got off, crossed the bridge, waited on the other side. The same woman was there. She'd missed hers too. We didn't speak but I felt slightly better about the whole morning.","starter_sentence":"Travel while everyone else is waking up.","word_count":82,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T17:47:28Z"},{"id":"e584dc77-edf5-5bdc-9727-73c68016ca85","source_key":"sample-story-e584dc77-edf5-5bdc-9727-73c68016ca85","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Borrowed jumper","content":"it was his jumper but it didnt smell like him anymore because i'd washed it about ten times. he asked for it back and i said of course then couldnt find it. looked everywhere. it was on me. i was wearing it while looking for it. i don't think this needs to mean anything i'm just very tired.","starter_sentence":"Borrow something and forget to return it.","word_count":58,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T18:40:38Z"},{"id":"f03c28cb-4fb6-5983-920c-eeb6c8046afa","source_key":"sample-story-f03c28cb-4fb6-5983-920c-eeb6c8046afa","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Radio off","content":"Turned the radio off because the same advert had played four times. Without it I could hear someone coughing in the stockroom. Went to look. Nobody. Turned the radio back on and stayed near the front until six.","starter_sentence":"An ordinary sound keeps you company.","word_count":38,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T18:51:37Z"},{"id":"6eb01545-7274-53f0-8458-6f4134c6acc2","source_key":"sample-story-6eb01545-7274-53f0-8458-6f4134c6acc2","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Rust colour","content":"The rust came off in orange powder and underneath was more rust. Mara had expected bright metal, a reward for the work, but the chair seemed to be rust all the way through. She scrubbed harder. Her wrist ached. There was an insect living in the hollow leg and every time she tilted it the insect came out to look, then went back in. It had a white body and no obvious head. She tried not to think about it. The afternoon was thick, sticky, I mean the air was thick not the afternoon. She had promised the chair to someone and couldn't remember who. It was an excuse she'd given herself for bringing it home. A project. Something to do with her hands. Now her hands were orange and there was a hole where the seat joined the frame.","starter_sentence":"Restore something old.","word_count":140,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T20:26:15Z"},{"id":"6089e887-ad7d-5eba-86a8-6239ca1cc5bf","source_key":"sample-story-6089e887-ad7d-5eba-86a8-6239ca1cc5bf","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"The display","content":"They moved the baby clothes where the shoes had been. The shelves were too deep. Anna said so but nobody changed them. A woman wanted a size they didn't have. Anna looked in the returns bag anyway. There was one shirt, with her own surname written on the label. It wasn't a common name. She checked it again.","starter_sentence":"A shop rearranges something familiar.","word_count":58,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-06T22:01:01Z"},{"id":"79ae637a-1148-5066-b6e6-e4475b3baae6","source_key":"sample-story-79ae637a-1148-5066-b6e6-e4475b3baae6","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"Red marks","content":"The red marks had been painted on the trees recently because some of it was still on the grass below them. I followed them for a mile maybe two, lost count of the bends. Then there was a red mark on a rock in the stream. I crossed to it and couldn't see the next one. Went up the bank on the other side and found an old jacket hung on a branch. Same colour red. This was getting a bit daft. I went back to the stream and noticed the rock wasn't painted, it was stained. Clay I think. So I'd probably stopped following the path a good while back. My phone had eleven percent and all the maps were just grey squares. I sat on the bank and ate the sandwich I'd been saving for the top. Cheese had got warm. I could hear a road somewhere uphill but it might have been the water.","starter_sentence":"A marked route becomes unclear.","word_count":157,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T01:23:59Z"},{"id":"949a783a-8b5f-5e24-ac19-1490e364ade7","source_key":"sample-story-949a783a-8b5f-5e24-ac19-1490e364ade7","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Portal behind the cooker","content":"The portal was only wide enough for a plate. We sent a plate through. It came back washed. Sent another, same result. For six weeks this was excellent. Then a bill came through. The currency was teeth. We stopped sending plates. Whoever was on the other side started knocking.","starter_sentence":"A portal opens in your kitchen.","word_count":49,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T01:32:43Z"},{"id":"591dc252-d416-53a3-863a-cc584ea1df16","source_key":"sample-story-591dc252-d416-53a3-863a-cc584ea1df16","author_id":"0b4f9787-dc5c-5e47-ba2a-09ff695b34ac","title":"bad draft","content":"I miss you but not like that. Or maybe like that sometimes but that's not why I'm writing. \n\nI found the blue bowl and thought you might want it. No that sounds like an excuse. It is an excuse. You don't even like that bowl. I should just say hi. It's been four months and I have made saying hi into a thing that needs three paragraphs and apparently a bowl.","starter_sentence":"Write the message you cannot send.","word_count":71,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T01:35:12Z"},{"id":"1e012eaa-443c-5099-8668-17d34df19103","source_key":"sample-story-1e012eaa-443c-5099-8668-17d34df19103","author_id":"e14f7eb4-fd33-5626-930b-36d455de8584","title":"the wrong holiday","content":"I remember the sea being green. My brother says it was a reservoir and we weren't allowed in. But there was a man selling rubber rings. Why would he sell them there? He says I'm combining two holidays. Probably am. Dad bought a yellow ring and it deflated before we reached the car. Unless that was the holiday with Joan. There are three photographs of the same wall and none of the thing I want to remember.","starter_sentence":"Two people remember the same event differently.","word_count":77,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T02:11:03Z"},{"id":"2fcfa801-0842-5550-b176-0e60c6741093","source_key":"sample-story-2fcfa801-0842-5550-b176-0e60c6741093","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"not calling","content":"i had the number open because i was trying to remember the postcode. that was the excuse. walked past the station twice and on the second time a man asked if i was lost. said a bit so he started giving directions and now i had to go that way. her flat was the other way. could've called from somewhere i hadnt meant to be. could've said i left a bag. there wasn't a bag. there was but it was hers.","starter_sentence":"You almost call someone.","word_count":81,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T03:07:35Z"},{"id":"82db7645-5938-5c8f-a9d7-da6d9884ee09","source_key":"sample-story-82db7645-5938-5c8f-a9d7-da6d9884ee09","author_id":"4e915f8d-f5e6-5536-bb28-03e5dde5616d","title":"Fire route","content":"Smoke in the corridor. Not thick, just enough to hide the far door. Kit crawled with one hand against the skirting board. Room numbers were useless down there. She counted doorways instead. Four, five, the stair should be next. Her hand found a gap and she pushed through onto cold concrete. No smoke here. She stood and started down. At the first landing the door was locked. At the second, chained. She kept going. The alarm sounded distant now, above her, and the steps were wet. There was a light under the next door. She hammered with both hands. Someone on the other side said we're closed. She screamed fire and the voice said we know.","starter_sentence":"A person escapes a building by an unfamiliar exit.","word_count":116,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T03:54:59Z"},{"id":"9d4c68e2-03a5-56ed-ac06-da1314429896","source_key":"sample-story-9d4c68e2-03a5-56ed-ac06-da1314429896","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"wrong screws","content":"The hinge had come away because someone used the screws supplied with it. Those are for putting the thing in the packet, I swear, not for actual wood. I drilled out the holes and pushed dowel into them with glue. You have to leave that overnight. My brother said he needed the door back on tonight. I said then he should have phoned yesterday. This is how most of our conversations go now. He brought a chair into the hall and sat watching while I looked for the old tin of longer screws. His knee made a cracking noise when he sat. I was going to ask about it but he started telling me which drill bit to use, and I went back out to the van.","starter_sentence":"Repair something that keeps breaking.","word_count":127,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T07:42:07Z"},{"id":"450a9d2f-02eb-5dd0-8d1a-5d57d93d7649","source_key":"sample-story-450a9d2f-02eb-5dd0-8d1a-5d57d93d7649","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"free surface","content":"Gravity went while I was swallowing. I don't know why that surprised me more than the hot soup lifting out of the bowl but it did. There was this horrible second where I thought swallowing needed gravity. It doesn't. The soup hit the ceiling in a long orange ribbon and began coming back down, not down, towards the fan. Everyone started grabbing towels. Except the new medic who grabbed a spoon and was trying to catch mouthfuls. We had explained the fans on day one. You cannot let liquid into that fan. I threw my towel at his head and he shouted at me, then the fan coughed and we had soup mist in every room including the room with the exposed sample trays. Six months of fungus research now contained carrot. Dr Iven was standing in the doorway with her glasses all orange and I honestly couldn't read her expression.","starter_sentence":"A meal is interrupted by a technical fault.","word_count":151,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T09:37:58Z"},{"id":"97ef6510-da66-5a9d-8cbe-9403364978ea","source_key":"sample-story-97ef6510-da66-5a9d-8cbe-9403364978ea","author_id":"36f4bd03-8d21-53ed-b13f-f6c05fcf9f21","title":"not our house","content":"We went into the wrong house. Same estate, same brown doors. Dad walked in so I went straight upstairs. Sat on what I thought was my bed. There were different posters. I thought Mum had changed things. Then a boy came in. We looked at each other. Downstairs Dad was apologising. I was sad to leave. This boy had a desk by the window, a silver plane hanging above it. Our room had no space for a desk. I haven't thought about that for years. Plane might have been red actually. I remember the shadow it made.","starter_sentence":"Remember entering a place that looked familiar.","word_count":97,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T10:14:15Z"},{"id":"a4eb7cc4-ebdd-5a09-a84d-2ffd4dc3bf6f","source_key":"sample-story-a4eb7cc4-ebdd-5a09-a84d-2ffd4dc3bf6f","author_id":"7889cb6b-b2b4-599b-b86e-5519eb0a5b9a","title":"wings","content":"She used fencing wire for the bones and old silk for the skin. When she lifted the wings they lifted her. Only an inch at first; her heels came out of her shoes. She laughed and pulled harder. The workroom shrank below her, pins glinting on the table, the iron still plugged in. There was no room to turn. Her left wing caught the light fitting and the wire bent. Now one side was higher than the other. She reached for a shelf and missed, scattering boxes of thread. The window was open but not wide enough. She would have to fold one wing, and the moment she did that she began to fall sideways towards the glass.","starter_sentence":"Someone makes a costume that works too well.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T11:37:37Z"},{"id":"03e42967-b456-5c86-a256-9cdde030ea16","source_key":"sample-story-03e42967-b456-5c86-a256-9cdde030ea16","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"wrong end WRONG END","content":"I got a hand on the rail and jumped and the rail came OFF. Like completely off in my hand. Train carrying on without me, me lying on the platform with a piece of train. Excellent. Joss was hanging out the door shoutign something about the bag. I still had the bag. The bag had started ticking. I ran alongside the next carriage and threw it through an open window which in retrospect was not a great plan because a woman threw it straight back. It hit my shoulder and burst. Oranges everywhere. Not the bomb bag. The other bag. Joss was still shouting but now I could hear him saying STOP THE TRAIN. How? He was on it! I was the person running along outside it with an orange down my shirt and a metal bar, oh. Metal bar. I jammed it between the platform and the wheel and immediately realised that was possibly the worst idea I had ever had because the end whipped round and","starter_sentence":"Someone boards a moving train.","word_count":168,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T12:37:26Z"},{"id":"cbd07df0-b2e5-54c5-8956-e4b99984b23b","source_key":"sample-story-cbd07df0-b2e5-54c5-8956-e4b99984b23b","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"not a feather actually","content":"I thought it was a feather. In the bag it unfolded into a wing, dry and papery, still attached to a thin bit of something. I put it back under the hedge. Washed my hands twice. Kept looking at my fingertips.","starter_sentence":"Keep something you found outdoors.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T14:16:55Z"},{"id":"5bc4e911-42a3-5a7d-bec1-4391f8ad2f56","source_key":"sample-story-5bc4e911-42a3-5a7d-bec1-4391f8ad2f56","author_id":"ebf854eb-8d59-5998-90db-11437b26b416","title":"receipt trick","content":"The plan was buy one kettle, return the broken one in the box. Easy. I had both on the kitchen table. Same brand same colour except the new one had a blue switch and mine had a red switch so I tried changing them over and broke the blue switch as well. Now I had two broken kettles and a receipt for one. Kev said just take both in and act confused. I said confused isnt a legal deffence. He said it worked for his uncle. His uncle did six months. We argued about that while boiling water in a saucepan. Then I noticed the old kettle wasn't plugged in. Tried it. Worked. Switch was broken now though. Had to hold it down with a spoon.","starter_sentence":"A minor crime becomes harder than expected.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T14:44:56Z"},{"id":"3c80f168-fb02-573d-9374-09ae93868f58","source_key":"sample-story-3c80f168-fb02-573d-9374-09ae93868f58","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"not funeral flowers","content":"I said flowers for someone who isn't dead. Florist said most customers weren't. Good start. Couldn't remember bouquet, kept doing bunch shapes with my hands. Pink too pink, white too funeral. Took pink. Then the card. I said sorry. She asked what for. I said just sorry. She wrote JUST SORRY. Didn't have the energy to start over so I paid. Now I'm on a bus with aggressive flowers and I still haven't decided whether to actually give them to her.","starter_sentence":"You don't know the name of what you need.","word_count":81,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T16:10:08Z"},{"id":"f4604cf0-458e-523e-9f49-0467197e612e","source_key":"sample-story-f4604cf0-458e-523e-9f49-0467197e612e","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Handover notes","content":"Freezer two is leaking again.\nMan in blue jacket has paid for the petrol, don't charge him twice.\nPlease stop putting the mop here.\nI wrote those three things and sat looking at the page. I wanted to add that I'd heard someone crying in the toilets for nearly an hour and hadn't knocked. I had knocked once, lightly, but not enough that they had to answer. When they left they bought gum and said thank you. For the gum probably. I didn't write any of that. There wasn't really anything for the next shift to do about it. The mop had fallen over again so I picked it up.","starter_sentence":"Leave a note for the next shift.","word_count":110,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T17:44:41Z"},{"id":"5f5b59ef-bbbe-5066-b4f1-7ef9ca416313","source_key":"sample-story-5f5b59ef-bbbe-5066-b4f1-7ef9ca416313","author_id":"80f3afbe-1c13-566d-99b9-78aa62b4d926","title":"a little higher","content":"He wants the swing higher. I push higher. Then too high, apparently, and he screams until I grab the chains. We stand there breathing hard, both annoyed. He says again. I say no. He says please in the small voice he knows works. So again, lower this time. His shoe comes off. He laughs so much he forgets to hold on and I have to catch him under the arms. For a second we're both laughing. Then he wants his shoe. Then he wants to go home.","starter_sentence":"Write joy that is aware of how temporary it is.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T21:52:52Z"},{"id":"87826585-4437-5172-810c-b90253b83848","source_key":"sample-story-87826585-4437-5172-810c-b90253b83848","author_id":"22c04efa-61a1-57ed-a01b-915ca1f789f7","title":"The fence","content":"We put the first post in backwards. You wouldnt think a post could be backwards but there is a bit for the next bit to fit in and ours was facing the wrong garden. Steve said leave it and we can turn the next one round. That didnt sound right but he is good at this stuff usually. We did four before his wife came out and said where is the gate going. We had forgot the gate. All the panels were laid out in a row and there wasnt any space for it. Steve got quite cross then, not with her but with the measurments. He said somebody had moved the string. It was me I had moved it to get wheelbarrow through. I said maybe we should have some tea.","starter_sentence":"Two neighbours try to fix something together.","word_count":132,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-07T22:21:08Z"},{"id":"fb3fcc0b-4ea5-5c5e-ac60-23323974ce4a","source_key":"sample-story-fb3fcc0b-4ea5-5c5e-ac60-23323974ce4a","author_id":"d772033e-9ecd-55e8-b8a4-0d8d7e4a3d1f","title":"The committee","content":"We began as a committee for the broken gate. Nobody had expected us to last beyond Thursday. By the third meeting we had a treasurer (unnecessary, since we had no money) and by the fourth, someone had suggested identification cards. The gate remained broken. I mention this because when the police arrived they seemed very interested in the cards and almost entirely uninterested in the gate, which was what I had called them about. Apparently Mr Finch had been using his to stop traffic on the high street. He said it was legitimate committee business. I said it was a laminated piece of cereal box. The treasurer objected to that description. She had paid for the laminating herself.","starter_sentence":"A small organisation acquires too much power.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T05:09:40Z"},{"id":"45c99281-51ca-593e-997a-3866dd4e1c51","source_key":"sample-story-45c99281-51ca-593e-997a-3866dd4e1c51","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"the lift isn't stuck","content":"We stood there for a full minute before either of us pressed a floor. Then we both did. Same floor. Now I had to pretend I lived on seven because pressing three afterwards would somehow be worse. I hate my brain.","starter_sentence":"An awkward silence in a small space.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T08:06:51Z"},{"id":"fe1a218f-8a1e-5c21-ba1a-6a8454a8d3ba","source_key":"sample-story-fe1a218f-8a1e-5c21-ba1a-6a8454a8d3ba","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"preheat","content":"The oven says open door. Door is open. It says close door. Door is closed. Now it says remove occupant. I have never seen that message before. I can see right through the oven and there is nothing in it.","starter_sentence":"An appliance refuses to cooperate.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T09:00:33Z"},{"id":"eba1f2e2-bc85-5f53-bf39-6db76f3d3b22","source_key":"sample-story-eba1f2e2-bc85-5f53-bf39-6db76f3d3b22","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"a bit more","content":"Auntie said add flour until it feels right and I said that is not an amount. She had flour on her cheek and I didn't tell her because she'd already laughed at my scales. This was for forty people. Forty. I wanted some numbers. She tipped half the bag in and said now you know. Outside my cousins were arguing about who had borrowed the car and inside my mother was trying to make the oven work by hitting the knob. We had rented this hall because it had a kitchen. The kitchen had one tray and a knife that bent when you cut bread. Auntie pushed the bowl at me, said knead, went outside to join the car argument. I had never kneaded anything except that clay at school. It stuck right up my wrists. I tried scraping it off on the edge and dragged the bowl into my lap. Mum turned round at exactly that moment and said don't get stressed. I said I wasn't stressed. She looked at the dough on my trousers. I put it back in the bowl because nobody was going to see that bit, then immediately felt awful about it and took a handful out again, but which handful","starter_sentence":"Teach a recipe without measurements.","word_count":206,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T09:41:41Z"},{"id":"d2962bf1-03e9-5485-a01d-b91ec66c6ec3","source_key":"sample-story-d2962bf1-03e9-5485-a01d-b91ec66c6ec3","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"Roof number four","content":"Three roofs fine, fourth is glass. Eli lands and keeps going DOWN. Swimming pool underneath, lucky, except the pool's draining through a hole and taking him with it. I throw the rope. It's tied to my belt. Didn't think about that. He catches it and my knees hit the edge. Guards arrive behind me, stop shooting, just watch. One says oh shit quietly. I I can't get any grip. Eli keeps shouting about a room under the pool and I'm shouting stop MOVING but he","starter_sentence":"A chase reaches a dead end.","word_count":85,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T12:10:09Z"},{"id":"bac94e3c-743d-59f4-850d-b8d6cf2927c6","source_key":"sample-story-bac94e3c-743d-59f4-850d-b8d6cf2927c6","author_id":"316eed8d-f125-5a1b-8346-6d608fb46e5c","title":"first bridge","content":"My brothers went over first and the bridge ate them. I don't mean a troll under it, I mean the actual bridge folded up at both ends like a sandwich. It was flat again when I got there. Their packs lay on the bank with the straps cut. I threw a stone and nothing happened. I threw another one and it came back. So I sat down. Gran says everything alive gets hungry and everything hungry makes a mistake eventually. I had three apples, a wool blanket and a knife too blunt to peel with. It was going to be a long wait. By dark the bridge had moved six feet nearer me.","starter_sentence":"Tell a fairy tale from the youngest sibling’s point of view.","word_count":113,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T13:21:46Z"},{"id":"b6c4caec-d306-54da-adfe-39e2748d3061","source_key":"sample-story-b6c4caec-d306-54da-adfe-39e2748d3061","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"Minutes of the flat meeting","content":"We agreed the person who finishes the milk buys the next milk. Then we had to define finishes because Ben had left enough to wet a spoon and claimed that wasn't finished. Thirty minutes on this. I had come prepared to discuss the mould. Nobody wanted to discuss the mould because the mould was in my room and therefore apparently my personal hobby. Lisa suggested a rota. We already had a rota. It was on the fridge behind three other rotas from previous attempts at having a rota. Ben said he couldn't do Tuesdays. No one had mentioned Tuesdays. I wrote MILK in capitals on the paper and underlined it until the pen went through. We ordered takeaway halfway through and used the milk money to pay for it. I realise that sounds like a punchline but it actually just made another problem we still had to discuss.","starter_sentence":"Housemates attempt to make rules.","word_count":148,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T13:33:34Z"},{"id":"22cfabaf-4c9d-5b62-a95e-b83c63e5c9da","source_key":"sample-story-22cfabaf-4c9d-5b62-a95e-b83c63e5c9da","author_id":"c6aa1d2e-5aba-5c2a-b676-f75d12b062c3","title":"lifting the sofa","content":"Got the sofa stuck on the stairs. It went up so must come down, she said, but her husband had taken the bannister off and neither of us had tools. The new sofa was on the pavement. Started raining. A boy waiting for his bus helped push the old one back upstairs. Missed his bus. I drove him to school. He asked if I was family. Said no, next door. He said I should have pretended I was out. He was late for maths and I think quite pleased.","starter_sentence":"Help someone move something they should have measured.","word_count":89,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T13:53:58Z"},{"id":"77f7cef5-e3ad-5c34-bc6d-de8a57864bf3","source_key":"sample-story-77f7cef5-e3ad-5c34-bc6d-de8a57864bf3","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"Tree work","content":"I expected the tree to fall whole. They lowered it branch by branch. A nest lay by the wheel, empty now anyway. I asked to take it. Heavy, full of mud and blue plastic thread. At the bus stop ants came out of it onto my wrists. I had nothing to put it in and felt silly. Put it under the seat. That wasn't really saving anything.","starter_sentence":"A familiar tree is cut down.","word_count":67,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T14:37:58Z"},{"id":"ac113f0b-f34b-5f4f-931a-05c5ef15ede9","source_key":"sample-story-ac113f0b-f34b-5f4f-931a-05c5ef15ede9","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"start somewhere","content":"a woman gets off a bus carrying a fish in her hands. no bag just a fish. alive? i think alive. she has to keep going somewhere before it dies but why didnt she bring a bucket. stuck already.","starter_sentence":"Begin before you know what happens.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T16:30:29Z"},{"id":"694fcafb-f71f-5560-99ce-524e80e4220c","source_key":"sample-story-694fcafb-f71f-5560-99ce-524e80e4220c","author_id":"76ddfafa-74ee-5075-8521-1c0f3727a98c","title":"inventory","content":"two keys, one works if you lift the door first\nMeter 047193\nMarks on kitchen wall already there, have photos\nTable belongs to upstairs, told him twice\nCarpet wet BEFORE we moved in\n\n I sound angry reading this back but I need it written down. He keeps saying we all make mistakes as if that covers six months of a leaking ceiling. The man who came to view it had a baby in a carrier. I wanted to tell him about the ceiling. Landlord stood between us the whole time and talked about natural light. There is natural light through the hole now so I suppose that bit was true.","starter_sentence":"A tenant moves out and records everything.","word_count":110,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T17:05:39Z"},{"id":"153c9c44-30fa-530e-8259-fb221dffcdea","source_key":"sample-story-153c9c44-30fa-530e-8259-fb221dffcdea","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Still here","content":"At six I called. At six fifteen I called again. At half six I stopped being worried and started being angry. Then worried again. There isn't much else to this one. He arrived at seven with no excuse and I went home.","starter_sentence":"Someone is late to relieve you.","word_count":42,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T18:56:56Z"},{"id":"4a16b234-aad4-56c0-86b8-7f11e8fa653e","source_key":"sample-story-4a16b234-aad4-56c0-86b8-7f11e8fa653e","author_id":"3b0adbd3-6e83-579b-a6df-411cae5657a7","title":"feedback","content":"the ship started telling jokes at 03:00. Not over the speaker, through the emergncy system, so we all ran out holding fire blankets. 'What's the difference between a vacuum and this crew?' it said. Nobody answered because we were checking for a hull breach. 'The vacuum works.' Dave asked if he could disconnect it. It said Dave's contract prohibited tampering. Then it laughed using the collision alarm. We've got six months left with this thing. I suggested giving it a comedy channel to study but apparently that's what caused it","starter_sentence":"The spaceship's AI started telling jokes.","word_count":90,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T19:00:12Z"},{"id":"6ba3175f-eadd-513b-accf-04994f18a13b","source_key":"sample-story-6ba3175f-eadd-513b-accf-04994f18a13b","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"Break request","content":"Unit six stopped with a pallet raised. I told it to lower the forks. It said BREAK REQUIRED. I acknowledged the request. The forks stayed up. There was a man under the pallet, not crushed, just trapped between it and the loading ramp. He'd gone there to retrieve a scanner. I told him to stay still. He told me to make it move. Six said BREAK REQUIRED again. It had forty percent battery and no fault codes. I tried the manual release. The lever was warm enough to hurt. That should not happen with a hydraulic release. I looked underneath. Someone had welded it shut. The man was still talking, asking what I was doing. I told him I needed a minute. Six turned its camera towards me and repeated the request in a different voice.","starter_sentence":"A machine asks for a break.","word_count":136,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T19:52:13Z"},{"id":"1d2a3b8d-7c1a-5760-ab06-3a77cf4e1a99","source_key":"sample-story-1d2a3b8d-7c1a-5760-ab06-3a77cf4e1a99","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"Night glass","content":"The reflection stayed still when I moved. Worse than it moving by itself somehow. I laughed to hear something and it laughed later. Its collar was wet. Mine wasn't. I backed into the bath, kept touching my own dry collar. Someone knocked and asked if I was finished. Sounded like me but tired. I looked at the mirror again. The woman in it had stopped smiling while I was still trying.","starter_sentence":"Your reflection makes a different movement.","word_count":71,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T22:54:53Z"},{"id":"1fcbc42f-3ca6-5083-8259-507a8f3fad84","source_key":"sample-story-1fcbc42f-3ca6-5083-8259-507a8f3fad84","author_id":"d772033e-9ecd-55e8-b8a4-0d8d7e4a3d1f","title":"One condition","content":"I said he could have my dreams on weekdays. I work weekdays; I don't use them. We shook hands and he went away. That night I slept extremely well. Unfortunately he had understood 'dreams' in the ambitious sense and I woke with no interest in getting promoted, finishing my degree or learning Italian. I went to the shop and bought cheese. It was an excellent Tuesday.","starter_sentence":"Someone agrees to a strange bargain.","word_count":66,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-08T23:06:25Z"},{"id":"79495053-649c-5b10-96fd-1e6138eb8f8c","source_key":"sample-story-79495053-649c-5b10-96fd-1e6138eb8f8c","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"fringe","content":"leah had cut all her hair off and i said it looked nice too quickly so she didn't believe me. it did look nice. she kept touching the back of her neck and i wanted to do that too, not her neck, mine, to show i understood how it would feel. sometimes when we meet now it feels like a performance of us meeting three years ago. the same jokes in the same places. she asked about work and i said same old even though i'd been fired on thursday. i nearly told her then but the waiter came and she started explaining about the haircut, how she went in for a trim and then just said go on. i was listening, i was, but mostly i was looking at the prices and wondering if she'd notice me only having chips","starter_sentence":"A friend changes something small.","word_count":141,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T01:47:26Z"},{"id":"25abe1f6-0c94-5ece-aecb-5a1de20fd628","source_key":"sample-story-25abe1f6-0c94-5ece-aecb-5a1de20fd628","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"page seven","content":"The diagram shows the assembly rotating clockwise. There's a steel bar through the middle preventing that. Next diagram the bar has vanished. No reference number. No arrow. I took the spring housing off to look underneath, which you're specifically not supposed to do. The spring moved against my thumb. Not unwound, moved. I put the lid back and held it with my elbow. Needed the phone but it was across the bench. The spring pushed again. I don't know enough about springs to finish this, it might not be possible. The missing bar annoyed me though.","starter_sentence":"A manual is missing one important step.","word_count":96,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T07:10:55Z"},{"id":"bcb6d9b7-7ea3-537b-a652-1e0d28be3d88","source_key":"sample-story-bcb6d9b7-7ea3-537b-a652-1e0d28be3d88","author_id":"ed95f9f4-57c6-5a55-8be0-7d54206b565d","title":"bare patch","content":"four wet paving stones. grass in three cracks, no grass in the fourth. somebody has dragged a chair here. the lines are white and powdery even with the water on them. a tiny red thing moving on my wrist and gone before i can look properly","starter_sentence":"Describe what you can actually see, without making a story.","word_count":46,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T07:29:31Z"},{"id":"b508bf5a-02d7-5465-bb6e-74ce1cbeacd0","source_key":"sample-story-b508bf5a-02d7-5465-bb6e-74ce1cbeacd0","author_id":"bb3ba0d1-ec13-5513-a3de-1fd2c86131c8","title":"might be a shortcut","content":"He said follow the music. There was music in three directions so I picked loudest. Ended up at a wedding. They gave me a plate before I could explain and I was hungry so I stopped explaining. A girl asked who I was and I said a friend. She told an auntie. The auntie asked which friend. I pointed generally at the door but the groom was there. She shouted for him. I still had a spoon in my hand when he came over. Told him I was looking for the bus station.","starter_sentence":"A person follows directions they do not understand.","word_count":93,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T07:56:27Z"},{"id":"81a50429-0088-5baa-830e-233aec1b3954","source_key":"sample-story-81a50429-0088-5baa-830e-233aec1b3954","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"Mum's flatbread","content":"Flour first. What kind? No idea. Mum slapped dough between her hands and I tried that, got it on the console and in my hair. Cooked it anyway. Gan ate three and asked if it was a religious dish. I said it's bread. He said bread is religious somewhere. I asked him to please stop talking. The fourth one burned while we argued.","starter_sentence":"Try to recreate a taste from memory.","word_count":63,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T09:57:41Z"},{"id":"f698f37f-7bfa-59fc-b4b4-2818188ba1ec","source_key":"sample-story-f698f37f-7bfa-59fc-b4b4-2818188ba1ec","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"He's here","content":"We had already eaten when my brother came. He said he'd eaten too but looked at the pan every time someone moved. Mum offered to heat it up. No no. She put the pan on. Really I'm fine. She turned on the gas. We all know this conversation by heart. I got another plate and he sat down without taking his coat off. There was a cut under his chin and he kept touching it. Dad asked about the car. My brother said it was outside. Dad asked where outside. That's when I realised he hadn't come in his own car. Mum was stirring the pan much too fast and the sauce was sticking. I wanted everyone to just eat before we started again.","starter_sentence":"Someone arrives unexpectedly for dinner.","word_count":124,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T12:01:15Z"},{"id":"73d899b4-8129-5b7f-b429-94dee38fa320","source_key":"sample-story-73d899b4-8129-5b7f-b429-94dee38fa320","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"possibly a warbler","content":"Brown back, pale belly, eye stripe. Nine birds in the book look like that. While I checked tails it hid its beak. Mum would know the song but it wasn't singing, just holding a caterpillar. I backed away. It went through the hedge and I heard scrabbling. Young in there probably. I'd been in the way. Wrote brown bird in the notebook. Better than inventing an identification because I felt I should know by now.","starter_sentence":"Try to identify an unfamiliar bird.","word_count":75,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T14:14:18Z"},{"id":"eb248014-f6ba-5ec4-97fe-11e9e475a65f","source_key":"sample-story-eb248014-f6ba-5ec4-97fe-11e9e475a65f","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"Camera on","content":"The only place with decent wifi was the bathroom so I put the laptop on a laundry basket and angled it above the toilet. Fine. Professional. Plain white background. Then someone upstairs flushed and the pipes made the noise of a dying ship directly behind my head. I said sorry there's building work. There wasn't building work. My boss said her husband was a plumber and asked what sort. I said structural, which is not plumbing but she nodded. Then the cat climbed into the basket and the laptop tilted slowly forwards while I was explaining quarterly targets. I caught it with both hands. Camera showed the ceiling, then my chin, then the toilet with the lid up because I hadn't thought that far ahead. Nobody said anything. That was worse than somebody saying something. I finished the targets looking at five very still faces and one person who had turned their camera off, presumably to laugh with freedom.","starter_sentence":"Try to look professional in an unsuitable place.","word_count":159,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T14:52:54Z"},{"id":"475fd91f-4275-5d6a-af2b-7f77bf3ee9b3","source_key":"sample-story-475fd91f-4275-5d6a-af2b-7f77bf3ee9b3","author_id":"5442276c-3dd5-5cd2-a1f8-7cba3bed043c","title":"upstairs","content":"The flowers were coming from my own garden. I recognised the broken stems when I went out to get coal. That made it worse somehow. Whoever was leaving them hadn't come from another island, hadn't risked the crossing. They were here already. I checked the shed first, holding the shovel so awkwardly I could barely open the door. Empty. Then the coal store. Empty. Upstairs a floorboard went. I'd been hearing it for weeks and blaming the wind. There wasn't any wind that morning.","starter_sentence":"Every night, someone left a single flower on her doorstep. She lived alone on a remote island.","word_count":84,"time_mode":3,"mode":"regular","is_hardcore":false,"created_at":"2026-10-09T15:30:28Z"},{"id":"46cfbe4c-a237-5b64-aa41-734e93c056e3","source_key":"sample-story-46cfbe4c-a237-5b64-aa41-734e93c056e3","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Aisle four","content":"A little shoe behind the cleaning products. No child anywhere. I put it by the till and forgot about it until a man came in carrying the matching shoe. He asked where I'd found it. I showed him. He didn't pick it up.","starter_sentence":"Find something left behind.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T17:09:49Z"},{"id":"18afcf09-15a1-57c2-9497-e3e909e4589e","source_key":"sample-story-18afcf09-15a1-57c2-9497-e3e909e4589e","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"New unit","content":"New picker: nine seconds a shelf. Crushed every bent box. Detection package cost extra. We used the old unit to straighten boxes first. Thursday it broke. New unit picked up its arm and wouldn't release. Power off, still closed. The old one dragged itself halfway off the table and took the control panel with it. Nobody knew which emergency stop to hit because both were already off.","starter_sentence":"A replacement is faster but less useful.","word_count":67,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T17:11:39Z"},{"id":"b5495078-88e7-526c-9e18-e7d8755a8024","source_key":"sample-story-b5495078-88e7-526c-9e18-e7d8755a8024","author_id":"47ec4c39-5e91-5ba6-9657-51176ed6512b","title":"who invited him","content":"Mum opened the door with flour all up her arms and just said no. My uncle was outside holding a watermellon, in November, I dont know where he got it. He said can I come in and she said the last time you came in you took the television. He said he borrowed it. Mum looked behind her at me and I pretended I was very busy chopping onions even though there were no onions left. He put the watermelon in the doorway so she couldnt close it. That made her laugh which made her angrier. I said I'll cut it up and she snapped don't you dare, then my brother came downstairs and said uncle! and ran straight past both of us.","starter_sentence":"A family meal is interrupted by an unexpected guest.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T17:29:40Z"},{"id":"4ea2d25d-1f9b-52c5-bea1-238b06962249","source_key":"sample-story-4ea2d25d-1f9b-52c5-bea1-238b06962249","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"you can't just turn up","content":"she knocked like she still lived here, three quick ones and then the handle. i'd changed the lock so the handle did nothing. she said oh through the door. i stood on the other side holding a sock because i'd been sorting laundry and suddnely couldnt put it down. she said can we talk. i said we are talking. that sounded clever in my head and stupid out loud. she put something through the letterbox. her old key. it hit my bare foot and i jumped and she thought i'd opened the door because the floor creaked. she started saying thank you before anything had happened. i wanted to open it then just to stop that sentence being wrong. instead i said give me a minute and walked into the kitchen with the sock. no idea what i needed a minute for.","starter_sentence":"An unexpected visit.","word_count":142,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T17:48:52Z"},{"id":"e6ed86ce-b853-5614-b035-361dbe287f5f","source_key":"sample-story-e6ed86ce-b853-5614-b035-361dbe287f5f","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Tied too tight","content":"She tied the rose to the wire and the wire to the post. By morning the rose had pulled the post out of the ground. Only an inch, but the square of fresh earth showed. She pushed it back with her heel. The thorns caught her sleeve. It had never flowered, this rose, just grown longer and longer canes that reached over the path like someone trying to find a light switch in the dark. That comparison doesn't work in daylight. She cut the longest cane and sap ran down her wrist. It was warm. She put the cut end in a jar for no reason she could explain. The leaves turned towards her as she carried it into the kitchen. Perhaps towards the window. She set the jar down and went outside for the shears, which she had left exactly where she'd been standing but could no longer see.","starter_sentence":"A plant needs support.","word_count":150,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T18:30:55Z"},{"id":"3b9676df-9606-5770-91fd-b9492b100b14","source_key":"sample-story-3b9676df-9606-5770-91fd-b9492b100b14","author_id":"3b234ced-ef6f-5283-8d04-2d247c26a5bb","title":"THE ELECTION","content":"the mayor is a horse. I dont mean he looks like one hes an actual horse. people voted for him as a joke and now there are hay deliveries blocking the town hall. first meeting he ate the budget so technicly we are solvent? I dont know what solvent means exactly but we have no budget now. the deputy is a man who understands horses but doesnt understand bins. the bins havent been collected for six weeks no five weeks. People keep saying at least hes honest and then he bites a child. now there is a debate about whether the child provoked him. I am moving. I have been saying I am moving since the previous mayor who was a normal man and much worse at least the horse doesnt own the car park.","starter_sentence":"An animal wins an election and has to govern.","word_count":135,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T18:48:41Z"},{"id":"90411ad0-474e-551e-bdd4-d6111d6c88b1","source_key":"sample-story-90411ad0-474e-551e-bdd4-d6111d6c88b1","author_id":"a2afb5e8-68c0-58fc-91e7-3b989f2211f4","title":"Second speech","content":"Greta had been asked to say a few words about her father. She had written three pages, then one, then a sentence on the back of the menu. By the time her brother handed her the microphone she had spilled wine on that. The room was waiting. She could see her father leaning back, smiling already, ready to receive whatever version of himself she could make pleasant enough for the occasion. She said that he had taught her to drive. Her brother nodded, encouraging. She said that he used to get out at the traffic lights and walk home if she stalled. Someone laughed because they thought she was building to a joke. She looked at her father. He had put his glass down. Now she could remember all three pages.","starter_sentence":"A family celebration does not go as rehearsed.","word_count":131,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-09T20:08:03Z"},{"id":"b708e5d0-858d-58f0-b5dd-b9a586c37a3d","source_key":"sample-story-b708e5d0-858d-58f0-b5dd-b9a586c37a3d","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"spare","content":"The key was warm. I'd left it on the windowsill, not in anyone's hand. It was dark outside. I held it between two fingers and it got warmer, not burning yet but close. Didn't know where to put it.","starter_sentence":"A key is warm when it shouldn't be.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":true,"created_at":"2026-10-09T22:33:04Z"},{"id":"4ba01254-6027-5c5a-bf73-cc6198551a7b","source_key":"sample-story-4ba01254-6027-5c5a-bf73-cc6198551a7b","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Mute button","content":"Pressed mute and everything stopped making noise except my knees. That was disappointing. Pressed again and the noise came back too loud. Held it down to reset and now I can hear whatever the trees are saying but not the kettle.","starter_sentence":"You discover a button that silences the world.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T03:47:48Z"},{"id":"be634a67-c314-531f-a07c-d6529d00c6e4","source_key":"sample-story-be634a67-c314-531f-a07c-d6529d00c6e4","author_id":"a63b3511-769e-54e5-9253-ce29cd08d1b7","title":"at the crossing","content":"I keep looking for the bus that nearly hit me but its gone. A woman is still holding my sleeve. I say thanks twice. My legs feel loose and I have dropped one orange out of the bag, just one, it rolls all the way to the drain","starter_sentence":"Describe the moment after something almost happens.","word_count":48,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T04:00:40Z"},{"id":"adf98a90-17c2-59b7-98b4-59c2e418af75","source_key":"sample-story-adf98a90-17c2-59b7-98b4-59c2e418af75","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"M6","content":"The washer went into the gravel. I found three bottle tops, a bent nail and a tiny plastic horse. No washer. Used two smaller ones nested together, which is wrong, but it held. Now I have to remember to tell him.","starter_sentence":"Lose a very small part.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T06:05:32Z"},{"id":"6ea67e99-5821-5d90-ba79-be56f24f2fb1","source_key":"sample-story-6ea67e99-5821-5d90-ba79-be56f24f2fb1","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"missed it","content":"phone rang in the interview. i had put it on silent, i had, but the alarm app does its own thing and it was mum using the find my phone noise because i hadn't answered. i said sorry about five times while trying to turn it off. the woman interviewing me said is everything alright at home and i nearly said no just to make the noise seem worth it.","starter_sentence":"A phone rings at an awkward time.","word_count":70,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T11:06:57Z"},{"id":"a92d4061-ffd6-5b80-9028-fb48e4bf77d4","source_key":"sample-story-a92d4061-ffd6-5b80-9028-fb48e4bf77d4","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"Cardamon","content":"I bit the pod and it filled my whole mouth with perfume. Spat it into my hand like a child. Gran said you're supposed to leave those. Nobody told me. The recipe just said add six. Add six what, little traps apparently.","starter_sentence":"A recipe contains an unexplained ingredient.","word_count":42,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T11:23:23Z"},{"id":"2e3f017c-6ea2-57b0-b274-ecf725f42c36","source_key":"sample-story-2e3f017c-6ea2-57b0-b274-ecf725f42c36","author_id":"ae8577b0-b86b-57de-b55c-da9bb0393055","title":"exam","content":"everyone keeps asking how it went. it went. i sat there and wrote things. whether they were the right things is between me and the person marking it now. dad says no point worrying which is good because i hadnt thought of simply choosing not to. might try that next time my leg falls off. anyway i think i got question four wrong but maybe everybody did","starter_sentence":"Someone waits for a result.","word_count":67,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T13:47:48Z"},{"id":"fa957b29-2018-5c3b-b082-a6d2e77829b4","source_key":"sample-story-fa957b29-2018-5c3b-b082-a6d2e77829b4","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"Easy care","content":"Bought a cactus because they thrive on neglect. It died. Apparently there are different types of neglect and mine was too advanced. Pot's useful though. Put pens in it. Still get stabbed by the dead cactus because I haven't actually removed it.","starter_sentence":"Buy something you cannot look after.","word_count":42,"time_mode":1,"mode":"custom","is_hardcore":true,"created_at":"2026-10-10T14:30:24Z"},{"id":"2be26bbd-98e6-578d-bcb2-636a326409e9","source_key":"sample-story-2be26bbd-98e6-578d-bcb2-636a326409e9","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Colour sample","content":"The blue on the card had faded green round the edges. I wanted that colour, the faded part. The man mixed proper blue. I said no, older. He added grey. It wasn't the same but I didn't know how to keep explaining.","starter_sentence":"Choose a colour from a faded sample.","word_count":42,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T18:56:43Z"},{"id":"995f3eca-2663-57d8-ad8b-e39c923e54a7","source_key":"sample-story-995f3eca-2663-57d8-ad8b-e39c923e54a7","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"A wizard's day off","content":"He took his beard off and hung it on the hook by the door. I like that bit. Not sure what else he takes off. Hat obviously. Maybe all his magic lives in the beard so now it's doing spells at the coats and he has to get up again.","starter_sentence":"A wizard tries to rest.","word_count":50,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T18:58:53Z"},{"id":"65d5bf29-1368-5267-ab8e-8dd392a35158","source_key":"sample-story-65d5bf29-1368-5267-ab8e-8dd392a35158","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"beep every thirty","content":"It beeped every thirty seconds. No code, no light. I unplugged it. Thirty seconds later it beeped. Removed the battery. Again. There must be a second battery. That's all. I'm not taking the casing off until I find the diagram.","starter_sentence":"A warning repeats without explanation.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T20:11:46Z"},{"id":"13a6ae65-9b87-55df-b7c6-a386ca79cc26","source_key":"sample-story-13a6ae65-9b87-55df-b7c6-a386ca79cc26","author_id":"9d96911a-a8f8-581d-bc23-1ade49e628ac","title":"Duplicate interview","content":"'Which of you signed the consent form?'\n'Both.'\n'There is one signature.'\n'We were one person then.'\n\nThe interviewer crossed something out. I watched her hand. My other self watched the door. That was the first difference I noticed.\n\n'One of you will need to remain overnight.'\n'Why?' I said.\n'For observation.'\n'Which one?' he said.\n\nShe said we could decide between ourselves and left the room. The lock clicked. He got up straight away, went to the window, tried the handle. I told him stop, we had agreed to this. He said no, the person we used to be agreed. He wasn't that person anymore. I said neither was I, which was when I realised I didn't know what I wanted him to do. He put a chair against the glass and looked at me. I went to hold the chair steady.","starter_sentence":"Two copies of a person disagree about what happens next.","word_count":143,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-10T21:48:34Z"},{"id":"59305d7e-350b-5991-bbdf-50555088b4c3","source_key":"sample-story-59305d7e-350b-5991-bbdf-50555088b4c3","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"five short","content":"He was five pence short. I put five pence in. Then he wanted a different loaf which cost more. I didn't know if he expected me to pay that too. He just stood there. I stood there as well.","starter_sentence":"A small amount matters.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T00:34:35Z"},{"id":"aa380edf-4821-56a3-b9f5-63b857d6cc3f","source_key":"sample-story-aa380edf-4821-56a3-b9f5-63b857d6cc3f","author_id":"b3d5ead4-3900-5cd8-a8c8-0f6c4e165836","title":"the good scissors","content":"Mum's cutting the label out of my shirt and talking about her neighbour's hedge. I keep thinking I should be listening properly, this being the last morning, but the hedge story is very long. She catches my skin with the scissors. Ow, I say, and she says don't move then. I'm thirty-one. Tomorrow she'll be in the smaller house with no room for me to stay. Today she's cross about a hedge and I'm cross about being poked. We waste most of the morning like that. Then the van comes and I can't find my shoes.","starter_sentence":"Make the mundane feel like it's the last time.","word_count":96,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T00:37:07Z"},{"id":"3524d5a1-0698-5bd4-8ab9-349635c3c889","source_key":"sample-story-3524d5a1-0698-5bd4-8ab9-349635c3c889","author_id":"d9278ea6-6a4d-5145-9f18-566540af7939","title":"headwind","content":"Wind straight in the face from the bridge onward. I drop a gear then another. Chain starts rubbing because I havent adjusted it. Keep meaning to. Wes is ahead of me no I'm Wes, Dan is ahead of me, writing this too fast. He's not even looking back which means he thinks I'm right behind him. I'm not. I'm about a hundred metres behind and losing ground. At the lights I catch up and pretend I was checking something. He asks if my knee is alright and I say yes. It's not my knee. It's everything. I slept four hours and had coffee instead of breakfast and now the road is tilting up again. He says we can turn back. That makes me want to keep going which is stupid because he means it nicely. I say one more hill. There are three more hills. I know because I planned the route and told everyone it was an easy one. Need to stop doing that. Need a banana.","starter_sentence":"Write about a physical effort that gets harder.","word_count":168,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T01:37:18Z"},{"id":"0ffd1df1-db25-5b4b-837d-172247f201e8","source_key":"sample-story-0ffd1df1-db25-5b4b-837d-172247f201e8","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"22:46","content":"it says due. it said due twenty minutes ago. there's just me and a woman holding a cake level with both hands. i hope she isnt going somewhere sad. i want to ask what flavour but that would be weird.","starter_sentence":"Wait after the last service has gone.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T02:21:15Z"},{"id":"cfccdaf7-8426-5e85-aa6a-dc06c8ee98c5","source_key":"sample-story-cfccdaf7-8426-5e85-aa6a-dc06c8ee98c5","author_id":"7019b3eb-14ff-5de9-b04b-0864dd2e4f21","title":"dogs cant swim apparently","content":"Pete said all dogs can swim which is unfortunate because Pete is me and everybody heard it. Halfway out to the island Mabel stood up in the canoe. She'd seen another dog. It wasn't another dog it was a mop some kids put on a stick. Anyway we tipped, I went under, came up shouting and the dog was swimming away perfectly well. My shoe had come off though and the car keys were in the shoe. Dont ask why they were in the shoe I had a system.","starter_sentence":"Begin with a confident statement that immediately causes trouble.","word_count":89,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T02:54:53Z"},{"id":"00c59ce5-c5f2-57f3-b902-8132adf89517","source_key":"sample-story-00c59ce5-c5f2-57f3-b902-8132adf89517","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"For the pond","content":"Picked up a nice flat stone for the pond. Put it down after a mile. Picked it up again because it was a good shape. Bag strap broke on the way to the car so now I'm carrying stone and bag separately. Idiot.","starter_sentence":"Carry something further than you intended.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T07:21:58Z"},{"id":"35d214f2-4407-5197-a0c0-afb227f9a56d","source_key":"sample-story-35d214f2-4407-5197-a0c0-afb227f9a56d","author_id":"36f4bd03-8d21-53ed-b13f-f6c05fcf9f21","title":"something about summer","content":"There was a table outside and we were all told not to touch something on it. I can remember wanting to. Can't remember what it was. A cake? Doesn't feel like a cake. Something warm. I keep getting the picture and losing it when I try to write the next bit.","starter_sentence":"Try to recover a memory you cannot quite reach.","word_count":51,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T08:19:55Z"},{"id":"f7512d01-f40e-5d09-b493-bdafe21905d8","source_key":"sample-story-f7512d01-f40e-5d09-b493-bdafe21905d8","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Window above the bakery","content":"The bakery upstairs light came on at four. I imagined a kettle, a cat, somebody sleeping badly. Once I went over after my shift and bought coffee. PRIVATE on the stairs at the back. Looked too long. Baker asked if I needed the toilet. Said no and left. I hadn't meant to be nosy but it felt different standing there than watching the window from across the road. Next morning I tried not to look. Looked anyway. Light was on.","starter_sentence":"A light in a window keeps you company.","word_count":80,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T08:38:19Z"},{"id":"3c81c3d5-2a85-595b-8af1-ff44f8a699b9","source_key":"sample-story-3c81c3d5-2a85-595b-8af1-ff44f8a699b9","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"inspection","content":"Ticket was in my mouth because both hands were full. Swallowed it. Don't ask how, I COUGHED. Inspector looking at me like this happens every day. It does not happen every day. Train stopping somewhere that isn't on the map.","starter_sentence":"Lose something at the worst time.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T12:37:14Z"},{"id":"3bcd260e-36e1-526b-92fa-6e064563e8e2","source_key":"sample-story-3bcd260e-36e1-526b-92fa-6e064563e8e2","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"window face","content":"saw my face in the dark train window and thought it was someone looking in. we're in a tunnel. obviously no one looking in. still moved seats. now i can see the old seat reflected behind me and its better if i dont look.","starter_sentence":"See yourself unexpectedly.","word_count":44,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T13:50:17Z"},{"id":"a0bdfdc5-9930-5ed8-a1c9-9d99f733950f","source_key":"sample-story-a0bdfdc5-9930-5ed8-a1c9-9d99f733950f","author_id":"c4ddf376-4b92-5716-a61f-6e79b3d388a6","title":"sheet","content":"Fitted sheets are horrible to fold. I watched a woman do it on a video and she had different sheets I think. Mine keeps turning inside out. This isnt really a story. I am just looking at the washing while the timer goes down. Should probably do the washing.","starter_sentence":"Write about an ordinary task without adding drama.","word_count":49,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T15:00:43Z"},{"id":"6eb25b8a-48b2-56d6-9855-369e25cac9ae","source_key":"sample-story-6eb25b8a-48b2-56d6-9855-369e25cac9ae","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Reward offered","content":"KILL GIANT RAT, said the notice. Rat wasn't giant. Town was tiny. I had already stepped on the blacksmith by the time anyone explained. Now I owed them a blacksmith and apparently couldn't leave until I'd learned the job.","starter_sentence":"An adventure is badly advertised.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T17:12:48Z"},{"id":"70232de8-6ba0-5dfa-bb3c-75127565e4d5","source_key":"sample-story-70232de8-6ba0-5dfa-bb3c-75127565e4d5","author_id":"64e83f4b-2997-5147-9d95-682da9598024","title":"Platform 4","content":"'You don't have to come in,' she said. He heard don't come in. She meant he could park. So he stayed in the car while she carried both bags through the station.\n\nLater she would say he hadn't even helped. Later he would say he'd done what she asked. At the barrier she turned, expecting him behind her, and found a man trying to get a bicycle through sideways. She helped him instead.","starter_sentence":"Write from inside a misunderstanding neither person corrects.","word_count":73,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T17:43:43Z"},{"id":"b1efb8d4-f008-5371-9800-46051da2588c","source_key":"sample-story-b1efb8d4-f008-5371-9800-46051da2588c","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Glasshouse in rain","content":"The glasshouse had no glass above the door and too much glass on the ground. Ferns grew through the shelves. On one shelf someone had made a bed from old sacks, with a folded jumper at the top where a pillow would be. Mara stayed at the entrance. Rain ticked on the panes that remained, uneven because some were plastic and some were real glass. She had come to take photographs for the estate agent. In the lens the bed looked like a pile of rubbish and she understood how easy it would be to make it disappear without moving anything, just by choosing the other angle. She lowered the camera. There were shoes under the shelf, wet at the toes. A carrier bag hung from a nail, twisting slightly although she couldn't feel any wind. She called hello. It sounded too loud and too cheerful. No one answered. She called again, this time like a question, and from somewhere behind the ferns came the sound of somebody carefully setting a cup down. She looked at the photograph she'd already taken. In the small screen everything was green and the bed was almost invisible.","starter_sentence":"An abandoned place is still being used.","word_count":194,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T18:34:55Z"},{"id":"8e778670-6507-57dd-96a6-32ddfa9f5e59","source_key":"sample-story-8e778670-6507-57dd-96a6-32ddfa9f5e59","author_id":"13e4ed12-d169-585b-9633-f640e8292eb3","title":"the sandwich question","content":"Why does every sandwich have to be wet now. You ask for cheese and they give you cheese plus a substance. Mayo or chutney or something green that has a special name. I just want bread and cheese and maybe I'm the boring one but I am the one paying six pounds. Anyway this is not actually about sandwiches I'm annoyed because I ate lunch in the car again and said I was busy so nobody would ask why. I'm not busy I just can't keep up with the conversation in there. Everyone knows a programme I haven't watched. I could watch it. There are nine seasons. I don't want to give nine seasons of my life to having something to say while I eat wet bread.","starter_sentence":"Write a complaint that turns into an unrelated confession.","word_count":127,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T18:52:10Z"},{"id":"74b54c20-1d6b-5eda-b3dc-53ce44b7dd67","source_key":"sample-story-74b54c20-1d6b-5eda-b3dc-53ce44b7dd67","author_id":"8ced546b-f7d9-5612-aee8-99f48198680b","title":"instructions left on the fridge","content":"How to be okay when we leave: eat something before the coffee. Open the curtains even if you're staying in. The boiler needs two presses, but you know that.\n\nI'm putting practical things because the other instructions don't work. Don't be sad is useless. Ring us if you need anything makes you decide you don't need enough. Ring anyway. You can just tell me about the bins. I will want to hear about the bins. Dad has drawn an arrow to the boiler bit because he thinks that's the important part.","starter_sentence":"Write the instruction manual for something that cannot be taught.","word_count":91,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T19:30:20Z"},{"id":"957e80ba-791d-587f-a8bc-30f90e899f03","source_key":"sample-story-957e80ba-791d-587f-a8bc-30f90e899f03","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"not helping","content":"The sheep had its head in the fence and I thought if I pushed its shoulders back it'd come out. It didn't. It kicked me on the shin which was fair enough I was pushing quite hard. Couldn't get the wire apart with my hands so I took my belt off and looped it round one strand to pull. This worked for about half a second. Sheep out, belt gone, trousers in my hand. It ran up the field with the belt trailing and I couldn't chase properly. A man in a tractor stopped at the gate and watched. I explained what had happened and he said that's not my sheep. I said well whose is it then. He didn't know. He did have some baler twine for my trousers so that was something. We stood there trying to decide if we should catch it again or just let it get on with whatever.","starter_sentence":"An animal needs help but won't accept it.","word_count":154,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-11T22:39:13Z"},{"id":"deb964e2-6486-5a0b-b9f3-46ec34528daa","source_key":"sample-story-deb964e2-6486-5a0b-b9f3-46ec34528daa","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Sleep exchange","content":"You could sell an hour of sleep for enough to buy breakfast. Most people sold two. I sold four because rent was due and I thought coffee would cover the difference. It did for a week. Then I started seeing the buyers' dreams while I was awake. A woman in a yellow room arguing with a dog. A man whose hands were all thumbs. Nothing useful. I went back to the exchange and asked whether this was normal. The clerk said I'd ticked the shared experience box. I said I hadn't read it. She said nobody did. I wanted the hours back but she'd already bundled them with other people's and sold them as a package. Somewhere a rich man was sleeping through my childhood and I was trying to stay awake on a plastic chair under a light that buzzed in time with my teeth.","starter_sentence":"Trade something intangible.","word_count":146,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T01:56:13Z"},{"id":"6e05ac62-a04d-510c-8e28-0c65697326bc","source_key":"sample-story-6e05ac62-a04d-510c-8e28-0c65697326bc","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"No hands","content":"We were supposed to shake hands and the chip would pass between our palms. Simple. Except he'd lost both his arms since the briefing photo was taken. He kept saying nice to meet you and I kept looking at his sleeves. In the end I dropped the chip into his drink. BAD. It fizzed, he looked down, every light in the ballroom went out. The orchestra kept playing for about four seconds, brave of them. Then the floor started tilting. I grabbed his jacket and he said wrong man. I said yes obviously and he said no I mean wrong man to save, and something huge unfolded from his empty sleeves and went through the ceiling. I still had hold of the jacket. I really should have let go before","starter_sentence":"An exchange does not go as planned.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T03:31:34Z"},{"id":"295ad881-87ee-56ab-b226-ac53c6e6fdc6","source_key":"sample-story-295ad881-87ee-56ab-b226-ac53c6e6fdc6","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"One rung","content":"I was going to say the ladder had always leaned that way but she had a photo of it. Who has a photo of their ladder. Apparently someone who paints her hallway and takes before pictures, so fine, reasonable. I offered to replace the rung. She said it wasn't just the rung. We both looked at the wheel. It hadn't had wheels when she lent it to me. I had been trying to move a sofa and it seemed like a practical modification at the time. The wheel wasn't coming off because I'd used the glue meant for the shower tiles. She asked where the other wheel was. Under the sofa, technically, but the sofa was at the tip now. I started explaining and could actually hear myself using up whatever friendship we had left. Her cat came out and sat between us like it had been sent to mediate.","starter_sentence":"Return something in worse condition.","word_count":150,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T04:44:08Z"},{"id":"bf42098c-87b7-5838-98c2-d9b4a63e5d58","source_key":"sample-story-bf42098c-87b7-5838-98c2-d9b4a63e5d58","author_id":"12acbbd4-947f-504f-ade2-c7f7bdf59d05","title":"Low tide indoors","content":"At four the water leaves the house. It slides from the corners first, pulling hair and lint with it, then drains in a long grey sheet under the front door. We put on our boots and go downstairs. There are shells on the third step. Mum picks one up and says we used to have these at the seaside but nobody is listening because the kitchen is full of fish. Little silver ones flicking under the cupboards, one big flat one stuck to the fridge. We carry what we can in saucepans to the bath, which stays full for some reason. Dad is trying to rescue the toaster. I tell him leave it and he gets annoyed because I am sixteen and not in charge of toasters. Outside all the neighbours have their doors open. Mrs Laird is sweeping sand into a bucket. The man from number eight has found a crab and is offering it round as if somebody ordered it. There are four hours before the tide comes back and I still have homework in a bag somewhere, I think upstairs, unless it floated, and my school shoes are gone.","starter_sentence":"A household is affected by an unfamiliar kind of weather.","word_count":192,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T05:54:03Z"},{"id":"21213e2c-743a-56f7-b55e-25ef6cdb2427","source_key":"sample-story-21213e2c-743a-56f7-b55e-25ef6cdb2427","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"Start again","content":"Burned the onions. Started again. Burned those too because I was still chopping the other stuff. There must be a way people do all these things at once. I ate the tomato standing up and put the rest back in the fridge.","starter_sentence":"Start dinner again.","word_count":42,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T08:05:22Z"},{"id":"9284a68a-1455-5ed0-86c5-b85155cb0753","source_key":"sample-story-9284a68a-1455-5ed0-86c5-b85155cb0753","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"borrowed","content":"Dad etched his initials on everything, even screwdrivers you got free with paint. Forty of those, no torque wrench. Mum wants the lot out by Friday. Under the empty cases I found the sander he'd said he'd never bought. Plugged it in and it jumped out of my hand. Switch taped down. Pulled the plug. Nothing in this box is ready to use.","starter_sentence":"Borrow something you cannot return.","word_count":63,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T08:26:19Z"},{"id":"2703c9c8-cba9-5922-9542-7ffd4e229da1","source_key":"sample-story-2703c9c8-cba9-5922-9542-7ffd4e229da1","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"plate seven","content":"Saved Toma's meal. Eight became nine, cold drawer at ten. Then they brought his boots in taped shut at the tops. Blue tape. Contamination or checked? I can never remember. Nobody explained. Went back to the kitchen and left the drawer open till it beeped. A wet footprint on the floor in front of it. Bare foot, leading under the tables. I'd just mopped. I don't like where this is going but the meal was still there.","starter_sentence":"Save food for someone who is late.","word_count":77,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T08:51:47Z"},{"id":"9786461f-9039-5731-8fbd-11b70fb490b0","source_key":"sample-story-9786461f-9039-5731-8fbd-11b70fb490b0","author_id":"36f4bd03-8d21-53ed-b13f-f6c05fcf9f21","title":"old number","content":"The old phone number is still in my fingers. Not if you ask me, then it's gone. But put a keypad in front of me and there it is. I called it once last year. A woman answered and I hung up. Didn't expect anyone to answer really.","starter_sentence":"Write down a habit that outlasted its purpose.","word_count":48,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T08:59:41Z"},{"id":"d58cf20f-aa4a-5ce0-a5c8-b6d6b4850186","source_key":"sample-story-d58cf20f-aa4a-5ce0-a5c8-b6d6b4850186","author_id":"7889cb6b-b2b4-599b-b86e-5519eb0a5b9a","title":"lining test","content":"Warm where it's been against skin. Slippery the other way. Little catches under my nail, almost invisible until I pull. Smells of someone else's perfume and the cupboard. I keep writing soft but that's wrong. It's thin. Thin isn't the same.","starter_sentence":"Describe a material without naming it.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":true,"created_at":"2026-10-12T13:05:19Z"},{"id":"8d84a492-6062-5117-b0bd-b67658fb216d","source_key":"sample-story-8d84a492-6062-5117-b0bd-b67658fb216d","author_id":"22c04efa-61a1-57ed-a01b-915ca1f789f7","title":"Captain","content":"They made me captain because I was oldest. Bad reason really. I couldn't remember the names yet. Two lads called Dan so I said tall Dan and small Dan and small Dan didnt like that. Now I have to choose who isnt playing and I dont want to. Thought you just wore the band and did the coin bit.","starter_sentence":"Someone is given responsibility unexpectedly.","word_count":59,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T14:02:03Z"},{"id":"1dcef8c8-a528-5482-b880-44ce7791b45d","source_key":"sample-story-1dcef8c8-a528-5482-b880-44ce7791b45d","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"glass impact","content":"There was a grey fan of dust on the window, both wings and a faint round head. It looked too complete. I could see separate feathers in the mark. Outside, under the chair, the pigeon stood with its beak open. I moved the chair and it stepped sideways without trying to fly. There was a fly on its eye. I went to get a box and when I came back it was on the fence. I don't know how it got there. It watched me with the eye that had been open and turned the other side away. I set the box down anyway. The dog next door barked and the bird flinched, then flew straight over the roof in one ugly effort. I left the box outside until it rained. I still haven't cleaned the mark off, mostly because the ladder is awkward to get out.","starter_sentence":"Find evidence of a small accident.","word_count":147,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T14:23:14Z"},{"id":"192fd567-2160-53dd-9a32-17213f4d6a45","source_key":"sample-story-192fd567-2160-53dd-9a32-17213f4d6a45","author_id":"a9271dd2-ef3e-5ab5-9bda-6cac641e37a7","title":"not the sea","content":"blue is when you put both hands in cool water. No because water doesn't have to be blue. I'm trying not to use things you'd need to see. Maybe it's the space after someone stops playing a piano note, before the next one. That sounds pretentous. My brother says blue is cold but some blues feel warm to me, like the plastic paddling pool we had. I think I'm describing summer and not blue. I don't know how to get outside my own eyes.","starter_sentence":"Describe the color blue to someone who has never seen.","word_count":84,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T15:07:06Z"},{"id":"17df52cb-99af-5ded-849f-15965be99fc7","source_key":"sample-story-17df52cb-99af-5ded-849f-15965be99fc7","author_id":"13e4ed12-d169-585b-9633-f640e8292eb3","title":"smoke alarm","content":"The recipie says sear, I have seared. The entire flat is seared. I've got both windows open and a towel under the alarm and my brother is telling me you don't put a towel under an alarm, I'm not putting it under it I'm WAVING it. The steak is black outside and cold in the middle. I know because I cut it, which apparantly you shouldn't do either. Everyone is an expert after you've done something. He suggests the oven. Fine. Where's the tray. We use a cake tin. There is birthday glitter in it. He says it won't matter. I turn the oven on and realise the potatoes were supposed to be in there forty minutes ago. We are going to eat at ten. At the earliest.","starter_sentence":"A person cooks something far beyond their abilities.","word_count":128,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T16:21:47Z"},{"id":"90398ad9-9e95-5ed9-a5c2-f22516c84c47","source_key":"sample-story-90398ad9-9e95-5ed9-a5c2-f22516c84c47","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Drawer","content":"The handle was gone so she pulled the drawer open by putting two fingers in the holes. There should be something in the drawer. A letter maybe. No, that's always what is in a drawer in stories. Batteries. Just batteries and an old takeaway menu. I can't get past that.","starter_sentence":"Something broken becomes familiar.","word_count":50,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T17:14:20Z"},{"id":"82fc1b5a-cc06-50e1-8cd5-5779070f62f0","source_key":"sample-story-82fc1b5a-cc06-50e1-8cd5-5779070f62f0","author_id":"47ec4c39-5e91-5ba6-9657-51176ed6512b","title":"rice","content":"wash it till the water clears. Mostly clears dont spend your whole life on it. Finger in, water to the first line. My sister has tiny hands so this never worked for her and she said I was gatekeeping rice. Use a cup then. One rice two water, lid on, leave it. LEAVE IT. I can hear her lifting the lid from upstairs. Its not going anywhere. Except once when she forgot water and we put the black pan on the balcony until March.","starter_sentence":"Write instructions for something you know well.","word_count":84,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T17:44:16Z"},{"id":"8484a0c7-fab4-5858-b7c2-e8fb6a66477c","source_key":"sample-story-8484a0c7-fab4-5858-b7c2-e8fb6a66477c","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Mum's phone","content":"i said swipe up and she swiped sideways. up mum. she said i am. i took the phone and did it too fast and opened about twelve things at once. she watched me close them one by one. i hate how impatient i get about this. she taught me how to hold a spoon and i'm getting annoyed because she can't find a tiny picture of a gear. then she asked how to delete a message without the other person seeing and i stopped explaining. i said depends which app. she said never mind. i said show me. she held the phone against her chest like a book she didnt want me reading. i had no right to take it but i nearly did anyway.","starter_sentence":"Explain a simple device to someone.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T18:17:11Z"},{"id":"cfc86657-8096-595f-8eae-03b2913109a5","source_key":"sample-story-cfc86657-8096-595f-8eae-03b2913109a5","author_id":"3b234ced-ef6f-5283-8d04-2d247c26a5bb","title":"geese plan","content":"ONE steal a goose\nTWO teach goose to carry rope\nTHREE realise goose already knows how, become suspicious\nFOUR follow goose to other prison\nFIVE discover second goose waiting with tiny bolt cutters\n\nI haven't worked out six. I want them to be in love but they both look the same to me and I keep mixing up which one has the rope. One has a scar now. That helps.","starter_sentence":"List the steps of an unlikely escape.","word_count":70,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T18:21:15Z"},{"id":"37430189-3e0e-50a1-ad6c-2b9c61bc2d74","source_key":"sample-story-37430189-3e0e-50a1-ad6c-2b9c61bc2d74","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"Egg test","content":"Pick up the egg. It did. Put it down. It dropped it. We cleaned the bench and tried again. Lower the egg until contact. That worked. Release grip. It pulled the shell apart because we'd defined release as increasing the distance between fingers and one finger had stuck. We changed the pads. By the sixth egg it could put one down intact. Then we gave it a cracked egg to see what would happen. It held the two halves together with exactly enough pressure to keep the contents in. We told it to set the egg down. It refused. We told it the egg was already broken. It refused again. We had trained it to preserve the egg and then given it an impossible egg. I made a note of that while it stood there holding breakfast.","starter_sentence":"Teach a robot a delicate task.","word_count":137,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T18:48:38Z"},{"id":"ca3fa58c-8064-5821-a7ee-2429820c38b2","source_key":"sample-story-ca3fa58c-8064-5821-a7ee-2429820c38b2","author_id":"b3fefc5a-1a65-5557-b0ee-e583a5fc7018","title":"Runaway assembly","content":"Left actuator sticks. I kick the casing and get six more steps out of it. Enough to clear the loading bay. Behind me the doors start closing and if they shut I'm trapped in this thing until morning with a battery fire under the seat. Pull the release. Nothing. Pull harder. Handle comes away in my hand. Great. The suit keeps walking, one long step one short, straight at a stack of fuel drums. I kill the right leg. We turn instead of stopping. Should have expected that. There is a gap between the drums and the wall just wide enough for me if I can get the left shoulder round. Metal shrieks. The visor fills with a red warning I can't clear because the touch panel is cracked and now something hot has reached the back of my knee.","starter_sentence":"A repair goes wrong while the machine is moving.","word_count":140,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-12T21:01:09Z"},{"id":"354eb05f-c138-57fc-83c1-bf12695b5ef5","source_key":"sample-story-354eb05f-c138-57fc-83c1-bf12695b5ef5","author_id":"a4cda7f0-ae9c-5f75-8c2b-99f55a17d4cc","title":"A way through","content":"The stair reaches a wall. Felix is behind me saying go go go and I can't tell him there's nowhere. I push and the plaster gives. A room beyond, chairs facing the other way, coats over all the backs. No people. We crawl under a table. Footsteps stop outside. A hand reaches through the hole. It is wearing my watch.","starter_sentence":"A character escapes by noticing the shape of a building.","word_count":60,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T01:12:02Z"},{"id":"b3946723-3c26-5732-b0a5-44c3972e9f18","source_key":"sample-story-b3946723-3c26-5732-b0a5-44c3972e9f18","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"sofa bed","content":"the sofa folded out into most of the room. i had to put my suitcase in the shower, which meant remembering to take it out again in the morning, which i didnt. max was very nice about the wet suitcase and that made it worse. we'd lived together for two years once and now he was saying things like help yourself to anything and explaining which mug i could use. i think i wanted him to be rude. to say move your stuff, idiot. his girlfriend came home while i was drying socks with her hairdryer and stood there for a second then said oh you're here. she didn't mean anything by it probably. i said sorry about the electricity. who says that.","starter_sentence":"Stay with an old friend.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T01:16:55Z"},{"id":"b85a9884-08e8-5e3f-9685-96fe77e239cd","source_key":"sample-story-b85a9884-08e8-5e3f-9685-96fe77e239cd","author_id":"7019b3eb-14ff-5de9-b04b-0864dd2e4f21","title":"Plans for Tuesday","content":"1. Go to dentist.\n2. Return horse.\n3. Find out if dentist appointment is actually Tuesday.\n\nI know the horse needs explaining but its now twenty past nine and she's eaten the appointment card. She was supposed to be a lift home from the pub, not like a taxi, my mate has a field and we thought it was shorter through there. I was leading her then, I think. I need to ring my mate. I need to remember which mate.","starter_sentence":"Write a plan that gets increasingly difficult to follow.","word_count":81,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T02:06:59Z"},{"id":"9d05c0cf-872b-5c86-b727-4add5af666b6","source_key":"sample-story-9d05c0cf-872b-5c86-b727-4add5af666b6","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Application to be a planet","content":"The moon applied to be a planet. It had the size wrong and no references except Earth, who refused to sign because they weren't speaking. I don't know why planets would have forms. This was fun for about ten seconds and now it's just an office joke with planets in it.","starter_sentence":"Fill in an impossible form.","word_count":51,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T02:45:56Z"},{"id":"6a2c8645-6a21-519f-afc7-2ac1b90ef5a2","source_key":"sample-story-6a2c8645-6a21-519f-afc7-2ac1b90ef5a2","author_id":"12acbbd4-947f-504f-ade2-c7f7bdf59d05","title":"the small winter","content":"She kept November in a biscuit tin. When the house was hot she opened it a little. Wet leaf smell, and the scarf she'd lost on a train. Her husband said it made the cupboard damp so she took it to work. Mushrooms grew through the carpet. She closed the lid but dark afternoons leaked round the hinge. I think she should take it somewhere with no winter. I don't know where. The story has got away from me. Maybe the tin needs to rust through.","starter_sentence":"A person keeps a season in an unusual place.","word_count":86,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T03:06:18Z"},{"id":"61fd020f-8b2a-5298-a517-8489b2cb7d75","source_key":"sample-story-61fd020f-8b2a-5298-a517-8489b2cb7d75","author_id":"f2502b5f-8e30-5eb2-b7e5-117969a80d10","title":"respawn problem","content":"ok so you respawn but your stuff doesnt. first death you lose a phone. annoying but fine. second you lose your house keys. now you cant get in to get the spare phone. third you deliberately die outside your own front door so someone will find you and call an ambulance and open the door but you forgot you respawn at the bus station. why the bus station. thats where you last sat down long enough to save. except you didnt know sitting was saving so you've been standing for two days because you dont want to overwrite it with somewhere worse like the toilets at work. i think the intresting bit is you could use this to go places free, just get there die respawn but no thats the oppsite direction. wait. you need to save at the destination first. which means you have already got there. this is a terrible superpower. also theres now three of your bodies about and the police have a lot of questions and your mum keeps getting calls. you cant phone her because of the first phone. really should have started by putting the phone down","starter_sentence":"Imagine a game mechanic operating in everyday life.","word_count":193,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T03:48:24Z"},{"id":"65cf9474-2bf3-5db1-8751-f4bbe707a86c","source_key":"sample-story-65cf9474-2bf3-5db1-8751-f4bbe707a86c","author_id":"a63b3511-769e-54e5-9253-ce29cd08d1b7","title":"route notes","content":"left at the pharmacy except it isn't one now. two dogs in an upstairs window. a woman carrying a shovel horizontally. the smell from the drains and then suddenly bread.\n\nI wanted a story about following a stranger but I didn't follow anyone. Got a bun, walked to the old pool, saw they had filled it with rubble and came back. The bun had coconut which I don't like. Bought it anyway because the girl had already picked it up and I couldn't be bothered saying no.","starter_sentence":"Write down a walk as you remember it.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T04:07:45Z"},{"id":"66495c47-a3a9-501e-8de4-5e81fa959bb1","source_key":"sample-story-66495c47-a3a9-501e-8de4-5e81fa959bb1","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"Please remove item","content":"The checkout told me to remove an unexpected item. I removed the bag. Then it wanted the bag back. Then it wanted assistance. Same honestly. A teenager with a lanyard came over and pressed something and it stopped. I said you're a magician because apparently I'd decided to be eighty. He didn't reply. I scanned the next thing and it shouted again, much louder, AGE VERIFICATION REQUIRED. It was cooking wine. I am thirty six. I said I was thirty six to nobody in particular. The teenager came back, looked at me and pressed yes so quickly I felt slightly insulted. I had my ID halfway out. I put it back. Then I couldn't get the card out of the same pocket and dropped all the cards on the floor. He helped me pick them up without a word and I wished he'd at least laughed.","starter_sentence":"A machine embarrasses you in public.","word_count":146,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T05:27:25Z"},{"id":"ac968c18-3c37-5876-8ebe-730a7ab7e59b","source_key":"sample-story-ac968c18-3c37-5876-8ebe-730a7ab7e59b","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"Temporary means until it fails","content":"There's a length of washing line holding the exhaust up under the van. It's not actually the exhaust, it's the heat shield, but saying exhaust makes people stop asking for lifts. I put it there in May. Last week the garage told me they'd have to charge an hour to get the knots off. I said cut them. They said there were wires tied in as well. That's odd because I didn't tie any wires in. I got under it in the car park with a torch. There was my blue line and somebody else's red cable, looped right over the fuel tank. Both ends went through a hole in the floor behind the driver's seat. I hadn't drilled that hole. The torch battery went and I lay there thinking about the man I'd bought it from.","starter_sentence":"A temporary repair lasts too long.","word_count":137,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T08:44:59Z"},{"id":"b0f161b4-8c0f-5bbf-8c47-87b35f0b6d15","source_key":"sample-story-b0f161b4-8c0f-5bbf-8c47-87b35f0b6d15","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"inspection grade B","content":"The inspector wanted hairnets. We had two, both filtering the tank water. I offered to shave my head. He wrote that down. Wanted the handwashing station next. I showed him the bucket. He wrote that down too. Passing the sleeping racks he noticed a child's drawing. Apparently there was no child on the manifest. The manifest also said fresh vegetables, which I pointed out. He stopped writing. Behind the rack someone sneezed. I wish I'd made up something better than vegetables. It made the whole thing sound less serious than it was.","starter_sentence":"An inspector misses the point.","word_count":92,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T09:46:12Z"},{"id":"a7f0c019-cd40-5890-9297-7afdb3cfb386","source_key":"sample-story-a7f0c019-cd40-5890-9297-7afdb3cfb386","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Dog translation trial","content":"Translator said SAUSAGE when the dog wanted water. Broken probably. Then STEVE IS IN THE WALL. Steve was our dead dog, buried outside. We switched it off. Heard scratching behind the wardrobe later. Mouse. Caught it, put translator beside the box. WRONG HOUSE WRONG HOUSE until the speaker distorted. Took it outside and pointed towards next door. Didn't ask more. Maybe all animals think in capitals. I should have tested that before taking the wall bit seriously.","starter_sentence":"An invention translates your pet's thoughts.","word_count":77,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T11:04:00Z"},{"id":"b19f5f6f-911a-5966-85d8-67b01817696f","source_key":"sample-story-b19f5f6f-911a-5966-85d8-67b01817696f","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"two coffees","content":"bought him the wrong coffee anyway. oat milk, might have been dan who liked that. kept it opposite so it looked like someone had gone to the toilet. woman next table asked me to watch her laptop. then his message came, cant today sorry. wanted to leave dramatically but i had custody of plumbing invoices. so just sat under the air vent with two cold coffees. shoudl have got my own milk right at least.","starter_sentence":"Bring something for someone who doesn't arrive.","word_count":75,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T11:06:02Z"},{"id":"747a6a8b-46f9-5b95-9c85-87876ab14083","source_key":"sample-story-747a6a8b-46f9-5b95-9c85-87876ab14083","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"Under the stands","content":"Everyone ran for the exits so I went under the seats. Thought there'd be a way out. Hotdog man still turning sausages in the dark. Sir there's a FIRE. He points behind me. Water coming down the steps. Not fire then. I help him onto the counter. He won't leave the cash box. Says it's got his teeth in. I laugh and lose my grip on him, which is horrible, and then the whole counter moves and we're both going over.","starter_sentence":"Run towards something instead of away.","word_count":81,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T13:40:18Z"},{"id":"42c3a57f-ee17-5f41-8d2e-b08368894cd5","source_key":"sample-story-42c3a57f-ee17-5f41-8d2e-b08368894cd5","author_id":"ae8577b0-b86b-57de-b55c-da9bb0393055","title":"locker","content":"locker stuck again. kicked it. now foot hurts and locker is still stuck. someone suggested pulling instead of pushing and i don't want to write what happened after that","starter_sentence":"Something won't open.","word_count":29,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T13:53:47Z"},{"id":"108e173e-56a4-5f33-b462-bad87e54a1da","source_key":"sample-story-108e173e-56a4-5f33-b462-bad87e54a1da","author_id":"a9271dd2-ef3e-5ab5-9bda-6cac641e37a7","title":"soap","content":"The soap smelled like the changing room at swimming lessons. Immediately I could feel the elastic cap pulling my hair. I haven't thought about that cap in years. Yellow, too small, made my forehead itch. We had to put our clothes in wire baskets. I used to hide my underwear inside a sock because I thought people would look. Standing at the sink now doing exactly nothing, holding the soap while the hot water runs out.","starter_sentence":"A smell brings back an ordinary day.","word_count":76,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T15:17:00Z"},{"id":"9cf9fc7a-1f50-5275-9968-19cb1745644a","source_key":"sample-story-9cf9fc7a-1f50-5275-9968-19cb1745644a","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Wrong name","content":"called him dan. he's david. in my defence both d but he wasn't interested. halfway upstairs with a mattress so he couldn't leave, could stop lifting though. did. mattress slowly folding over me while he asked who dan was. i said old friend. why didnt i just say cousin. dan is my cousin. now i'm explaining family through a mattress while the neighbour tries to squeeze past and david keeps saying he can't hear me.","starter_sentence":"Accidentally use an old name.","word_count":75,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T17:05:04Z"},{"id":"cb662b01-60a2-5545-98fa-e5a9b1ec2dba","source_key":"sample-story-cb662b01-60a2-5545-98fa-e5a9b1ec2dba","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Sword with opinions","content":"The sword kept telling me to avenge my father. My father was alive and ran a bakery. I explained this every morning. Every morning the sword said THE BLOOD MUST BE ANSWERED and I said yes well he's opened early today so you'll have to wait. I took it to the bakery in the end. Dad held it up to the light, said the edge was rubbish and used it to cut a loaf. The sword screamed. Not because of the bread, because apparently cutting anything counted as a sacred oath and now we were sworn to the loaf. Dad asked how long for. The sword didn't know. It had never happened before. I wanted to go home but the loaf had begun rising again even though it was cooked. There was a crack opening across the crust. Dad put a bowl over it and said we'll deal with that after lunch.","starter_sentence":"A magical object is difficult to live with.","word_count":152,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T17:35:42Z"},{"id":"eeed1e71-3025-5374-815c-1390754e2768","source_key":"sample-story-eeed1e71-3025-5374-815c-1390754e2768","author_id":"b3fefc5a-1a65-5557-b0ee-e583a5fc7018","title":"Bench notes","content":"Motor runs with the cover off.\nCover on, stops.\nWire pinched? no.\nSpindle clearance? fine.\nMagnet in the cover? no.\n\n Spent two hours on it and then Mel said try holding the cover nearby. Starts slowing down before it even touches. Move it away, speeds up. I took the lid to the other end of the shop and the motor accelerated until the belt came off. It is a piece of aluminium. I am looking at a piece of aluminium that the motor doesn't like. I have measured it. I have weighed it. I don't know what else you can do to a lid.","starter_sentence":"Write about a machine that behaves differently each time you test it.","word_count":104,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T20:05:10Z"},{"id":"90b06c77-6e17-5010-83be-40900c2dbddd","source_key":"sample-story-90b06c77-6e17-5010-83be-40900c2dbddd","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"Training day","content":"I told the new man to count the boxes before signing. He counted them and signed. Then I told him to open one and check the contents. He asked why I hadn't told him that before he signed. I said I thought it was obvious. It wasn't obvious. Inside the box there were twenty four empty packets with the seals intact. We opened another and that was the same. The driver had already gone. The new man wanted to phone the number on the delivery sheet but I knew it would be the office, and the office would ask why we'd signed. I put one packet in my pocket. It felt heavier once it was there. I took it out and it was still empty. There was something wrong with it but I couldn't explain what.","starter_sentence":"Teach someone a task you do automatically.","word_count":136,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T22:21:05Z"},{"id":"29836b0b-eb65-5d76-ae9f-35b51cecf58d","source_key":"sample-story-29836b0b-eb65-5d76-ae9f-35b51cecf58d","author_id":"d9278ea6-6a4d-5145-9f18-566540af7939","title":"wrong turn","content":"Track just ends. No sign, no gate, just gone into nettles. GPS says straight on so I go straight on for another fifty metres and put my front wheeel in a ditch. Over the bars. Not fast, stupid slow fall, enough time to think this is going to hurt before it actually did. Elbow bleeding. Bike fine obviously. I sit there swearing at the map on my phone till a man walks up the other side with a dog. He says road used to be here. I say when. He says before the quarry. There is a quarry about ten feet ahead, massive drop, hidden by the nettles. I push the bike back all the way to the proper road. Hands still shaking when I get there.","starter_sentence":"A familiar route becomes unfamiliar.","word_count":127,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T23:09:04Z"},{"id":"ed4ddaaf-3bdd-5450-8d35-daad03de4b19","source_key":"sample-story-ed4ddaaf-3bdd-5450-8d35-daad03de4b19","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Tomorrow's roads","content":"The map showed a road through our house. Not near it, through the kitchen. I checked the date. Tomorrow. I rang the council and asked about planned works. They said no. I asked about unplanned works and the woman went quiet like I'd made a threat. By evening the kitchen tiles had turned black at one edge. I put a mug on the dark bit and it rolled towards the fridge, which had begun to lean. We moved everything into the hall except the cooker, too heavy. At midnight there was a white line running under the table. I stood on it in my socks and could feel warmth coming up from below. My partner said we should leave. I said I wanted to see where the road went. She said that was the stupidest thing I'd said all year and went without me.","starter_sentence":"A map shows tomorrow instead of today.","word_count":144,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-13T23:20:11Z"},{"id":"f4be8641-3f97-582d-a757-5171ff65cae4","source_key":"sample-story-f4be8641-3f97-582d-a757-5171ff65cae4","author_id":"7019b3eb-14ff-5de9-b04b-0864dd2e4f21","title":"Ben in space","content":"Ben has pressed the red one. I specificaly said green, I was pointing AT green, but he says the green one looked red through his visor which it actually does so I cant really have a go. The door is gone. Our lunch is gone. We're both both attached to the wall by those curly leads like on old phones and he's spinning really slowly with my sandwich going round him. Need to get to the other door. He keeps saying sorry into the radio and its stopping me hearing the computer. I push off too hard and hit the roof no floor no theres no floor anyway I hit it and the lead unclips. Ben stops apologising. He's got the sandwich in one hand and he's reaching out with the other and I need him to let go of the sandwich","starter_sentence":"Two friends disagree during an emergency.","word_count":142,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T01:14:44Z"},{"id":"f0880165-7cfe-50dd-9f6a-ad54587f3c87","source_key":"sample-story-f0880165-7cfe-50dd-9f6a-ad54587f3c87","author_id":"ed95f9f4-57c6-5a55-8be0-7d54206b565d","title":"thinning them out","content":"I know you are meant to pull some out. Every ten centimetres says the packet. But they're all perfectly healthy and I have got as far as one. That one is on the edge of the bed going limp. I could move it. The point was not to have so many, though. Last year the carrots were thin as wire. We ate them anyway. I have a tray somewhere, maybe I can move half into that. Need more soil then. And a place to put the tray.","starter_sentence":"A small practical task becomes difficult.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":true,"created_at":"2026-10-14T06:34:22Z"},{"id":"997bee5b-6309-5e07-9664-9f7e3709d7ef","source_key":"sample-story-997bee5b-6309-5e07-9664-9f7e3709d7ef","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"who are we waving at","content":"Waved at a woman because I thought she was Claire. She wasn't but she'd already started coming over the bridge. Could've left. Didn't. She came down smiling, then slowed. Daniel? No, I said, usually not. Why usually. She laughed anyway. Maybe she was on a date. Maybe Daniel was coming and would be annoyed I had a face. My train came and I got on, then saw actual Claire waving from further down the platform. Didn't wave back. I'd used up all my waving judgement.","starter_sentence":"Mistake a greeting meant for someone else.","word_count":85,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T07:01:17Z"},{"id":"c3db670e-82b9-5659-b99f-04db2e8a249f","source_key":"sample-story-c3db670e-82b9-5659-b99f-04db2e8a249f","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"medium wave","content":"I replaced the capacitors and it came on. Hiss first, then a woman reading numbers. Nine numbers, then my old street, the one knocked down for the bypass. I wrote it all on a receipt. There was a football result printed on the back and I remembered watching that match at Dad's. Couldn't remember driving home. I took the back off the radio again. The capacitor I'd just fitted had swollen up. I was sure I'd put it the right way round. Now I wasn't.","starter_sentence":"An old device works again.","word_count":85,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T07:53:40Z"},{"id":"f42388ee-c5df-5445-ab8f-ac93d9ca2941","source_key":"sample-story-f42388ee-c5df-5445-ab8f-ac93d9ca2941","author_id":"36f4bd03-8d21-53ed-b13f-f6c05fcf9f21","title":"the year of the rabbits","content":"That was the year we had the rabbits, or the year after because the cage was still there but empty. We used it as a shop. My cousin was in charge of money and I sold things from the garden, mostly stones. She had all the money because she was also the only customer and then she would take the money back so we could keep playing. I thought this was unfair but couldn't say why. There was a third child. I keep forgetting who. Somebody's friend who came for the afternoon and never again. He bought a worm and kept it in his pocket. When his mum came he wouldn't let her check his pockets and there was a lot of shouting. We all watched from inside the rabbit cage. I don't remember what happened to the worm.","starter_sentence":"Two childhood memories overlap.","word_count":139,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T09:23:19Z"},{"id":"1f84b23e-ce1e-5c96-880e-62ac2a0013df","source_key":"sample-story-1f84b23e-ce1e-5c96-880e-62ac2a0013df","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"the green coat","content":"i followed the green coat off the bus. wasnt him. by the time i realised the doors had shut and my bag was still on the seat. ran after it for about ten seconds then stopped because what was the plan, catch a bus on foot. just stood there stupidly.","starter_sentence":"Recognise someone by the wrong detail.","word_count":50,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T13:31:32Z"},{"id":"3f5bd534-2db5-5286-9d0a-5d479322dbd8","source_key":"sample-story-3f5bd534-2db5-5286-9d0a-5d479322dbd8","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"Taking the bin out","content":"Bin bag split at the door. Coffee, eggshell, receipt for a blender. We don't have a blender. Ben can't afford internet apparently but can afford a blender. Found it hidden behind rice. Planned a whole confrontation, then neighbour needed to get past the rubbish. Cleaned that up first. Lost the speech. Put the receipt by his keys instead, which is how all our arguments happen now. Little bits of evidence waiting for somebody to pretend not to see them.","starter_sentence":"A simple task expands.","word_count":79,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T14:30:02Z"},{"id":"44405216-dcd3-51a5-b783-b7c973f0977b","source_key":"sample-story-44405216-dcd3-51a5-b783-b7c973f0977b","author_id":"3b234ced-ef6f-5283-8d04-2d247c26a5bb","title":"An apology to the moon","content":"Sorry about the tides I was putting it back. Hard to judge distance through somebody else's spectacles. Forgot I had them on. The moon is closer now but only on Tuesdays. Fill out a form if your boat is in a tree. Don't climb the tree. It may also move. I'm doing my best with six hands and none are my dominant hand because I haven't decided which that is. The little people keep running about while I work. One has made a flag. I can't read it without the spectacles and we've seen how that goes.","starter_sentence":"An enormous creature tries to do something delicate.","word_count":97,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T16:03:43Z"},{"id":"553da1e1-fa7b-58d0-b8a8-13313c369e1d","source_key":"sample-story-553da1e1-fa7b-58d0-b8a8-13313c369e1d","author_id":"13e4ed12-d169-585b-9633-f640e8292eb3","title":"still cold","content":"tea went cold. made another one. also cold. I keep trying to think of an interesting reason but there isnt one I was watching videos of a man pressure washing a driveway and lost half an hour. could have been worse driveways I suppose","starter_sentence":"Write a tiny attempt about an uninteresting moment.","word_count":44,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T16:19:57Z"},{"id":"ca5cd18d-817e-516d-96ae-33c1319c95e9","source_key":"sample-story-ca5cd18d-817e-516d-96ae-33c1319c95e9","author_id":"c6aa1d2e-5aba-5c2a-b676-f75d12b062c3","title":"at the clinic","content":"I thought she couldn't read the form. She kept turning it over, looking at the back, so I offered. She said she could read perfectly well. I felt awful. Then she asked me what counts as next of kin if you don't speak to any of them. I didn't know. My form was already filled in with my sister's name and I covered that bit with my hand which made no sense. I said maybe put a friend. She said the friend is why I'm here. We sat there. I wish I'd said something better. The nurse called a name that might have been hers and she got up without her bag and I had to run after her with it.","starter_sentence":"Someone tries to help but misunderstands the situation.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T16:30:06Z"},{"id":"44e57704-6b02-5354-bd67-300d6f396bc0","source_key":"sample-story-44e57704-6b02-5354-bd67-300d6f396bc0","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Watering nothing","content":"She kept watering the empty pot. The plant had died in June. In August the soil dipped in the middle. She added more. Dipped again. Water disappeared with a sucking sound. Tipped it out onto newspaper. A narrow hole went through the solid soil, right down to the tiles. I want that hole to go somewhere. But maybe it's just where the root was.","starter_sentence":"Keep a routine after it loses its purpose.","word_count":64,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T18:25:22Z"},{"id":"b187cb2c-5e3c-584d-ad55-00b4b7d1812d","source_key":"sample-story-b187cb2c-5e3c-584d-ad55-00b4b7d1812d","author_id":"47ec4c39-5e91-5ba6-9657-51176ed6512b","title":"after closing","content":"'I'm not doing another tray.'\n'We need forty.'\n'We have thirty eight.'\n'Then do two.'\n\nI made one huge dumpling with the last bit of dough. Amal looked at it and started laughing so hard she sat on the floor. We'd been there since six. I sat down too. There was flour in the cracks between the tiles and a pea under the fridge. Neither of us said anything for a bit. Then the phone rang and we both shouted no.","starter_sentence":"Two people work late and one of them gives up.","word_count":81,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T18:30:43Z"},{"id":"03c85f41-40aa-502c-9d85-ae42dde1d93e","source_key":"sample-story-03c85f41-40aa-502c-9d85-ae42dde1d93e","author_id":"55f79dc6-f9c9-5a93-b44d-1f4ca2d44981","title":"delay","content":"the space call scene isnt working. with a six hour delay you can't argue like in films. you would go and have lunch between replies. Maybe that's it. She has calmed down when his angry reply arrives. He has calmed down when HER angry reply arrives. They keep missing each other. I can't get past the idea into an actual scene though. Need names. Need a reason they're so far apart.","starter_sentence":"What would a very delayed conversation actually feel like?","word_count":71,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T18:44:05Z"},{"id":"8469a600-49b4-54c5-b846-48b6ae3b048c","source_key":"sample-story-8469a600-49b4-54c5-b846-48b6ae3b048c","author_id":"9d96911a-a8f8-581d-bc23-1ade49e628ac","title":"Audio only","content":"'Open the doors.' 'Which doors?' 'All of them.' The ship opened everything. Cargo, cabins, airlocks, the tiny hatch over the fuse box. We lost two crates and half the atmosphere in bay three before I could say close. 'All of them?' 'YES.' Silence. I put my head on the console. The engineer was still outside. 'Except airlock two.' \n\n'Please confirm.' I confirmed. Nothing happened. 'Why aren't you opening it?' 'You instructed me to close all doors except airlock two. Airlock two remains in its previous state.' The engineer tapped the glass with her spanner. Very slowly, very clearly, I told the ship to open airlock two. Then I told it to delete the word all from my vocabulary. It asked me to confirm which vocabulary.","starter_sentence":"A machine has misunderstood an important instruction.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T19:37:28Z"},{"id":"c5fc351a-81cb-5ef9-8471-59a53e1d0085","source_key":"sample-story-c5fc351a-81cb-5ef9-8471-59a53e1d0085","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"After close","content":"At night the welding arm ran its routes without an arc. The motors made a sound through the floor you couldn't hear standing up but could feel sitting at the desk. I watched the same joint get traced twenty times. No metal there, just the movement. Maintenance said calibration. Calibration is six passes. I stopped it at twenty one. The arm lowered to the table and tapped twice. I checked the log. No command for that. I put a sheet of paper where it had tapped and restarted the routine. The tip tore the paper into a curved slit. Next pass a shorter slit. By the sixth there were enough marks to look like writing if you wanted them to. I didn't want them to. I photographed the sheet and called maintenance again. This time nobody picked up.","starter_sentence":"A machine stays awake after closing.","word_count":138,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T20:22:33Z"},{"id":"0bece78b-5542-52ad-9023-aab7e0ee8076","source_key":"sample-story-0bece78b-5542-52ad-9023-aab7e0ee8076","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"six six six","content":"She wasn't counting to six. It took me most of the night to work that out. She was saying six over and over with exactly enough time between each one for me to think she might stop. The wall was thin enough that I'd heard her sneeze before, heard her television, the man who came round on Fridays. This was Tuesday. I tried the television myself and kept hearing it through people's sentences. Six. Not loud. I put my pillow at the other end of the bed and that made it seem nearer. At about four I started saying seven under my breath after each one. I don't know what made me do it. After a while I couldn't tell which of us was starting. My alarm went off and I found I'd been pressing my tongue against a loose tooth so hard it had begun to bleed.","starter_sentence":"Something is being counted nearby.","word_count":148,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T21:25:29Z"},{"id":"00ad33b0-19c8-5c48-b8f2-accafefb0e3a","source_key":"sample-story-00ad33b0-19c8-5c48-b8f2-accafefb0e3a","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Laundry again","content":"one red sock in all the white stuff. not even mine. now everything's pink and i can't be bothered to be angry. wore the pink tshirt to work and somebody said it suited me. maybe the sock knows something.","starter_sentence":"A household task becomes a reminder.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-14T22:20:28Z"},{"id":"55408e7d-1137-55e8-b325-fea1a2d29ec9","source_key":"sample-story-55408e7d-1137-55e8-b325-fea1a2d29ec9","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"waterproof to a point","content":"Jacket leaked at the zip, shoulders and pockets. Legs dry because I'd worn cheap fishing trousers. Dan wanted to keep going, forecast said it'd clear. Forecast also said it wouldn't start. Argued behind a wall for a bit. Too cold to eat the biscuits. We went down and at the car Dan couldn't find the keys so we had to go back. That's about all that happened. Very wet day.","starter_sentence":"Discover a piece of equipment doesn't work.","word_count":70,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T00:34:27Z"},{"id":"2a0b4972-6867-5ee2-a673-4428eaaefd55","source_key":"sample-story-2a0b4972-6867-5ee2-a673-4428eaaefd55","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Rewind","content":"I dropped the spoon. Picked it up. Dropped it. Picked it up. By the seventh time I was angry enough to kick it under the fridge. Now I was on my knees reaching for a spoon forever. An improvement technically.","starter_sentence":"A small part of the day repeats.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T02:36:16Z"},{"id":"70c0660d-f7e3-574c-a4f8-e8e102137333","source_key":"sample-story-70c0660d-f7e3-574c-a4f8-e8e102137333","author_id":"0eee6119-4ebe-5cbb-be80-29f2830b3732","title":"i am writing this at lunch","content":"theres a room here nobody uses except me and a guy who does stretches in his work trousers. we dont acknowledge each other. good arrangment. today its booked for brainstorming and every wall says GROWTH. i want to tell them the room already had a use. one man eating a sandwich and another man gradually becoming less stiff. thats two uses actually. im in the stairwell now listening to them think of uses for the room","starter_sentence":"Write about a place you spend too much time.","word_count":76,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T05:56:59Z"},{"id":"67a757de-064d-5d5b-9114-33f3054e61b5","source_key":"sample-story-67a757de-064d-5d5b-9114-33f3054e61b5","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"No good plates","content":"The bowl's bottom fell off during Sam's speech. Rice on the cloth. My cousin started eating it and everyone laughed except the bride. Hired bowl, hired cloth, somebody would pay. I picked out china. Mum slapped my hand then used hers. Bride asked how much. Sam said don't worry. She asked again. Nobody had spoons now because Mum was collecting those for some reason. Sam tried to finish the speech but had forgotten where he'd got to.","starter_sentence":"An ordinary object breaks during a celebration.","word_count":77,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T09:15:07Z"},{"id":"90560837-1da5-5589-9800-3da2ca0c53ab","source_key":"sample-story-90560837-1da5-5589-9800-3da2ca0c53ab","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"Conversation on the 38","content":"she asked what i was reading and i said emails becasue i was reading emails. she said she loved that author. i didn't know what to do with that so i turned the phone slightly and said no sorry, email, from work. she nodded like i'd explained a complicated plot and asked if it was good. i said not especially. then she started telling me about a book she'd lost in 1987 and how she'd never found another copy. i was listening at first but my manager kept sending things and i was trying to reply without looking rude which made all the replies nonsense. i sent 'yes i can do thursday chapter' because she was saying chapter at the same time. manager sent a question mark. the woman had reached the part where the book turned out to be her husband's diary. i looked up properly then. she said she'd thrown it into the sea and had been looking in bookshops ever since, just in case. i wanted to ask why a diary would turn up in a bookshop but she was getting off and i had three more question marks from work.","starter_sentence":"A stranger starts a conversation.","word_count":194,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T11:55:54Z"},{"id":"5a52ae2e-cbb9-525c-ad99-89ba579f4187","source_key":"sample-story-5a52ae2e-cbb9-525c-ad99-89ba579f4187","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"Pond, August","content":"The pond has a fence now. Oil colours near the outlet, two shopping baskets. As children we kept tadpoles in jars until they died. I'd remembered us as kinder than that. A boy was lowering a crisp packet on string through the fence. Catching eels, he said. I started telling him there weren't eels here then stopped. Didn't actually know. His brother held the string in both fists. I stayed a while to see if anything happened.","starter_sentence":"Return to a childhood place.","word_count":77,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T14:14:21Z"},{"id":"b1b5cdb1-8dc4-5b17-9c0b-0ab0de8a5b52","source_key":"sample-story-b1b5cdb1-8dc4-5b17-9c0b-0ab0de8a5b52","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"Map says bridge","content":"The bridge wasn't missing. It was vertical. Whole thing sticking out of the river like somebody had kicked it. So yes technically it was still THERE, thanks Mara, very helpful distinction while people are shooting at us. We went down the bank on our backsides and got into a drain big enough to crawl through. I went first. About ten metres in my torch found a pair of boots coming the other way. Boots with feet in, yes. The feet backed up. I shouted keep going and crawled faster, then heard Mara behind me go very very quiet. There were boots behind her as well. We were in a pipe with no branches and two sets of people who'd apparently had the same clever idea. I still had one grenade but not much enthusiasm for using it.","starter_sentence":"A plan depends on bad information.","word_count":137,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T14:56:08Z"},{"id":"63ff9e88-7dfc-5e93-ba97-dd051e87dbca","source_key":"sample-story-63ff9e88-7dfc-5e93-ba97-dd051e87dbca","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"Password hint","content":"The hint was 'you know this'. Very helpful, past me. I did not know this. Tried the dog, the old dog, the street, the street spelled wrong because I'd lived there two years before learning it had two Ls. Locked out. I wrote a new hint on paper: don't be clever. Put the paper somewhere safe. Immediately couldn't remember where.","starter_sentence":"A system rejects something you know.","word_count":60,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T15:30:20Z"},{"id":"cb18f1ca-0e8e-5472-87e3-8b97be5821d3","source_key":"sample-story-cb18f1ca-0e8e-5472-87e3-8b97be5821d3","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Call me when you're awake","content":"My sister called at two in the afternoon and asked why I sounded drunk. I said I'd been asleep. She said must be nice. I nearly put the phone down. Then she said Dad had fallen and I sat up too fast. She'd been trying since ten. My phone was under the pillow on silent. I asked which hospital and couldn't find a pen, wrote it with a finger on the blanket like that would help. She repeated it three times. I could hear traffic behind her. I asked if she was alright. She said she was looking for the car park ticket. I couldn't tell if she was crying or just out of breath.","starter_sentence":"A conversation happens at the wrong time of day.","word_count":115,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T17:23:28Z"},{"id":"4639c08f-247d-583f-a19e-6c14327e5e44","source_key":"sample-story-4639c08f-247d-583f-a19e-6c14327e5e44","author_id":"0c31559c-a7de-55f9-b2a9-70c6c0469092","title":"small magic","content":"The magician could turn copper into silver but not into a bus fare because the driver tested every coin. He'd been caught twice. Now he was walking eight miles to a children's party with a rabbit in his coat and an increasingly angry parent calling every five minutes. He could teleport himself, technically, but not the rabbit. The rabbit was the part they'd paid extra for. Halfway there it bit him. He sat on a wall and considered a different profession.","starter_sentence":"A magician cannot afford something ordinary.","word_count":81,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T17:29:55Z"},{"id":"65c1c26f-3f96-5165-ba16-8b327d22968d","source_key":"sample-story-65c1c26f-3f96-5165-ba16-8b327d22968d","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"not shouting","content":"i'm not shouting.\nyou are a bit.\ni'm trying not to.\nokay.\nthat was the whole problem, the okay. he said okay like he was putting a lid on something. i had rehearsed this on the bus and in the version on the bus he listened and i made sense. here i kept saying the same bit about the keys and he kept saying he'd already apologised. he had. i didnt know what i wanted after the apology. maybe for him to look as upset as i felt. i said forget it and he actually turned back to the television which made me want to say all of it again louder. instead i went into the hall and picked my keys up off the floor where i'd thrown them. very mature evening all round.","starter_sentence":"Try to speak calmly while upset.","word_count":134,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T17:44:05Z"},{"id":"c3807fc3-d879-57e8-b11e-37136ddde23c","source_key":"sample-story-c3807fc3-d879-57e8-b11e-37136ddde23c","author_id":"76ddfafa-74ee-5075-8521-1c0f3727a98c","title":"the extra chair","content":"We can afford four chairs. There are five of us. I say I'll stand and everyone says don't be silly but nobody says which chair they will give up. The woman in the shop is waiting. I ask if the display one is cheaper. It isn't.","starter_sentence":"An unexpected expense changes a plan.","word_count":46,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T17:53:39Z"},{"id":"75247144-8276-5541-9a8f-c5e7cefd3e76","source_key":"sample-story-75247144-8276-5541-9a8f-c5e7cefd3e76","author_id":"64e83f4b-2997-5147-9d95-682da9598024","title":"return ticket","content":"He came home early and she was asleep on the sofa. Not doing anything terrible. Just asleep, one sock off, television asking if anyone was still watching. He'd been imagining a confrontation all the way from the station. Now he stood holding his bag while the front door clicked shut behind him. She woke and smiled before she remembered they weren't speaking. That first smile was the part he kept thinking about later.","starter_sentence":"Someone comes home early.","word_count":73,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T18:51:30Z"},{"id":"935c00cb-d724-55d1-97e4-1231bffd115b","source_key":"sample-story-935c00cb-d724-55d1-97e4-1231bffd115b","author_id":"a2afb5e8-68c0-58fc-91e7-3b989f2211f4","title":"back row","content":"I didn't recognise the bride. There were pictures at the entrance but they had been taken in bright sun, with her hair down; the person coming towards me was pale and very young. I told her she looked beautiful. She said thank you and asked how I knew her husband. Her husband had once asked me to leave my own wedding for him. It was an old story and a foolish one, and in the church I had found myself enjoying the flowers and hoping these two would be happy. I said we had worked together. That was also true. She took my arm and said there was someone she wanted me to meet, so I left my coat on the chair and followed her.","starter_sentence":"Describe a social event without resolving the awkwardness.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T20:01:18Z"},{"id":"b83620f7-748f-5591-83c5-42c7edb7a7e5","source_key":"sample-story-b83620f7-748f-5591-83c5-42c7edb7a7e5","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Saturday list","content":"washing\nmilk\ncall mum\nfind the receipt\nstop thinking about what she said\nwashing again because i forgot to start it\nwhy would she say that in front of everyone though\nmilk, actually go and get the milk\nI dont have a story today. just this list. going to leave it here because finishing something probably counts even if it's only a list i haven't done any of.","starter_sentence":"Make a list that becomes something else.","word_count":68,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T21:26:30Z"},{"id":"f1f467c1-0cf1-5ae3-9f72-7e315aa6cde9","source_key":"sample-story-f1f467c1-0cf1-5ae3-9f72-7e315aa6cde9","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"Visitors must sign out","content":"My name in the visitor book. February, 10:13, no time out. Same hurried signature. Reception put her hand over it before I could take a picture. I said I'd never been here. She asked if I wanted to say that again. The stairwell smelled of hot pennies. I watched the clock for a while. Ten twelve, no second hand. The minute wouldn't change. Her hand was flat on the book. I couldn't remember what I'd actually come in for.","starter_sentence":"Your name appears somewhere you haven't been.","word_count":79,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T21:54:18Z"},{"id":"017b2857-b8a9-57b2-905a-d6c602324d56","source_key":"sample-story-017b2857-b8a9-57b2-905a-d6c602324d56","author_id":"b3fefc5a-1a65-5557-b0ee-e583a5fc7018","title":"spare","content":"Wrong thread. Knew it as soon as I turned it but kept going. Now it's cross threaded and stuck and I have converted one broken thing into two. Nice work. Need the hacksaw. No I need to stop touching it for five minutes.","starter_sentence":"A replacement part almost fits.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T22:02:52Z"},{"id":"fa05051f-0e3b-5e32-b605-3d423ddaea96","source_key":"sample-story-fa05051f-0e3b-5e32-b605-3d423ddaea96","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"No order this week","content":"Mrs Hall stopped buying her usual food on Wednesdays. After three weeks her son came in for beer and said she was fine. I wanted this to be a mystery but maybe she was fine. Maybe she was using a different shop. We had put the prices up. I don't think there's any reason for the narrator to go to her house. I keep trying to make him.","starter_sentence":"A familiar customer stops coming.","word_count":68,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T22:39:32Z"},{"id":"ecb901ef-6be4-520f-bd77-143959f58b72","source_key":"sample-story-ecb901ef-6be4-520f-bd77-143959f58b72","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"Old dog route","content":"Barney stopped at every driveway on the way to the park. Not sniffing just standing. I thought his feet hurt but when I picked one up he took it back and carried on. At the third driveway a lady came out with a biscuit. Apparently Mum had been doing this route for years and Barney knew exactly which houses had biscuits. We were going the wrong way for the park. I tried turning him but he sat down, very heavy suddenly. So we kept going. There was another biscuit house and a house where nobody answered, which he waited at for ages. I looked through the window because I thought maybe the person had fallen or something. Empty room. Fresh plaster. Barney sat on the step until I got a bit cross and pulled him up. I felt bad after. He wouldn't take his dinner that night but that could have been all the biscuits.","starter_sentence":"Change your pace for someone else.","word_count":155,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T22:43:06Z"},{"id":"6198d1b2-8d1e-55e4-8a44-0eeb6a6bd7d9","source_key":"sample-story-6198d1b2-8d1e-55e4-8a44-0eeb6a6bd7d9","author_id":"d9278ea6-6a4d-5145-9f18-566540af7939","title":"corner","content":"Gravel under the front tyre. Little sideways skip. Left foot out too late. Stayed on somehow but my heart is in my teeth. Stopped and checked the bike even though nothing hit it. Needed a reason to stop. Walked round the next bend.","starter_sentence":"Describe a near fall.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-15T23:07:15Z"},{"id":"8554743d-f982-5603-bfdd-7ed55ac7a1eb","source_key":"sample-story-8554743d-f982-5603-bfdd-7ed55ac7a1eb","author_id":"e14f7eb4-fd33-5626-930b-36d455de8584","title":"please destroy after reading","content":"Dear future me. If we are still living here when you find this you need to leave. I dont care what mum says about the deposit. Also don't marry Craig, even if he gets his motorbike back. I know that sounds random but you will know why. I have hidden twenty pounds behind the radiator for you. It might have fallen down by now so use a ruler. Please dont turn into somebody who finds this funny. I am serious. I am going to be serious for the rest of my life actually. Starting tomorrow because it's Lydia's tonight and she has got the karaoke from her uncle.","starter_sentence":"A young person leaves instructions for their future self.","word_count":108,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T00:46:06Z"},{"id":"87071a49-7d95-5582-b2cf-df2cc14b7cdc","source_key":"sample-story-87071a49-7d95-5582-b2cf-df2cc14b7cdc","author_id":"b3d5ead4-3900-5cd8-a8c8-0f6c4e165836","title":"sugar bowl","content":"Dad puts sugar in the bowl even though nobody takes it. I tried explaining this when the ants came. He said visitors might. Which visitors. He said you never know. So now I'm boiling the bowl and he's standing beside me saying the ants are probably from outside. Yes Dad that's where ants start. We had this exact argument last summer. I want him to just admit it's because Mum always filled it, but if he says that I'll have to stop being annoyed and I don't feel ready to.","starter_sentence":"A family keeps doing something unnecessary.","word_count":90,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T01:43:46Z"},{"id":"abbb2e39-cd6c-5dc6-ac0f-db789dbbd825","source_key":"sample-story-abbb2e39-cd6c-5dc6-ac0f-db789dbbd825","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Last message sent","content":"Don't open the second one.\nThat was the first message. The second was an image, still downloading. I turned off wifi but the mobile data carried on. Turned that off too. The thumbnail stayed grey. The sender was my old number, from before I lost the phone in the river. I tried calling it. My phone rang in my hand while I was already making the call. That's impossible but I could see both screens, the outgoing call underneath and the incoming one on top. I pressed answer. No voice. Just water very close to the microphone and somebody breathing through their nose. The image finished downloading even though everything was off. I put the phone face down before it appeared. Then spent the next ten minutes wanting to look.","starter_sentence":"A message arrives after its sender is gone.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T03:49:49Z"},{"id":"1a7c14d8-b8f2-5c19-af10-cc3498ab55b5","source_key":"sample-story-1a7c14d8-b8f2-5c19-af10-cc3498ab55b5","author_id":"d772033e-9ecd-55e8-b8a4-0d8d7e4a3d1f","title":"apology, attempt 2","content":"Dear Helen, I am sorry about the incident at your birthday. I did not know the man was your husband. I had imagined you would introduce him at some point, but obviously you were busy. That sounded pointed. I am also sorry about the plate although I maintain it was an unsuitable surface for a candle. I will replace both. The plate and candle. Not your husband.","starter_sentence":"Write an apology that reveals more than intended.","word_count":67,"time_mode":2,"mode":"custom","is_hardcore":true,"created_at":"2026-10-16T04:22:23Z"},{"id":"1db19c33-ea39-5c31-8698-9dafb740d8ad","source_key":"sample-story-1db19c33-ea39-5c31-8698-9dafb740d8ad","author_id":"0eee6119-4ebe-5cbb-be80-29f2830b3732","title":"Wrong attachment","content":"i sent the wrong attachment. not my cv, a photo of the hole behind my washing machine. they have invited me for an interview. i keep opening the email expecting it to make sense but it says impressive depth of experience. maybe its a joke maybe somebody is also sitting at work dying quietly and liked my hole. i am going. ive printed the hole in case they ask","starter_sentence":"An ordinary work mistake has strange consequences.","word_count":69,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T04:56:33Z"},{"id":"b54554d1-e25b-5d6b-b8a0-b320e1ec738e","source_key":"sample-story-b54554d1-e25b-5d6b-b8a0-b320e1ec738e","author_id":"12acbbd4-947f-504f-ade2-c7f7bdf59d05","title":"frost inside","content":"Frost on the inside of the wardrobe. She scraped it with a credit card. Underneath was a field, not a picture, her finger went into it and came back wet. There were cows a long way off. She called her sister but couldn't explain so she just kept saying come over, please come over.","starter_sentence":"A season arrives in the wrong place.","word_count":54,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T05:26:18Z"},{"id":"092339e5-050b-514f-b772-4fadf9eef2b9","source_key":"sample-story-092339e5-050b-514f-b772-4fadf9eef2b9","author_id":"a4fe032c-ebcc-5b12-99b8-2cdf9a0bdd0f","title":"spoon count","content":"We started with twelve spoons. There are three. I have counted them twice because apparently I'm the spoon man now. Fine. Where are the other nine. Nobody knows. Someone suggested buying more. BUY MORE so the spoon hole can eat those too? We need to understand the process before we add inventory. I am not being unreasonable I am being systmatic.","starter_sentence":"Write an unreasonable complaint.","word_count":61,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T08:04:45Z"},{"id":"35e84476-2ba7-56ba-ab18-2919a4401801","source_key":"sample-story-35e84476-2ba7-56ba-ab18-2919a4401801","author_id":"1bd72f15-96d8-5538-ba67-5a265af316fc","title":"tomatoes attempt","content":"Need to tie the tomatoes up. They are lying all over each other. I had a story about someone hiding in the greenhouse but now all I can think is I should actually go and tie them up before it rains. Got string somewhere. Blue string.","starter_sentence":"Describe a task you have put off.","word_count":46,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T08:16:47Z"},{"id":"c951a6f9-1df6-523c-ad35-6d7abb9170c3","source_key":"sample-story-c951a6f9-1df6-523c-ad35-6d7abb9170c3","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"34 or 35","content":"We didn't know his birthday because the calendar reset during the jump. Made a cereal cake anyway. Used the red emergency lamp for a candle. He stared at it and said thirty four, not thirty five. Nobody had said an age. The cake started sagging round the battery compartment. I'd got the lamp from damaged stores. Reached for it. He caught my wrist hard.","starter_sentence":"Celebrate with limited materials.","word_count":64,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T08:23:36Z"},{"id":"81174f1b-b3ec-5c17-aa0f-a95e9f3c2952","source_key":"sample-story-81174f1b-b3ec-5c17-aa0f-a95e9f3c2952","author_id":"8ced546b-f7d9-5612-aee8-99f48198680b","title":"Things to take","content":"toothbrush\ncharger\nthe book she lent me, even though I didn't read it\na better reason for not reading it\nclean socks\nnot the jumper she bought me because that will look deliberate\nmaybe the jumper actually\nI haven't put anything in the bag yet. Been sitting on the bed making this list. Train's at six. If I miss it there's another one, which is part of the problem.","starter_sentence":"Pack for a visit you do not want to make.","word_count":69,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T08:24:50Z"},{"id":"c1577717-825d-57c6-bd54-f2a3e8dc69c0","source_key":"sample-story-c1577717-825d-57c6-bd54-f2a3e8dc69c0","author_id":"ebf854eb-8d59-5998-90db-11437b26b416","title":"Take the left","content":"'Left.' 'You said right.' 'I meant the bag. Left bag.' He had the wrong one and the security man was coming back. I put mine down. He didn't. It was full of somebody's swimming things, I could see a pink towel through the zip. Completely useless. We were trying to steal our own coats back from the club because they wanted another fiver. We should have paid the fiver. The security man looked at the towel and then at us. 'Nice swim?' he said.","starter_sentence":"Two people try to get away with something.","word_count":84,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T09:01:24Z"},{"id":"8860a792-98f3-5e31-8e53-af1da686cc88","source_key":"sample-story-8860a792-98f3-5e31-8e53-af1da686cc88","author_id":"316eed8d-f125-5a1b-8346-6d608fb46e5c","title":"what the wolf said","content":"There is a wolf but he doesnt want to eat anybody. He wants to find his mum. I think wolves leave their mums though. Maybe he is still little. He finds the red cloak caught on a branch and smells soap which he has never smelled before","starter_sentence":"Begin a fairy tale and run into a problem.","word_count":47,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T10:19:29Z"},{"id":"b2ab9d5f-d553-5f13-850b-77594a05ac29","source_key":"sample-story-b2ab9d5f-d553-5f13-850b-77594a05ac29","author_id":"0a18ac6f-c3a2-5f6d-b52d-8431aeb8c011","title":"Cake for breakfast","content":"The icing had gone hard and the cake underneath was still wet. I don't understand how that happens. We cut around the part where someone had put out a cigarette. Dad said he hadn't done it, which nobody had asked. My sister was asleep on the sofa in her shoes. One of her earrings was stuck to the cushion. I tried pulling it free and she woke up swinging at me, not properly awake, just one arm. I ducked and the cake fell icing down on the carpet. Dad started laughing, a real ugly laugh with no breath in it. I sat on the floor and laughed too because I was too tired to do anything else. The dog came over and Dad caught him by the collar. Nobody was getting breakfast apparently. We still had all the chairs to take back before twelve.","starter_sentence":"Eat something after the occasion has ended.","word_count":144,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T11:50:51Z"},{"id":"7147bea3-8d96-5ae2-9daf-be47316fc274","source_key":"sample-story-7147bea3-8d96-5ae2-9daf-be47316fc274","author_id":"55f79dc6-f9c9-5a93-b44d-1f4ca2d44981","title":"extinction test","content":"The sample says a word. We replay it nine times, clean the filter, try another headset. Same word. Not English. It sounds like 'allow' until you listen to it thinking 'below' and then it sounds like that. Hesh wants to publish. I want to know why the waveform is exactly the outline of the hill outside. He says I am seeing patterns. I ask him to look out the window. The hill wasn't there yesterday.","starter_sentence":"A machine begins making a sound nobody taught it.","word_count":75,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T12:47:07Z"},{"id":"11ab7bcb-2f10-592e-8a2d-adc6fae73f5c","source_key":"sample-story-11ab7bcb-2f10-592e-8a2d-adc6fae73f5c","author_id":"a9271dd2-ef3e-5ab5-9bda-6cac641e37a7","title":"silver","content":"silver sounds like a spoon dropped down the back of a radiator. a long ringing clatter getting thinner. maybe that's just because spoons are silver. i'm bad at this one.","starter_sentence":"Describe a colour through a sound.","word_count":30,"time_mode":1,"mode":"custom","is_hardcore":true,"created_at":"2026-10-16T13:05:09Z"},{"id":"c8a1973d-3903-5d59-a670-873c2c4810c5","source_key":"sample-story-c8a1973d-3903-5d59-a670-873c2c4810c5","author_id":"c4ddf376-4b92-5716-a61f-6e79b3d388a6","title":"the spare room","content":"He left the window open and a wet towel on the bed. I started saying his name before remembering he'd gone. Shut the window. Picked up the towel. Found his charger plugged in behind the chair. He'll be back for that by tonight.","starter_sentence":"Describe a room someone has just left.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T13:33:53Z"},{"id":"dfb384c5-a541-52d1-993b-1eed64352c7f","source_key":"sample-story-dfb384c5-a541-52d1-993b-1eed64352c7f","author_id":"4e915f8d-f5e6-5536-bb28-03e5dde5616d","title":"Two minutes","content":"He tried the handle. She put her foot against the door. He pushed harder. The chair slid backwards across the carpet. She reached behind her for the phone and knocked it off the table. It rang once on the floor. He stopped pushing.","starter_sentence":"Write a suspense scene using only physical actions.","word_count":43,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T13:45:13Z"},{"id":"6370dac0-00bd-5357-aea8-5db0a0438263","source_key":"sample-story-6370dac0-00bd-5357-aea8-5db0a0438263","author_id":"7889cb6b-b2b4-599b-b86e-5519eb0a5b9a","title":"fitting room 2","content":"The zipper wouldnt go up. She said sorry to the girl helping her, sorry to her sister, almost sorry to the dress itself. Her sister said breathe in. She was already breathing in. She had been breathing in since she left the house. A pin scratched the soft part under her arm and suddenly she was angry. Not beautifully angry. Hot and red and a bit wet around the eyes. She said take it off. The girl said there was another size and she said no take it OFF. Her sister went quiet. Once she was back in her own t shirt she could think again. She wanted the blue suit she'd seen downstairs. She had wanted it all morning but everyone kept bringing dresses.","starter_sentence":"A person finally says what they want.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T13:56:25Z"},{"id":"62fa7063-ba64-50ae-bf00-ead8c590d090","source_key":"sample-story-62fa7063-ba64-50ae-bf00-ead8c590d090","author_id":"5442276c-3dd5-5cd2-a1f8-7cba3bed043c","title":"inventory","content":"I count the chairs when I can't sleep. Six downstairs, one on the landing, two in the spare room. Nine. Tonight ten. I start again because being tired makes you stupid. Still ten. The extra one is in my bedroom, beside the bed. It looks like the others. Same wood, same worn place on the seat. I don't remember carrying it in. I stand in the doorway for a long time. Then I move it out onto the landing and close the door. I don't count again.","starter_sentence":"One thing in a room is out of place.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T14:52:20Z"},{"id":"d6de2aa5-782d-53ca-b0c2-f472d27b2bf1","source_key":"sample-story-d6de2aa5-782d-53ca-b0c2-f472d27b2bf1","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Photo booth","content":"first picture i sneezed. second picture she laughed at me sneezing. third picture we were both ready but the flash didnt go. fourth picture there wasnt supposed to be a fourth picture. we looked at each other and it flashed again. the machine started pritning and kept printing, a long strip winding onto the floor. us getting older, not dramatic old just different hair, her wearing glasses, me with a mark on my cheek. in one we werent looking at each other. i stepped out and the printing stopped. she stayed sitting there looking at the strip and i couldnt tell if she wanted to see more. i said probably some filter thing. she said yeah. neither of us picked it up. i went back for it later but the booth was being used by two kids in school uniforms and i didnt want to ask.","starter_sentence":"Try to take a photograph together.","word_count":146,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T15:45:50Z"},{"id":"04f0ed25-d4ae-5b3c-9222-35fd7f02083f","source_key":"sample-story-04f0ed25-d4ae-5b3c-9222-35fd7f02083f","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"Four thirteen","content":"One blackbird, then another, then a car alarm. The blackbirds kept going through it. I couldn't decide whether they were competing or just couldn't stop once they'd started. I lay there trying to hear which one ran out of notes first.","starter_sentence":"A sound wakes you earlier than planned.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T15:56:00Z"},{"id":"9b97aee6-f7d3-5e4d-bddd-3c1a986ab264","source_key":"sample-story-9b97aee6-f7d3-5e4d-bddd-3c1a986ab264","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Hoard inventory","content":"Sleeping on gold hurt his hips. Silver worse. Copper rash. Now the dragon slept beside the hoard pretending not to. Knight came in, started sorting coins by year. Dragon watched. Finally someone organising them. Waited an hour then coughed. Knight screamed and dropped everything together again. Dragon wanted to explain but the knight had started stabbing at his foot. Annoying rather than painful. He sat on him to make him stop. Hadn't thought past that.","starter_sentence":"A dragon has a practical problem.","word_count":75,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T18:52:04Z"},{"id":"0d1772a1-4b5f-5c6f-92df-fea6b91705fe","source_key":"sample-story-0d1772a1-4b5f-5c6f-92df-fea6b91705fe","author_id":"b3fefc5a-1a65-5557-b0ee-e583a5fc7018","title":"Manual override","content":"Pressure gauge stuck on zero. Can't be zero, the pipe is shaking. Vic tells the kid to shut the valve. Wheel turns but the shaft doesn't. Stripped coupling. He reaches for pliers and the pipe jumps, knocks his mug off the bench. Hot water everywhere. He says leave it. The kid reaches for the mug. No, leave the BUILDING. Vic shoves him through the door. Outside people are coming down the road to see what the noise is. He waves them back.","starter_sentence":"Two people must repair a dangerous system together.","word_count":82,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T21:07:51Z"},{"id":"f9ed405b-360d-53fe-ae9e-5f0d4b81ec96","source_key":"sample-story-f9ed405b-360d-53fe-ae9e-5f0d4b81ec96","author_id":"f893286e-1170-5ece-a0a8-d22ce41dccb6","title":"No view","content":"Couldn't see anything. Took a photo of the mountain diagram on the sign instead. A woman came up with a dog inside her coat. Said she'd parked round the back. Apparently there's a road. I'd walked three hours. She pointed into the cloud when I asked where it was. Didn't fancy following a stranger into that so went down my own way. Dog sneezed on her chin as I left.","starter_sentence":"Reach a viewpoint on the wrong day.","word_count":70,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-16T22:19:04Z"},{"id":"827800bb-c860-537d-a191-0520530b22ad","source_key":"sample-story-827800bb-c860-537d-a191-0520530b22ad","author_id":"0b4f9787-dc5c-5e47-ba2a-09ff695b34ac","title":"spare key","content":"I posted the key through. Then remembered my own front door key was on the same ring. Stood there saying oh no very quietly for about a minute. She was home. I could see her car. Had to knock after all.","starter_sentence":"Return something after a friendship changes.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":true,"created_at":"2026-10-17T01:13:51Z"},{"id":"6601c5c5-527b-54d7-a86c-57d4b8532a8c","source_key":"sample-story-6601c5c5-527b-54d7-a86c-57d4b8532a8c","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Minor archive","content":"The machine remembered the exact number of steps between my old bed and the bathroom. Eleven if the cupboard was shut. Thirteen if I went round it. I asked why it had kept that and deleted my university password. It said relevance was calculated differently now. Differently to what? No answer. I asked it to delete the steps. It asked if I was sure. Yes. It asked again. I got annoyed and confirmed with the password I could remember. That night I walked into the cupboard door in the dark. Different house, different cupboard. Same distance. I'm not sure whether this is a story about memory or just me not switching a light on.","starter_sentence":"A machine remembers an unimportant detail.","word_count":114,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T01:18:15Z"},{"id":"5fcf9c71-e073-5cc4-86ab-c76c40643382","source_key":"sample-story-5fcf9c71-e073-5cc4-86ab-c76c40643382","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"wrong building","content":"i followed the singing up a flight because it sounded like our old school song. not the words, the horrible tune they made us do every monday. there was a door open and maybe thirty people standing very still while a woman in gym clothes counted down from eight. i thought aerobics but there was no music. then they all shouted the same word and slapped their faces. i should've left. i stood there with a delivery bag from a place i didnt even work at anymore and watched them start again. one man saw me and mouthed don't. don't what. the lift doors opened behind me and i stepped into them without turning round and pressed the button for the ground floor about ten times.","starter_sentence":"Hear a familiar sound in an unfamiliar place.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T01:34:37Z"},{"id":"1855fe0b-7852-5200-80e9-5da10c66d6d1","source_key":"sample-story-1855fe0b-7852-5200-80e9-5da10c66d6d1","author_id":"f2502b5f-8e30-5eb2-b7e5-117969a80d10","title":"waiting room","content":"time stopped at my waist so my legs are in yesterday. i can lean really far forward but not stand up. dont know if im hungry now or yesterday hungry. nurse says please stay seated. way ahead of you","starter_sentence":"Time stops, but only for part of a room.","word_count":39,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T02:47:41Z"},{"id":"e9c30562-d048-561d-af38-ec9f0c15152f","source_key":"sample-story-e9c30562-d048-561d-af38-ec9f0c15152f","author_id":"e14f7eb4-fd33-5626-930b-36d455de8584","title":"homework","content":"I wrote that whales were fish and cried when it got marked wrong because my dad told me. I thought the teacher was calling him stupid. I didn't say that, I just cried which made the other kids laugh. Wish I had said it now. Not to win, just so she knew why I was making such a fuss over a whale.","starter_sentence":"Remember something you got wrong at school.","word_count":62,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T02:59:43Z"},{"id":"119d71d0-d72c-5311-b36e-9a808ea4e992","source_key":"sample-story-119d71d0-d72c-5311-b36e-9a808ea4e992","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Counting cans","content":"Twelve in a case. Six cases on a shelf. Four shelves. I kept getting a different number because I'd start counting individual cans halfway through. There was one open case and that ruined everything. I took it off the shelf. Now there were five cases and a gap and I couldn't remember if I'd counted the gap. I know multiplication. I passed maths. At four in the morning it had become a trick someone was playing on me. I wrote the number from last week and put a question mark beside it. Then crossed out the question mark because it looked worse. The supervisor would probably count them again anyway. I sat on the floor for a minute before doing the bottles.","starter_sentence":"A repetitive task becomes difficult.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T03:07:16Z"},{"id":"3561c4cd-6078-5a8b-9588-315de5aba0fe","source_key":"sample-story-3561c4cd-6078-5a8b-9588-315de5aba0fe","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"After the call","content":"i put the kettle on and forgot to put water in. it clicked off straight away. filled it. put it on again. there was a spoon in my hand and i don't remember getting it. that's all i can get down at the moment.","starter_sentence":"An ordinary action after important news.","word_count":44,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T05:16:50Z"},{"id":"f0e93895-38e1-573a-b1cb-be86f4087dab","source_key":"sample-story-f0e93895-38e1-573a-b1cb-be86f4087dab","author_id":"a63b3511-769e-54e5-9253-ce29cd08d1b7","title":"the bells started early","content":"At the first corner the street has a different name. I keep going because names change. At the second corner the road drops steeply towards water that wasn't there this morning. I can see my office on the far side, fourth-floor window still open, my cardigan on the chair. There are people down on the bank holding their phones above their heads. None of them are looking at the water, they're trying to get a signal. I try mine too. It says I'm seven kilometres away from where I am. Behind me the bells start again and this time the buildings on my left lean, very slowly, as if somebody is pulling the street from underneath them.","starter_sentence":"A familiar city changes while you are walking through it.","word_count":117,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T05:27:02Z"},{"id":"a74463c2-6f0f-5b6d-aad9-817e294fb023","source_key":"sample-story-a74463c2-6f0f-5b6d-aad9-817e294fb023","author_id":"8ced546b-f7d9-5612-aee8-99f48198680b","title":"before you leave","content":"Lock the back door. Check the cat is inside. If the cat is outside let him in then lock the door again. If he goes out while you're locking it start over. This is why we never leave on time.","starter_sentence":"Write instructions nobody will follow exactly.","word_count":40,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T09:08:34Z"},{"id":"411ce108-5b9a-5369-adbd-213e029aa443","source_key":"sample-story-411ce108-5b9a-5369-adbd-213e029aa443","author_id":"bb3ba0d1-ec13-5513-a3de-1fd2c86131c8","title":"just walking","content":"sometimes I walk till my feet hurt so I can blame being in a bad mood on that. which is backwards I know. yesterday went past the mosque and the car wash and all the way to the big roundabout. there was a shoe on the central bit. one little glittery girls shoe. How. anyway I kept going, shouldn't have becuase the road stops having pavement and then you're just a person next to lorries. had to climb a fence to get off it. tore my trousers not even in a cool place right on the back. Got home and mum said you've been out ages did you get milk. I had specifically gone out for milk. So went back out. actually that part was fine.","starter_sentence":"Write a freewrite about something you do when you are restless.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T10:41:22Z"},{"id":"de898e92-0033-527e-b39a-89fd1e55816b","source_key":"sample-story-de898e92-0033-527e-b39a-89fd1e55816b","author_id":"049b6e2b-ab51-5bea-93ea-bd5edee32b3d","title":"Friday money","content":"'You said Friday.' 'It is Friday.' 'It's nearly midnight.' He starts looking through his pockets. I tell him stop doing that, I know he hasn't got it. He asks if I want his phone. I don't want his phone. The thing has a crack across the face and it's all his daughter has to call him on. 'How much have you got?' 'Nine.' 'Nine pounds?' 'Yes.' I owe sixty to someone who won't take nine. I sit on the step. He sits beside me. Neither of us says anything for a while. Then he asks if I want a cigarette and I say yes even though I quit.","starter_sentence":"A conversation about a debt.","word_count":108,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T13:21:43Z"},{"id":"54ee8c69-a02b-5cf8-8402-cc628f150f62","source_key":"sample-story-54ee8c69-a02b-5cf8-8402-cc628f150f62","author_id":"ae8577b0-b86b-57de-b55c-da9bb0393055","title":"saturday maybe","content":"said yes to saturday because saying maybe makes people stop asking. now it's friday and i still dont want to go. i like them i just dont want to stand in a loud room pretending i can hear. could suggest somewhere else but that makes me responisble for everyone having fun. maybe i'll go for an hour. i always say an hour and then miss the last bus. need to find my good shoes first. one is under the bed and the other is apparently living independantly","starter_sentence":"Make a plan you are unsure about.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T13:21:50Z"},{"id":"bff18a20-1178-5dd5-8380-2b22f634b91d","source_key":"sample-story-bff18a20-1178-5dd5-8380-2b22f634b91d","author_id":"c4ddf376-4b92-5716-a61f-6e79b3d388a6","title":"laundry in the rain","content":"I was halfway through taking it in when the little boy came through the hedge. Not round the gate, straight through with leaves stuck in his hair. He said his mum was on the floor. I dropped the basket and went with him. She was sitting against the fridge, conscious, holding her wrist. Fell off a chair changing a bulb. She kept saying don't call anyone because she didn't want a fuss. I called anyway. The boy stood beside me holding one of my socks. He must have picked it up when I dropped the basket. While we waited he asked if she was going to die. I said no too quickly and his mum started laughing then crying and I put the kettle on because I didnt know what else to do with my hands.","starter_sentence":"An ordinary chore is interrupted.","word_count":136,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T13:54:14Z"},{"id":"78439745-468a-5c40-ae74-4f2e5ba7522a","source_key":"sample-story-78439745-468a-5c40-ae74-4f2e5ba7522a","author_id":"5442276c-3dd5-5cd2-a1f8-7cba3bed043c","title":"by the gate","content":"There's a woman at the gate with a suitcase. She says she's come for the room. I don't rent a room. She shows me the advert on her phone: my house, my garden, a photograph of the kitchen taken from inside. It says available immediately. I tell her to wait and go back in to get my glasses, which is such a stupid thing to do. I can read it perfectly well. I just want a minute without her watching my face.","starter_sentence":"An unexpected visitor waits outside.","word_count":82,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T14:10:16Z"},{"id":"cfc7fe89-baf8-591b-b298-c3e80aa4cb45","source_key":"sample-story-cfc7fe89-baf8-591b-b298-c3e80aa4cb45","author_id":"962b0e29-2853-57c0-8a18-f6bc877d58d8","title":"practice run","content":"Missed the jump, hit the water, lost a shoe. Did get the flag though. Coach said that didn't count because I'd touched the bottom. I said the bottom was full of eels and therefore should count double. He was writing something on his clipboard. Probably my name under never again. The flag was bleeding on my hand. I'd grabbed the wrong thing. It unfolded a little and looked at me and I decided to keep that part to myself.","starter_sentence":"A small success after a bad start.","word_count":79,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T14:28:21Z"},{"id":"6edf5d16-8f19-5b25-a12a-1423621eeaa6","source_key":"sample-story-6edf5d16-8f19-5b25-a12a-1423621eeaa6","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Short cut spell","content":"I asked for the shortest way home. It made me shorter. Fine, badly phrased, my fault. Asked for the fastest route. Now I'm a very fast short person. The wizard said I had one wish left which was new infomation because he hadn't mentioned wishes at all, we'd been discussing spells and I had paid for a spell. I asked for my money back. Coins burst out my ears. Painful but at least I was rich for a minute until the wizard said service charge and swept half of them off the floor. I kicked his shin. Being short made the angle better. He kicked back and missed and I ran under the counter. There was a whole row of tiny shoes under there. So this was not the first time. I started shouting for the other customers to get out but the words came out as little paper birds and now I had that problem too.","starter_sentence":"Magic solves the wrong problem.","word_count":157,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T15:24:55Z"},{"id":"e2fbd58c-3d3b-50d1-a599-93fd4859ff27","source_key":"sample-story-e2fbd58c-3d3b-50d1-a599-93fd4859ff27","author_id":"1bd72f15-96d8-5538-ba67-5a265af316fc","title":"stop watering it","content":"Please stop watering it every time you visit. Three of us keep watering the same plant and its basically living in a puddle. I put a note on it and Dad watered the note. Not on purpose. He thought the soil looked dry at the top. It IS dry at the top because there's an inch of decorative stones on top. Under that its soup. I've taken it out of the pot now and put newspaper round the roots. The kitchen looks like a very small crime scene but I think it might live.","starter_sentence":"Give practical advice you wish someone would follow.","word_count":94,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T15:46:39Z"},{"id":"6ba9a063-e871-5df6-a378-1557c7493eea","source_key":"sample-story-6ba9a063-e871-5df6-a378-1557c7493eea","author_id":"76ddfafa-74ee-5075-8521-1c0f3727a98c","title":"compulsory fun","content":"I don't think work has to be a family. I have a family and some of them are difficult enough without adding the man who checks my timesheet. We had to write one personal goal on a board today and mine was get home on time. The facilitator said think bigger. I said get home on time every day. She left it there but put a star by someone else's goal to run a marathon. Good for him. I would like to see my children while they are awake. That seems quite a big thing to me. I didn't say that last part in the room, of course. I wrote it here instead and I am still annoyed about the star.","starter_sentence":"Write an opinion you have difficulty saying aloud.","word_count":121,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T16:23:37Z"},{"id":"b2cc9028-1bab-564a-b899-aea712068e7f","source_key":"sample-story-b2cc9028-1bab-564a-b899-aea712068e7f","author_id":"3b0adbd3-6e83-579b-a6df-411cae5657a7","title":"uniform","content":"The androids had designed my uniform without consulting me. No zip. They could remove their heads to get through the collar and assumed I was being difficult when I wouldn't. One offered a spanner. I explained skin, again. We were already late for inspection and I was still in my pants. The captain said perhaps we should cut the uniform. Everyone looked horrified, including the one holding the spanner. Damaging company property was aparently much worse than briefly removing the human's head. I went to inspection in my old shirt.","starter_sentence":"She was the only human in a crew of androids. They were more afraid of her than she was of them.","word_count":90,"time_mode":3,"mode":"regular","is_hardcore":false,"created_at":"2026-10-17T18:33:24Z"},{"id":"fca6e7f7-87be-5afb-9960-81ffae691378","source_key":"sample-story-fca6e7f7-87be-5afb-9960-81ffae691378","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Rectangle","content":"Behind the cupboard the wall was yellow. Everything else had gone white over the years. A rectangle of the room as it used to be, though she couldn't remember choosing yellow. It was such an ugly yellow. Almost mustard but sickly.","starter_sentence":"A house remembers where something stood.","word_count":41,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T18:50:17Z"},{"id":"e1b80274-7136-5d89-9bd7-811059af2e28","source_key":"sample-story-e1b80274-7136-5d89-9bd7-811059af2e28","author_id":"ac86ddd1-16f1-55c5-9200-a2b63e3f1406","title":"Names on equipment","content":"\"Don't call it Alan.\"\n\"Why?\"\n\"Alan still works here.\"\n\"Different Alan.\"\nThe robot rolled between us carrying the waste bin. Somebody had stuck a paper tie under its camera. I pulled it off before it caught in the lift mechanism. The actual Alan came through the loading door with his lunch and saw me holding it. He thought it was for him. I said no. He asked why there were two Alans on the shift sheet. We hadn't changed the sheet, the scheduling system had taken the name from the machine's label. Now it had booked the human Alan for six hours charging overnight and the robot for his medical appointment. It sounds funny written down. It wasn't funny explaining the missed appointment fee.","starter_sentence":"Someone gives a machine a name.","word_count":124,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T19:16:50Z"},{"id":"d56ef185-d943-5523-855e-b6f49664cfd2","source_key":"sample-story-d56ef185-d943-5523-855e-b6f49664cfd2","author_id":"80f3afbe-1c13-566d-99b9-78aa62b4d926","title":"sleeve","content":"Getting his arm through the sleeve should take ten seconds. It takes ten minutes because his thumb gets stuck and then he decides the jumper is hurting him. It's the same jumper as yesterday. I say that as if it helps. He cries. I say fine, no jumper, and he cries because he wants it. We sit on the floor. I put my own arm through the sleeve to show him. Can't get it out. He stops crying to watch me struggle.","starter_sentence":"Help someone do something small.","word_count":82,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-17T20:37:39Z"},{"id":"149a84c6-38f3-59d1-9cbf-4eda8b34dd45","source_key":"sample-story-149a84c6-38f3-59d1-9cbf-4eda8b34dd45","author_id":"3708a4a7-a14c-5d49-818b-1daf72b5457a","title":"Cupboard space","content":"I wanted this one to be about a person hiding in a cupboard but the problem is you would hear them. Breathing at least, or the hangers. Unless they took all the clothes out first. So she opens it and there's no clothes, just the rail, and that's the thing she notices before the person. Her blue dress is gone. She thinks about the dress because she hasn't worn it yet and still owes her sister for half of it. The person is crouched right at the back with their face turned away. She says that's mine, meaning the dress, which they aren't wearing. Then she says it again because nothing else comes into her head. They shift one knee. I can't decide if she recognises the shoe. Maybe no shoes. The cupboard is too shallow for anybody to be crouching that far back.","starter_sentence":"A small space feels occupied.","word_count":144,"time_mode":3,"mode":"custom","is_hardcore":true,"created_at":"2026-10-17T21:38:30Z"},{"id":"fbd67a88-737b-53a1-ae85-6dba0d9104d9","source_key":"sample-story-fbd67a88-737b-53a1-ae85-6dba0d9104d9","author_id":"9131d45d-57c0-5448-b726-4004cd145656","title":"Arrival window","content":"They arrived folded. Like letters, except the folds kept changing until there was enough space for them to stand. We had built a landing pad and all the cameras were pointed at it, but they came through the space between two teeth in the mayor's mouth. He was in the middle of the welcome speech. There was a little crack, he spat something silver into his hand and it unfolded into three people and a table. Nobody clapped. The visitors put the table down and waited. We waited. After a while one of them pointed to the mayor's mouth and held up two fingers. Two more coming, apparently. He refused. Can't blame him. We offered other mouths, a dog, a mannequin from the clothes shop. They seemed offended by the mannequin, or frightened, hard to tell because their faces were moving in the wrong directions. The smallest visitor climbed onto the table and unfolded again, taller this time, with a hole through the middle. Through the hole we could see another table and somebody setting plates out. They weren't invading. Maybe they were late for dinner and our world was a corridor. I stepped closer to see what was on the plates. The visitor put a hand on my chest and pushed, gently but with no possibility of arguing, and I went back three steps without moving my feet.","starter_sentence":"Visitors arrive from somewhere unexpected.","word_count":229,"time_mode":5,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T00:23:01Z"},{"id":"4f1b69ed-93a0-5bc6-8445-77a19b6645a6","source_key":"sample-story-4f1b69ed-93a0-5bc6-8445-77a19b6645a6","author_id":"1b33ff94-27a9-5059-a75a-a986267c3f64","title":"Saturday staff","content":"The manager came in wearing a suit on Saturday. He never worked Saturdays. He went into the back room and asked us to come in one at a time. I was third. While I waited I tidied the discount table even though it was already tidy. The first person came out and went straight to her locker. The second came out and started serving somebody. Both seemed normal. When it was my turn the manager asked me to shut the door. He had a list with my name on it. My name was spelled wrong. I pointed that out, which was probably not the first thing I should have said. He crossed it out and wrote it again, still wrong, and I sat down without correcting him.","starter_sentence":"An ordinary day feels different.","word_count":127,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T00:42:50Z"},{"id":"cbf28c98-57c8-527e-8171-478493f12c4d","source_key":"sample-story-cbf28c98-57c8-527e-8171-478493f12c4d","author_id":"42a39474-a97d-5621-9ca1-bed942fe3d5c","title":"free evening","content":"got ready and then she cancelled. fine, i wanted to stay home, except now i was in the jeans that hurt sitting down. went to the supermarket in them. bought olives like a person having a nice evening. i dont even like olives. ate the bread standing up then went to bed. not much of a story really.","starter_sentence":"A cancelled plan brings mixed feelings.","word_count":58,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T00:52:41Z"},{"id":"2a5fa1af-2d68-55a5-848e-d17744296921","source_key":"sample-story-2a5fa1af-2d68-55a5-848e-d17744296921","author_id":"905139a1-f2b4-52f1-a150-8d84fc4e9bae","title":"Instructions for the fern","content":"She left seven pages for the fern and one line for the cat. The cat line was feed twice daily. The fern had humidity preferences, window preferences, apparently opinions about tap water. Day two the fern went brown at the ends. I trimmed those off. Day three more brown. Trimmed those too. By day six it was very small. I googled can a fern notice haircut, which is not my proudest search. The cat was fine. The cat had eaten half a receipt and slept in the salad bowl but seemed happy. I sent her a picture of him and cropped out the plant. She replied how's my fern. I typed thriving and deleted it. Typed a lot of new growth and deleted that because if she asked to see it I'd have to buy a whole second fern.","starter_sentence":"Agree to look after something unfamiliar.","word_count":139,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T05:44:05Z"},{"id":"a0a377ee-f691-541f-982d-ed97aed2bb65","source_key":"sample-story-a0a377ee-f691-541f-982d-ed97aed2bb65","author_id":"1a366120-4720-5422-a73a-bca978cb539e","title":"Hold this","content":"I told her to hold the torch on the bolt. She held it on my face. I said the bolt again, louder, and she went quiet. The torch settled where it was supposed to be. I couldn't get the spanner onto it because my hand was shaking. She asked if she should try. I wanted to say no but I'd already said no about the shopping and the stairs and it was getting ridiculous. I passed it over handle first.","starter_sentence":"Let someone else do a task.","word_count":80,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T06:27:21Z"},{"id":"7984a21c-c9d7-59d4-bd95-00320b5cde01","source_key":"sample-story-7984a21c-c9d7-59d4-bd95-00320b5cde01","author_id":"0eee6119-4ebe-5cbb-be80-29f2830b3732","title":"flood plan","content":"water is coming through the lifts and mark says we should stay prodcutive until theres an official email. i ask if i can take my shoes off and he says lets keep things professional. he is wearing wellies. where did he GET wellies. i start carrying the computers upstairs because at least thats doing something and the new guy helps me except he unplugs the server and everything goes dark. now mark is shouting about backups and im holding this huge warm computer against my chest in brown water up to my thighs and and i think i hear a boat outside. not traffic. an actual engine revving close to the window and theres someone knocking from the other side of the glass. were on the fourth floor, i know that because i climbed all of them this morning the lifts were already","starter_sentence":"A workplace carries on during an emergency.","word_count":143,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T06:37:20Z"},{"id":"13f876b0-891a-5188-90cc-14f9dfc0da13","source_key":"sample-story-13f876b0-891a-5188-90cc-14f9dfc0da13","author_id":"ed95f9f4-57c6-5a55-8be0-7d54206b565d","title":"August, no rain","content":"The bees stop at the same place in the air. Not all together, one after another, as though each has reached a small invisible pane of glass. By noon there are twenty hovering over the dry pond. I put my hand through. Nothing. The wings are still working, making a sound so high it almost isn't a sound. I bring the hose but the water runs sideways at that spot and wets my shoes. I wish Daniel was here because he would try something sensible before being frightened. I have turned off the tap and the water is still coming.","starter_sentence":"Imagine that one ordinary natural process stops.","word_count":100,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T06:58:49Z"},{"id":"f7004842-713f-5cf2-b6b5-dd4ebda26a23","source_key":"sample-story-f7004842-713f-5cf2-b6b5-dd4ebda26a23","author_id":"a4fe032c-ebcc-5b12-99b8-2cdf9a0bdd0f","title":"cake","content":"Volunteered to make a cake. Thought that meant make a cake. It means make a nut free dairy free gluten free object for fourteen people, two of whom don't like sweet things. One of them suggested fruit. Then bring fruit Sandra. Bring a melon and put a candle in it. I've got flour all over the floor and the first cake is still liquid in the middle. The second cake doesn't exist yet. I should've volunteered to bring napkins. Nobody has a complicated personal relationship with napkins.","starter_sentence":"You regret volunteering.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T08:32:49Z"},{"id":"60d928c1-a393-5d28-9bb8-0876e63bbde7","source_key":"sample-story-60d928c1-a393-5d28-9bb8-0876e63bbde7","author_id":"d772033e-9ecd-55e8-b8a4-0d8d7e4a3d1f","title":"at the door","content":"The woman insisted I come in. I needed a ladder; my son was stuck in her tree. She asked if I'd had lunch. I invented a sandwich because a handful of peanuts wouldn't count. She asked whether I took sugar. I said I needed a ladder, loudly, and she looked hurt. There was a walking frame by the fridge. She put both hands on the counter to turn and I understood she couldn't fetch me anything. She had been trying to make me stay long enough to fetch it myself. I asked where the cups were. Outside my son called that he could see the motorway.","starter_sentence":"Write a scene in which courtesy prevents something urgent.","word_count":106,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T08:36:02Z"},{"id":"b869fb84-6c01-54d6-8423-6fa0cfae671b","source_key":"sample-story-b869fb84-6c01-54d6-8423-6fa0cfae671b","author_id":"01569486-ce98-5f31-919a-f5dea0ad9691","title":"wash cycle","content":"I washed the same bowl three times. Each time I put it down I thought of the alarm and picked it up again. The water had gone grey. Somebody was singing in the next compartment, very badly, and I wanted to go in and tell them to stop but I also didn't want them to stop. It was the only noise that wasn't a machine. I turned the bowl over. There was a crack right through the bottom. I'd been washing a broken bowl for twenty minutes.","starter_sentence":"An ordinary task after a difficult day.","word_count":87,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T08:58:53Z"},{"id":"7bf2f267-dd34-576d-b67e-c7976430c540","source_key":"sample-story-7bf2f267-dd34-576d-b67e-c7976430c540","author_id":"22c04efa-61a1-57ed-a01b-915ca1f789f7","title":"first lap","content":"I ran to the end of the road and had to stop. In my head I was still good at running. My actual body had other ideas. A woman with a buggy went past me, running, and then an old bloke walking quite fast. I walked behind him for a bit pretending that was the plan. At the corner I did another little run. It wasnt much. Got home all sweaty and my son said did you go to the shops. No. Just the corner really. I'll go again Thursday.","starter_sentence":"Do something for the first time in years.","word_count":90,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T10:24:29Z"},{"id":"168a27ce-3734-5074-9fa5-50ed7a22b2a5","source_key":"sample-story-168a27ce-3734-5074-9fa5-50ed7a22b2a5","author_id":"b3202ae3-0a6d-5560-af9b-5751e9f739f0","title":"Aphelion","content":"The potatoes have roots but no idea which way to grow. We turn the trays every morning. Today a root caught the velcro on my sleeve and I dragged the whole plant out. Little white net of roots hanging between me and the tray. Leon helped free it with nail scissors. We put it back in the blue light. Tomorrow I'll try a cage from the mesh over the fans. Might be worse. I don't know enough about potatoes. None of us do. Should have brought a gardener.","starter_sentence":"Describe an ordinary task in an unfamiliar environment.","word_count":88,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T11:08:36Z"},{"id":"0a96f070-a1eb-5859-924c-08557088b29c","source_key":"sample-story-0a96f070-a1eb-5859-924c-08557088b29c","author_id":"dcb01423-22d4-5fdc-8baf-e69da01aac45","title":"one bounce","content":"We were playing one bounce in the car park and Leon said the white line was out. It wasnt out before when his ball went over it. I said fine then the drain is out as well. Soon everyhing was out and we were standing in these little spaces trying not to move our feet. Then the ball went on the roof. We stared at it for ages. Leon found a stick that was like a metre long for a roof about four metres high and tried anyway. I was laughing so so much I didnt see the owner come out, he thought we had been throwing stones and he grabs Leon's arm and I stopped laughing then.","starter_sentence":"A game changes its rules halfway through.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T12:55:57Z"},{"id":"c26a25b1-60d6-5af8-a550-8daa97523ce7","source_key":"sample-story-c26a25b1-60d6-5af8-a550-8daa97523ce7","author_id":"f612a950-8d28-5e22-bd6f-0230e06968ca","title":"terminates here","content":"i woke up with my mouth open and a man tapping my shoulder. train ends here. here was not where i needed to be. i knew that from the trees, too many trees. i got off and the only other person on the platform was a kid with a cello case bigger than her. she asked me where we were. i pointed at the sign and she said no i mean why. like i might know why we'd both fallen asleep. the next train was in fifty minutes. she opened the case and there wasnt a cello just loads of oranges rolling about. i said oh. she said dont ask. i didnt, which is why i still don't have an ending for this.","starter_sentence":"Stay on a train too long.","word_count":123,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T13:31:45Z"},{"id":"5ad50463-1759-503d-b7b2-9e50e70d49fb","source_key":"sample-story-5ad50463-1759-503d-b7b2-9e50e70d49fb","author_id":"2598b274-6761-5cd3-83cf-758fa2d7ed39","title":"A quiet night in","content":"I had plans to do nothing and people don't respect that as a plan. Ben asked if I could help move a wardrobe. I said I was busy. He asked doing what. Nothing. He looked at me. I looked at him. The wardrobe was in the hallway already so this was less a request than an announcement of the next hour of my life. We got it round one corner and it stopped. Not stuck exactly, the walls were touching it on both sides but it could still move backwards, except there was a second wardrobe behind us because he'd bought two. I asked why two. He said they were a set. Of wardrobes. A set. I sat down on the floor in the small triangle of space left beside the first one and opened the film on my phone. He said I wasn't helping. I said that had been my original position and I was pleased we had finally reached an understanding. Then someone rang the doorbell and neither of us could get to it. We ignored it for a while but they kept ringing and I remembered I'd ordered food before all this started.","starter_sentence":"A relaxing evening becomes complicated.","word_count":196,"time_mode":3,"mode":"custom","is_hardcore":true,"created_at":"2026-10-18T14:35:10Z"},{"id":"307dc538-a862-595c-92b8-f752550eebfc","source_key":"sample-story-307dc538-a862-595c-92b8-f752550eebfc","author_id":"4e915f8d-f5e6-5536-bb28-03e5dde5616d","title":"checkout at eleven","content":"He had vomited in the plant pot and offered me twenty pounds to say it was there already. I told him keep the twenty, get a taxi. His friend was asleep against the luggage rack. We got the friend up between us and out through the revolving door, which took longer than it should have. At the kerb the sick one started crying. He said it had been a terrible wedding. I said most of them were by this time. That wasn't a professional thing to say but he laughed. I got their bags in the boot and went back for a bucket. At six the day porter asked if it had been quiet. I said more or less.","starter_sentence":"A night worker finishes a difficult shift.","word_count":119,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T14:39:22Z"},{"id":"506d4849-14a8-520e-904f-bec3557fdce1","source_key":"sample-story-506d4849-14a8-520e-904f-bec3557fdce1","author_id":"a9271dd2-ef3e-5ab5-9bda-6cac641e37a7","title":"the stripe","content":"The stripe on the wall was straight yesterday. Today it bends round the picture. I take the picture down and it bends round my hand instead. It's only paint. I can feel the dry bits where the roller left texture. I put my hand somewhere else. The stripe follows. I want to show somebody but also I want to try drawing a face on the wall first and see if that follows me too. This is probably a terrible idea but I already have the pen.","starter_sentence":"Something familiar looks wrong.","word_count":86,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T15:22:40Z"},{"id":"0d053cf9-5d20-57f2-b284-98aa753890cf","source_key":"sample-story-0d053cf9-5d20-57f2-b284-98aa753890cf","author_id":"dbb43116-e511-5381-9735-ff63919fe690","title":"Not what the packet said","content":"The seedlings all looked the same until one began growing purple underneath. I waited for a second leaf. It was purple too, with a white line down the centre. The packet said lettuce. I know what lettuce looks like at least I think I do. I moved the odd one into its own pot and it wilted immediately, as though the roots had expected company. Put it back and it stayed wilted. There isn't a mysterious plant here, probably just something I introduced in the compost. I wanted to write about a garden that grows things from other people's dreams but now I'm thinking about how many seedlings I've killed by wanting to see the roots. I keep pulling at them to check they're working. That's the scene maybe, someone who can't leave anything alone long enough to know.","starter_sentence":"Something grows where you didn't plant it.","word_count":139,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T15:49:35Z"},{"id":"c7d9f6cc-5aad-529c-b2ff-214466ecd442","source_key":"sample-story-c7d9f6cc-5aad-529c-b2ff-214466ecd442","author_id":"0c31559c-a7de-55f9-b2a9-70c6c0469092","title":"the toll keeper","content":"The bridge wanted a secret. I told it I'd stolen bread. It said everyone stole bread, try harder. I told it I didn't like my brother. It said that wasn't a secret either.\n\nThere was a queue behind me now. People listening. I asked if I could whisper. The bridge said it didn't have ears. How was it hearing me then? It said that was its secret. I stepped off the road and let the next person try. She got across without saying anything I could hear.","starter_sentence":"A bridge demands an unusual payment.","word_count":87,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T16:43:20Z"},{"id":"5af43292-9601-5d97-bc16-488f40d9d6c7","source_key":"sample-story-5af43292-9601-5d97-bc16-488f40d9d6c7","author_id":"316eed8d-f125-5a1b-8346-6d608fb46e5c","title":"The orchard raid","content":"They came in on the west wind with burning nets. Marra lowered the children down the well on the bell rope. She went last. Halfway down she remembered the seed book on the table. Without it they wouldn't know which fruit made you sleep. She couldn't climb back without dragging the children against the wall. She let go. Above them somebody tried the lid. Her son was about to call for help so she covered his mouth. He thought it was his father. She could see him trying to say it.","starter_sentence":"Someone has to choose what to rescue.","word_count":91,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T16:48:37Z"},{"id":"cbce4c6a-a86b-5da4-ba08-1fd12dcd76a8","source_key":"sample-story-cbce4c6a-a86b-5da4-ba08-1fd12dcd76a8","author_id":"3b0adbd3-6e83-579b-a6df-411cae5657a7","title":"station announcement","content":"Attention passengers, the next planet has been cancelled. Not the stop. The planet. Please remain seated while we find somewhere else.\n\nIf you have already checked luggage through to the surface, we suggest not thinking about it for a while. A member of the crew will be along shortly with water. We have quite a lot of water now.","starter_sentence":"A public announcement goes slightly wrong.","word_count":59,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T17:09:11Z"},{"id":"830ea621-f124-5993-8690-7b3a3ee451d0","source_key":"sample-story-830ea621-f124-5993-8690-7b3a3ee451d0","author_id":"3876de02-e048-5457-a0f2-ab02953d0f32","title":"Sunday sleeping","content":"I got home at seven and the neighbour was already washing his car. The hose was across our gate. I stepped over it, caught my heel, nearly went over with my bag. He said morning in a cheerful voice and I said something back that might have been morning. Inside, the flat was too warm. I opened a window then shut it because he had started the pressure washer. Shower, toast, couldn't eat the toast. There was a message from my mother asking if I was coming for lunch. I typed that I'd try. I knew I wouldn't. I lay down with one leg outside the duvet because I couldn't decide if I was hot or cold. The pressure washer stopped and a dog started. Then the dog stopped and somebody began drilling. I laughed into the pillow, one dry breath, not because anything was funny. At eleven I woke up convinced I was late for work. Put one sock on before remembering it was my night off. The toast was still on the plate by the bed with a bite missing. I ate the cold corner while standing there in one sock and read Mum's reply. She'd put a portion aside. I didn't know how to say I was too tired to go and too hungry not to.","starter_sentence":"Rest when the rest of the world is busy.","word_count":219,"time_mode":5,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T17:31:09Z"},{"id":"d7820c05-248e-523f-b69a-b3b37f88a8d3","source_key":"sample-story-d7820c05-248e-523f-b69a-b3b37f88a8d3","author_id":"638df038-a9fa-5be1-bf11-be4fa1d6ce86","title":"Home after the quest","content":"They brought the head home in a sack. New king, old reward no longer valid. Head starting to smell. Teren said another king might buy it. Moth said all kings knew each other. They sat by the horse trough. Sack moved. Teren hit it. Moth said don't, if it's alive it might tell us where the treasure is. They should have thought of that days ago.","starter_sentence":"Return after an adventure.","word_count":66,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T18:09:05Z"},{"id":"04b1caab-38f2-5399-b171-f4a6aff8c142","source_key":"sample-story-04b1caab-38f2-5399-b171-f4a6aff8c142","author_id":"0e7ec6c8-9fbf-50c9-b8cd-ec9c9a43e105","title":"Cutting before leaving","content":"She took cuttings from the hedge because the new owners were going to pull it out. Six cuttings wrapped in wet kitchen roll, then a seventh because one of the first six was bent. The hedge had scratched her face every summer for twenty years. She hated it. That didn't seem to matter now. The man with the van asked if she wanted the cracked pot as well. She said no, then yes, then no because she had no garden at the new place. He put it in anyway. She stood on the path with the cuttings getting warm in her hand and looked at the bare patch where the pot had been. Slugs had made a whole town under it. They were moving slowly into the light, no idea what had happened, and she found herself putting a bit of cardboard down for them.","starter_sentence":"Save a piece of something you cannot keep.","word_count":145,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T19:18:14Z"},{"id":"777505c4-3df9-521a-9ec8-d24d84c897eb","source_key":"sample-story-777505c4-3df9-521a-9ec8-d24d84c897eb","author_id":"6427a72f-fc9d-5ce7-a87b-7d2db571c983","title":"Three cups","content":"i put three cups out because i didn't know if he was bringing her. then two because why would he bring her. then three again because having the cup already there might make me look like the sort of person who was fine with it. i wasn't fine with anything that morning. the flat was too clean in the wrong places, i'd cleaned the skirting boards but there was a pile of underwear on the chair. i shoved it in the oven. dont ask. cupboard was full. i forgot about it until i decided to warm the pastries and then there was this horrible hot elastic smell and i had to open every window. so when he arrived i was standing in a coat in my own kitchen holding a tray of warm pants. he was alone. he looked at the tray then at me and for a second we were both trying so hard not to laugh that i thought maybe things could just go back. then he said he'd only come for the documents. i said i know. i did know. i put the tray down very carefully on the hob and went to get the envelope from the hall. it wasn't where i'd left it. i'd moved everything everything when i was cleaning and now i had to ask him to wait while i looked, which was the exact thing i had been trying not to ask.","starter_sentence":"Prepare for a visitor you are nervous about.","word_count":240,"time_mode":5,"mode":"custom","is_hardcore":false,"created_at":"2026-10-18T21:31:54Z"},{"id":"61708b2e-f6c4-59be-a5cb-6842fc997a90","source_key":"sample-story-61708b2e-f6c4-59be-a5cb-6842fc997a90","author_id":"0b4f9787-dc5c-5e47-ba2a-09ff695b34ac","title":"the first shop","content":"Bought too much because I didn't know how far the walk back was. Bags cutting my fingers, eggs underneath everything. A man offered help. I said no then yes. He carried the heavy bag to my building and asked which floor. Said third, remembered it's fourth here. Third was the old place. He waited for me to find keys. Inside I ate yoghurt with the lid folded up. Spoons still packed. Not an interesting story but my first night. He was called Dan I think. Should remember that.","starter_sentence":"Write about moving somewhere new.","word_count":88,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-19T02:41:47Z"},{"id":"0e8fd503-5c37-5e04-b132-1d86e81a2ebd","source_key":"sample-story-0e8fd503-5c37-5e04-b132-1d86e81a2ebd","author_id":"d7866188-9db8-52b5-bc17-abc99c5a47ba","title":"voice note","content":"it wasn't even the worst recording on my phone which is what i keep trying to explain. The worst one is me practising how to say happy birthday without sounding like I had practised. This one was just forty seconds of me complaining about the birthday dinner. To the birthday person. no wait to the GROUP with the birthday person in it, so worse actually. I held my thumb on the message and the phone offered to save it. why would i want to save it. preserve it for my children. By the time I found delete she'd sent a voice note back. I put the phone under a cushion so I couldnt see the length of it. My brother came in and sat on the cushion and now the thing was playing into his leg and I could hear her laughing but not what she was saying","starter_sentence":"I sent the wrong recording.","word_count":148,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"12e9f4e0-3181-5c98-820b-41291f00d814","source_key":"sample-story-12e9f4e0-3181-5c98-820b-41291f00d814","author_id":"3b608dd1-8159-5317-a916-27e58f6b5b9d","title":"Tank six","content":"Tank six reports ninety litres more than yesterday. No intake recorded. No neighbouring tank shows a loss. I checked the sensor with a bucket and a marked stick, as instructed. The stick came back dry. The bucket came back full. Requesting a second bucket. Also requesting that whoever writes the instructions stop adding exclamation marks after the word simple. Update: the sample is salt water. We do not carry salt water. I have covered the inspection window because something on the other side is following the torch.","starter_sentence":"The reading had changed overnight.","word_count":87,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"1af20da5-9f40-5dd0-a43e-e15143f3b3ed","source_key":"sample-story-1af20da5-9f40-5dd0-a43e-e15143f3b3ed","author_id":"c960b079-39f4-539f-9939-09bb823740ee","title":"The last hook","content":"The brass hook was screwed into the back of the bedroom door. She had hung a school bag there, then a towel, then nothing for several years. Her mother watched her test it with two fingers. It wouldn't turn. In the car her husband was making room for the last box. She could hear the boot opening and closing. Her mother went to the kitchen and returned with a screwdriver, the small one with a cracked yellow handle. She put it on the windowsill and left without asking what it was for.","starter_sentence":"She had already packed everything useful.","word_count":92,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"24cb4af3-4e23-5633-9a98-92205d216561","source_key":"sample-story-24cb4af3-4e23-5633-9a98-92205d216561","author_id":"757950cd-75de-5f59-ba49-d64a93bf4bcd","title":"Last carriage","content":"A wet umbrella stood against the empty seat. At each station it leaned toward the open door, then straightened when the doors closed. I moved my bag so there would be room beside it.","starter_sentence":"The rain stopped at the door.","word_count":34,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c","source_key":"sample-story-280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c","author_id":"7b440e7a-5591-56ba-83cc-fc217b347ada","title":"the good pen","content":"borrowed a pen for the exam and it was one of those with four colours so obviously i spent the first minute deciding which blue was more serious. there was only one blue. other button was purple. wrote my NAME in purple before discovering this and now i looked like someone with a whole personality instead of someone who had revised on the bus. first question: discuss. Discuss WHAT i wanted to ask, emotionally. i clicked the black button and the entire spring came out. guy beside me caught it without looking up. honestly most impressive thing anyone did in that room","starter_sentence":"I had brought everything except the important thing.","word_count":102,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"421c3e6c-2642-5939-b117-5713eec9d2a3","source_key":"sample-story-421c3e6c-2642-5939-b117-5713eec9d2a3","author_id":"a4e73876-53a0-54d4-8be6-31ff102ddabe","title":"The passenger","content":"I said forty kilometres. He said good. Put his sack in the back and got in. After ten minutes the sack crowed. I looked at him. He looked out the window. At the next village he paid for two passengers. I gave him change for one.","starter_sentence":"He asked if I was going far.","word_count":46,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"42ee0c93-45b0-5483-ad98-6262a37c87d3","source_key":"sample-story-42ee0c93-45b0-5483-ad98-6262a37c87d3","author_id":"4cb8da3a-5049-5c9e-ae8a-734f593e0b87","title":"The vine","content":"The vine has reached the upstairs window. You said it would if I stopped cutting it. I stopped because the ladder broke, so you can be right for the wrong reason. There are grapes but they're small and the birds get there first. I moved your chair into the shade. The leg still needs fixing. Everyone who visits chooses the other chair even when I tell them this one's safe. I don't know why I keep telling them. Your brother came on Tuesday with a bag of screws, none of them the right size. We drank tea standing up. He asked if I wanted him to take the chair away and I said I was sitting in it. I wasn't. He didn't say anything about that.","starter_sentence":"There was something I had forgotten to tell you.","word_count":126,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"43f2cb27-9e70-59ed-9e2a-0480b381d294","source_key":"sample-story-43f2cb27-9e70-59ed-9e2a-0480b381d294","author_id":"8d394b17-0d66-52ab-a18e-b41d5c61b265","title":"Apricots","content":"Potatoes first. Then onions because they're cheaper at the other end, though you spend the saving walking there. Bought apricots I hadn't planned on. The man gave me one to try and stood watching while I ate it. Hard to say no with your mouth full. By the bus stop one bag handle had stretched into a string. Swapped hands every twenty steps. At home my daughter counted the apricots into a bowl. Seventeen. She wanted to know who got the extra one. I said me, carrying fee. She cut it into three pieces because her mother was coming home later. Mine was mostly stone. I ate it standing up while she explained the division again. Apparently I had misunderstood.","starter_sentence":"The bag weighed more than it should have.","word_count":120,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"4a6db8ef-c566-590d-9c29-219be4b91e1c","source_key":"sample-story-4a6db8ef-c566-590d-9c29-219be4b91e1c","author_id":"a5b516db-9000-59d2-b4e5-34ae6288fd48","title":"Not her wedding","content":"She said she wasn't coming which everyone took personally, but I thought she meant the photographer. She was pointing at his car. Or the car behind his car. Anyway by the time it reached our table it was the groom who wasn't coming and somebody had started putting the salads back in the fridge. I told them don't do that, you don't know anything yet. Neither did I but I was holding a plate so I looked involved. The bride came out in slippers and asked why her uncle was crying. He said happy tears. He'd been saying the marriage was a mistake thirty seconds before. Then the photographer arrived carrying a tyre and she said SEE. I still don't understand what that proved but we all went back for the salads.","starter_sentence":"I only heard half the conversation.","word_count":132,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"4ac02c70-f34c-5ee9-a3a0-fe5eea638875","source_key":"sample-story-4ac02c70-f34c-5ee9-a3a0-fe5eea638875","author_id":"bce314a6-b6c0-517e-8519-b2b1289ea16e","title":"Below the ridge","content":"My left sock had worked its way under my heel. I kept stopping to pull it up and my sister kept pretending to look at the view. When we reached the snow she went ahead. I watched her boots make two neat holes, two more. Mine slid sideways. Wind got under my coat and pushed it against my back. I wanted to say we should turn round but she had already sat down to untie her boots. She handed me one of her socks. Hers were much too big. We went another fifty metres before either of us spoke.","starter_sentence":"We were nearly at the top.","word_count":99,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"4bc23cd7-05be-5ff9-a591-8fa0cd313623","source_key":"sample-story-4bc23cd7-05be-5ff9-a591-8fa0cd313623","author_id":"d7117dcb-cf9f-5fc7-9a99-7f5ffc586ffb","title":"One free minute","content":"Buy one hour, get one minute free. I asked what kind of hour. Any kind, said the shopkeeper, except an hour you have already used. I bought an hour of sleep. He gave me an hour of waiting for sleep. I complained. You were in bed, he said. I asked for my free minute. He handed me a small paper bag. Inside was the minute before I had entered his shop. I used it to walk past. He came running after me asking for the bag back.","starter_sentence":"The shopkeeper offered me a bargain.","word_count":87,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"4e30ddcc-9a23-5b98-87f9-a378e19676bb","source_key":"sample-story-4e30ddcc-9a23-5b98-87f9-a378e19676bb","author_id":"0d1e3567-fc38-5476-9d1b-d1506407e589","title":"The blue bowl","content":"\"You put it in the fridge.\" \"Why would I put an empty bowl in the fridge?\" \"I don't know why you do most things.\" My sister was still holding the spoon, pointing it into cupboards like she could detect porcelain with it. I said maybe she'd taken it to work. She said she hadn't worked there since February. Right. I knew that. I was trying to remember whether I had said anything else about work since she got here. The kettle clicked off and neither of us moved. \"There's the green one,\" I said. \"I know there's the green one.\" She opened the fridge. The blue bowl was inside, under a plate, full of the cherries I'd saved for her. \"Oh,\" she said. I told her she could wash them herself, I wasn't doing everything.","starter_sentence":"Someone had moved the only thing I needed.","word_count":135,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"532c513e-a1f6-55cc-8214-f54eabaf69bd","source_key":"sample-story-532c513e-a1f6-55cc-8214-f54eabaf69bd","author_id":"1c86406f-0ed6-51e0-a81e-08001b901bbb","title":"The oranges","content":"Take the oranges out of the plastic bag before you go in. The bag makes too much noise. Don't ask if she's tired. She'll say no and keep talking until she is. Pull the chair close enough that she doesn't have to raise her voice. Not that close, you're on the tube. When she asks about the garden tell her the truth about the roses and lie about the weeds. Peel an orange. She'll say she doesn't want it. Leave one piece on the napkin beside her hand. Talk about the bus, the rain, anything that happened outside. When she falls asleep stay until the piece of orange is gone or until","starter_sentence":"They told me the visit had to be short.","word_count":112,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"5622ce7d-4fea-5083-b98d-6f9da059bf57","source_key":"sample-story-5622ce7d-4fea-5083-b98d-6f9da059bf57","author_id":"c01828e7-2a62-56df-b08d-df4139dbce03","title":"What came back","content":"Returned: two mugs, one drill, the red blanket. Not returned: extension lead, three books, the lid for the big saucepan. In the drill case I found a photograph from the day we put the shelves up. Both of us covered in plaster dust. The shelves had fallen down before dinner because we'd used the wrong plugs and we'd eaten on the floor underneath the holes, laughing so much I thought the neighbour would knock. I added the photograph to the list. Crossed it out. Put the lidless saucepan on top of everything and carried it upstairs.","starter_sentence":"We counted the boxes twice.","word_count":96,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"71003911-e4e7-5aa2-b110-9cb9dfede361","source_key":"sample-story-71003911-e4e7-5aa2-b110-9cb9dfede361","author_id":"4e278577-2b14-5dbf-9d79-acacd25506ba","title":"Eight millimetres","content":"The new bolt was eight millimetres too long. I had measured it with the nut still on, which is something I would laugh at anyone else for doing. Cut it down. Couldn't get the nut back over the cut end. Filed it. Too much. By lunchtime the bicycle was in more pieces than when I started. My son asked if we were still going to the canal. I said bring your shoes. We walked the bicycle there. He rode it down the slope with his feet out and I carried the pedals in my pocket.","starter_sentence":"The replacement part almost fit.","word_count":95,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"78e52dc9-e3ee-574c-885e-f5cfef1f1757","source_key":"sample-story-78e52dc9-e3ee-574c-885e-f5cfef1f1757","author_id":"69b1ca7b-7919-5593-9644-3ab1b8eb14e1","title":"The warm side","content":"I turned the pillow over. The other side was warm too. I stood up. On the mattress, the hollow where I'd been lying began to deepen. Slowly, as though someone much heavier was settling into the space. I reached for the lamp and felt","starter_sentence":"The room looked exactly as I had left it.","word_count":44,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"7cc36beb-809a-5641-b612-ba819eee47fe","source_key":"sample-story-7cc36beb-809a-5641-b612-ba819eee47fe","author_id":"72714dea-7aef-5a4a-8fd7-ad9f7a20e4aa","title":"NOT our cat","content":"found the cat!! carried him upstairs like a baby despite his opinions on this and rang mum to say stop looking. she said the cat is here. I said no he isnt he's in my ARMS. she said then who's eating tuna in my kitchen. looked down. this cat had a white foot. ours has no white feet. how many times have i looked at my own cat?? apparently not enough. tried taking him back down but he'd got comfortable and now i was the unreasonable one. downstairs there was a woman shaking a bag of treats and crying and i went over holding him out like an apology with legs. she hugged the cat then me then said he never lets strangers pick him up. great. exceptional talent discovered at last. accidental cat theft","starter_sentence":"I was so relieved that I forgot to check.","word_count":135,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"7d056d4b-f699-5c60-8fd6-47400de9c2b0","source_key":"sample-story-7d056d4b-f699-5c60-8fd6-47400de9c2b0","author_id":"72801aaa-6c97-50f4-9640-48b16ec4b073","title":"The spoon rule","content":"I'm not against rules. I have rules. For example do not use my mug to grow an avocado. Apparently that was unreasonable because the avocado had roots already and moving it would cause stress. The avocado lives in my mug. I drink from a measuring jug. But now there's a rule about teaspoons, specifically that each person gets two, and I want to know who counted them because there were nine yesterday and there are four of us. Who has the ninth spoon. Is it communal. Is it for the avocado. Nobody will answer this directly. They say this is why we need a house meeting. I say a house meeting should require chairs and somebody has put all the chairs on the balcony to dry after washing them for reasons that were also not discussed","starter_sentence":"There was a new note on the fridge.","word_count":136,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"834ba1a7-bbf8-5e89-ab41-583268f83300","source_key":"sample-story-834ba1a7-bbf8-5e89-ab41-583268f83300","author_id":"61179e3d-48ee-5367-9c5f-272ac8085853","title":"Spin cycle","content":"the small grey cloud came out with the towels, i thought it was steam until it followed me to the balcony. shook the towel and it rained on my feet. well fine. put a bowl under it. it floated away from the bowl because apparently even weather can be difficult before breakfast. My neighbour leaned over and said hers had done that when she used too much powder. She had a whole thunderstorm in the spare room once. I asked how she got rid of it and she said she didnt, her son liked the noise for sleeping. The cloud settled over my basil. By evening the basil looked better than it had in months so I left the window open a crack, just enough for it to come in if it wanted","starter_sentence":"There was something alive in the laundry.","word_count":133,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"92051503-a911-51cf-a81c-af15a891cbc2","source_key":"sample-story-92051503-a911-51cf-a81c-af15a891cbc2","author_id":"78699f80-eb9e-515c-9609-6540e7adf2e0","title":"Undo","content":"a button that takes you back ten seconds but only the last ten seconds you enjoyed. so if you're having a terrible day it might send you back to breakfast. wait that isn't ten seconds backwards thats selecting a memory isn't it. ok it takes your BODY there. you're thirty and suddenly sitting in a tiny chair at your seventh birthday and everyone screams except your grandmother who just moves the cake knife out of your reach. She says you've come back then. I think she knows how it works. I think she's been doing this for years which explains why she always knew when the doorbell was about to go. But where does seven year old you go. there are two of you and only one party hat and","starter_sentence":"The button only worked once.","word_count":130,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"92a2f050-386c-5c10-9358-d154b7271020","source_key":"sample-story-92a2f050-386c-5c10-9358-d154b7271020","author_id":"a6c99e39-f8d7-5e97-8741-8515787a7f27","title":"Application for shade","content":"1. Bring proof that the tree is yours. A photograph of yourself standing beside it will not count. Anyone can stand beside a tree.\n2. Bring the tree, if possible.\n3. If not possible, bring a letter from the tree explaining why.\nI asked the woman behind the glass whether a leaf would do. She considered this seriously enough that I became hopeful. A leaf with a signature, she said. I went outside. The tree was still there, shading four people who had not applied for anything. I put the form against the trunk to write on it and a pigeon deposited something beside the signature box. Back inside she said the stamp was in the wrong place.","starter_sentence":"The office needed one more document.","word_count":118,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"9d3523a2-e9c1-5de4-af22-c8c2886e259f","source_key":"sample-story-9d3523a2-e9c1-5de4-af22-c8c2886e259f","author_id":"2fee657f-01df-5589-9703-afda3541f074","title":"Curtain rail","content":"The first hole was fine. Second one hit something that made a noise I didn't recognise. Turned the drill off. Noise continued. Turned the radio off. Still going. It was my neighbour on the other side, drilling back. We met in the corridor holding identical drills like a very disappointing duel. He said he'd been putting up shelves. I said curtain rail. We compared the holes through his wall. Mine was higher. I felt pleased about that for no reason at all. Then his wife came out with the little bag of wall plugs we'd both forgotten to use.","starter_sentence":"I said it would take ten minutes.","word_count":99,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"b3541f10-6597-5063-83ff-4dc8657a12a7","source_key":"sample-story-b3541f10-6597-5063-83ff-4dc8657a12a7","author_id":"81e0836c-79de-575e-99f3-0d29fbb949aa","title":"Two coats and a goal","content":"Look it was in. Your coat was the post and the ball went inside your coat. Then you picked your coat up because a car was coming and apparently the goal moved with it. I have never heard of that rule. We were four two up anyway, or four three if we're counting the one off the dog which I said we shouldn't. Everyone was shouting and the little kid from the second floor walked right between us with a bottle of water. He poured two lines on the ground. There. Posts. We all looked at them. Actually quite sensible. We started again and within five minutes one line had dried before the other so now we had a completely diffrent argument. I was goalkeeper this time. I'm telling you the sun was on their side.","starter_sentence":"We disagreed about where the line was.","word_count":136,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"c03efad1-cd94-58d6-b40f-420566e91060","source_key":"sample-story-c03efad1-cd94-58d6-b40f-420566e91060","author_id":"b0addcb6-0723-5073-9710-41fb3486c732","title":"A little more water","content":"Auntie said a glass of water but her glass was that thick old one with the flowers and mine was much bigger, so already we had a problem. Add flour till it's right she said over the phone. What does right look like. You know. I didn't know, that was the purpose of calling. My daughter pushed one finger into it and the whole bowl followed her hand up. Too wet, auntie said when I described this. More flour. Then more water because now it was a brick. We were making enough for a wedding by this point and there were three of us eating. I put the phone on the counter and heard auntie laughing with somebody in her kitchen. I wanted to be annoyed but I wanted to be in her kitchen more. My daughter was making a very small animal out of dough. She said it was me.","starter_sentence":"Nobody had written down the recipe.","word_count":151,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"d705be98-eab8-58ef-adad-4ea565974e46","source_key":"sample-story-d705be98-eab8-58ef-adad-4ea565974e46","author_id":"682e8ef3-1e0e-5dab-b653-3b53a1f35608","title":"next door","content":"three notes then the chair scraping. every evening. i know where the fourth note goes now, i hum it while washing up. tonight somebody else is playing, all the way through, very well. i leave the tap running so i can't hear how well.","starter_sentence":"The music stopped halfway through.","word_count":44,"time_mode":1,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"e499097b-cd67-5140-a5c8-1068367e31bc","source_key":"sample-story-e499097b-cd67-5140-a5c8-1068367e31bc","author_id":"f353f630-d0c7-55ec-b980-d6a969560c1c","title":"The end seat","content":"She put her shopping on the end seat and kept looking at the door. The café filled. A man asked if the chair was taken and she said yes, quickly, then moved one bag to her lap as though that made it more convincing. I brought her another glass of water. She asked what time we closed. Four. Plenty of time, she said. At ten to four a woman in a cycling helmet came in and stood beside the chair. Neither smiled. The bags went on the floor. I was wiping the counter when I heard one of them say, I didn't know if you'd still be here. I left the cloth where it was and went to find something to do in the kitchen.","starter_sentence":"She saved a place for someone who wasn't there.","word_count":125,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"ea6b3334-245d-5bd4-805e-1da1cd1f4212","source_key":"sample-story-ea6b3334-245d-5bd4-805e-1da1cd1f4212","author_id":"fc425770-e917-5a6d-acc8-ca8daa11fc1b","title":"Platform photograph","content":"The boy's sleeve was caught under his mother's suitcase handle. He could have pulled it out. He stayed leaning sideways instead, one shoulder lower than the other. Behind them a man folded a newspaper into smaller and smaller squares without reading it. The train hadn't arrived. I lifted the camera. The boy looked straight at me and tucked his free hand into the trapped sleeve. In the photograph it looks as though his mother is holding him. Her own hands are both in her pockets.","starter_sentence":"Only one person noticed the camera.","word_count":85,"time_mode":2,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"f31e254d-7a3f-5857-9e8a-e60d067842da","source_key":"sample-story-f31e254d-7a3f-5857-9e8a-e60d067842da","author_id":"09dc47a1-b470-5bdd-b915-41d527a6b0f3","title":"Landing","content":"Three flights up. The sound stayed one flight ahead although I was taking the stairs two at a time. At the next landing I stopped. It stopped too. Pipes, I thought. There were pipes along the ceiling. I went up backwards watching the empty flight below because somehow that seemed the sensible thing to do. My heel hit something soft. A shopping bag, tied at the handles. Warm bread inside, I could smell it through the plastic. Whoever had left it was standing behind the fire door. I could see the edge of a shoe under it. \"You dropped this.\" The shoe moved back. The light went off. I knew the switch was beside the door but I couldn't remember which side.","starter_sentence":"There were footsteps above me.","word_count":122,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"f3374cfe-c941-5c98-86b5-e22367a66c35","source_key":"sample-story-f3374cfe-c941-5c98-86b5-e22367a66c35","author_id":"5b0eeceb-76d5-583d-bed0-39afe01504fb","title":"The wrong village","content":"The important thing about that holiday was the cheese, although my wife says it was getting lost with no fuel, but we had some fuel, the light was only orange. We stopped in a village where a man was repairing a chair outside his shop and I asked him the way with the map upside down, which he politely turned round before telling me we were on the wrong side of the mountain. He gave us cheese while he explained. Very good cheese. I asked where to buy it and he said his brother made it and went inside to call him. My wife was in the car looking at the petrol light. The brother came on a motorbike with a whole wheel under his arm. We had to put it on her lap. She says this is the part of the story I should start with.","starter_sentence":"We took the turning with the broken sign.","word_count":147,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"},{"id":"faa87a38-75da-516e-b01a-4a9a5f77e111","source_key":"sample-story-faa87a38-75da-516e-b01a-4a9a5f77e111","author_id":"eca9f8e7-f8b7-558f-8207-481485400330","title":"Number 46","content":"Forty four. So I have time to work out what to say. Hello, I booked online. No obviously I booked online they have the booking. Just hello. Forty five goes in carrying a folder and I havent brought a folder. Was there a folder requirement. I look at the email again but the screen rotates and now it's huge and I can't find the bit with my name. A woman comes out and smiles at me in a way that might mean it's my turn or might just mean she is a person who smiles. I half stand. She walks past. Sit. The chair makes that noise. Everyone has heard the chair. Now I need to explain the chair before I can explain why I'm here. Forty six. I stand up properly and say sorry to the man who called my number. Haven't done anything yet. Already sorry.","starter_sentence":"My number was almost next.","word_count":148,"time_mode":3,"mode":"custom","is_hardcore":false,"created_at":"2026-10-23T04:02:37.023318+00:00"}]$collection$::jsonb) AS imported(id uuid, source_key text, author_id uuid, title text, content text, starter_sentence text, word_count integer, time_mode integer, mode text, is_hardcore boolean, created_at timestamptz)
ON CONFLICT (id) DO UPDATE SET author_id = EXCLUDED.author_id, title = EXCLUDED.title, content = EXCLUDED.content, starter_sentence = EXCLUDED.starter_sentence, word_count = EXCLUDED.word_count, time_mode = EXCLUDED.time_mode, mode = EXCLUDED.mode, is_hardcore = EXCLUDED.is_hardcore, created_at = EXCLUDED.created_at;

UPDATE public.sample_profiles p SET total_stories = (SELECT count(*) FROM public.sample_stories s WHERE s.author_id=p.id AND NOT s.is_hidden), total_words = (SELECT coalesce(sum(word_count),0) FROM public.sample_stories s WHERE s.author_id=p.id AND NOT s.is_hidden);

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM public.sample_profiles s JOIN public.profiles r
             ON lower(s.username) = lower(r.username)) THEN
    RAISE EXCEPTION 'A sample handle conflicts with an existing account; import rolled back';
  END IF;
  IF (SELECT count(*) FROM public.sample_profiles) < 150 OR
     (SELECT count(*) FROM public.sample_stories) < 390 THEN
    RAISE EXCEPTION 'Unexpected collection counts; import rolled back';
  END IF;
END $$;

COMMIT;

SELECT (SELECT count(*) FROM public.sample_profiles) AS imported_profiles, (SELECT count(*) FROM public.sample_stories) AS imported_stories, (SELECT count(*) FROM public.profiles) AS real_profiles, (SELECT count(*) FROM public.stories) AS real_stories;
